import sys
import unicodedata


# -----------------------------------------------------------------------------
# Fonction : ent65_remove_accents
# Rôle : Supprime les accents pour faciliter les comparaisons textuelles sans modifier la logique clinique.
# -----------------------------------------------------------------------------
def ent65_remove_accents(text):
    if text is None:
        return ''
    text = unicodedata.normalize('NFD', str(text))
    return ''.join((char for char in text if unicodedata.category(char) != 'Mn'))


# -----------------------------------------------------------------------------
# Fonction : ent65_normalize_text
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def ent65_normalize_text(text):
    """
    Normalisation uniquement pour les contrôles internes.
    La valeur retournée dans `name` conserve autant que possible
    la forme textuelle originale.
    """
    if text is None:
        return ''
    text = str(text).strip().lower()
    text = ent65_remove_accents(text)
    text = text.replace('’', "'")
    text = text.replace('`', "'")
    text = text.replace('_', ' ')
    text = re.sub('(?<=\\d),(?=\\d)', '.', text)
    text = re.sub('\\s+', ' ', text)
    return text.strip()


# -----------------------------------------------------------------------------
# Fonction : ent65_clean_parameter_for_name
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def ent65_clean_parameter_for_name(parametre):
    """
    Transforme seulement la forme technique :
      creatinine -> creatinine
      bilirubine_conjuguee -> bilirubine conjuguee
      proteine_C_reactive -> proteine C reactive

    Aucune connaissance médicale n'est ajoutée.
    """
    if parametre is None:
        return ''
    text = str(parametre).strip()
    text = text.replace('_', ' ')
    text = re.sub('\\s+', ' ', text)
    return text.strip()


# -----------------------------------------------------------------------------
# Fonction : ent65_format_value
# Rôle : Formate une valeur numérique de manière stable pour construire une mention canonique.
# -----------------------------------------------------------------------------
def ent65_format_value(value):
    """
    Format stable des valeurs numériques.

    76.0 -> 76
    0.48 -> 0.48
    """
    if value is None:
        return ''
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if value.is_integer():
            return str(int(value))
        return format(value, '.15g')
    return str(value).strip()


# -----------------------------------------------------------------------------
# Fonction : ent65_value_variants
# Rôle : Génère les variantes décimales possibles d'une valeur afin de retrouver sa forme dans la preuve.
# -----------------------------------------------------------------------------
def ent65_value_variants(value):
    if value is None:
        return []
    raw = ent65_format_value(value)
    variants = {raw, raw.replace('.', ','), raw.replace(',', '.')}
    return [item for item in variants if item]


# -----------------------------------------------------------------------------
# Fonction : ent65_proof_contains_value
# Rôle : Vérifie que la valeur numérique de l'entité est réellement présente dans la preuve textuelle.
# -----------------------------------------------------------------------------
def ent65_proof_contains_value(proof, value):
    if not proof or value is None:
        return False
    proof_norm = ent65_normalize_text(proof)
    return any((ent65_normalize_text(v) in proof_norm for v in ent65_value_variants(value)))


# -----------------------------------------------------------------------------
# Fonction : ent65_compact_measurement_from_proof
# Rôle : Extrait une fenêtre textuelle compacte autour d'une mesure afin de conserver une frontière NER utile.
# -----------------------------------------------------------------------------
def ent65_compact_measurement_from_proof(proof, value=None, unit=None, max_tokens_before=5, max_length=100):
    """
    Essaie de conserver la mention textuelle réelle.

    Exemples :
      "CRP (u.s.) 36.9" -> "CRP (u.s.) 36.9"
      "Albumine 22 g/L" -> "Albumine 22 g/L"

    Si la preuve est une longue phrase, récupère une petite fenêtre
    autour de la valeur.
    """
    if proof is None:
        return ''
    proof = str(proof).strip()
    if not proof:
        return ''
    if len(proof.split()) <= 8 and len(proof) <= max_length and (value is None or ent65_proof_contains_value(proof, value)):
        return proof
    if value is None:
        return proof if len(proof) <= max_length else ''
    variants = ent65_value_variants(value)
    match = None
    matched_value = None
    for variant in variants:
        current = re.search(re.escape(variant), proof, flags=re.IGNORECASE)
        if current:
            match = current
            matched_value = variant
            break
    if match is None:
        return ''
    left_text = proof[:match.start()]
    tokens = list(re.finditer('\\S+', left_text))
    start = tokens[-max_tokens_before].start() if len(tokens) >= max_tokens_before else 0
    end = match.end()
    if unit:
        tail = proof[end:]
        unit_match = re.match('\\s*' + re.escape(str(unit)), tail, flags=re.IGNORECASE)
        if unit_match:
            end += unit_match.end()
    result = proof[start:end].strip(' \t\r\n,;:-')
    return result


# -----------------------------------------------------------------------------
# Fonction : ent65__find_literal_parameter_surface
# Rôle : Recherche dans la preuve la forme réellement écrite du paramètre biologique.
# -----------------------------------------------------------------------------
def ent65__find_literal_parameter_surface(proof, parametre):
    """
    Cherche dans la preuve la forme réellement écrite du paramètre.
    """
    if not proof or not parametre:
        return ''
    proof = str(proof)
    aliases = {'proteine_C_reactive': ['CRP (u.s.)', 'CRP', 'protéine C réactive', 'proteine C reactive'], 'procalcitonine': ['Procalcitonine (PCT)', 'Procalcitonine', 'PCT'], 'creatinine': ['Créatinine', 'Creatinine', 'créat', 'creat'], 'uree': ['Urée', 'Uree'], 'bilirubine_totale': ['Bilirubine totale'], 'bilirubine_conjuguee': ['Bilirubine conjuguée', 'Bilirubine conjuguee'], 'globules_blancs': ['Globules blancs', 'Leucocytes', 'GB'], 'polynucleaires_neutrophiles': ['Polynucléaires neutrophiles', 'PNN'], 'hemoglobine': ['Hémoglobine', 'Hemoglobine', 'Hb'], 'hematocrite': ['Hématocrite', 'Hematocrite'], 'plaquettes': ['Plaquettes'], 'sodium': ['Sodium', 'Natrémie', 'Natremie'], 'potassium': ['Potassium', 'Kaliémie', 'Kaliemie'], 'chlorure': ['Chlorure', 'Chlorures'], 'calcium': ['Calcium', 'Calcémie', 'Calcemie'], 'phosphate': ['Phosphate', 'Phosphore'], 'magnesium': ['Magnésium', 'Magnesium'], 'glycemie': ['Glycémie', 'Glycemie', 'Glucose'], 'ASAT': ['ASAT'], 'ALAT': ['ALAT'], 'gamma_GT': ['Gamma GT', 'Gamma-GT', 'GGT'], 'phosphatases_alcalines': ['Phosphatases alcalines', 'PAL'], 'LDH': ['LDH'], 'CPK': ['CPK', 'CK'], 'albumine': ['Albumine'], 'protides': ['Protides', 'Protéines', 'Proteines'], 'TP': ['TP', 'TQ', 'Temps de Quick'], 'TCA': ['TCA'], 'fibrinogene': ['Fibrinogène', 'Fibrinogene'], 'D_dimeres': ['D-dimères', 'D dimeres', 'D-dimères'], 'pH_arteriel': ['pH/T° patient', 'pH artériel', 'pH'], 'PaO2': ['pO2/T° patient', 'PaO2', 'pO2'], 'PaCO2': ['pCO2/T° patient', 'PaCO2', 'pCO2'], 'bicarbonates': ['Bicarbonate', 'Bicarbonates'], 'CO2_total': ['CO2 total', 'CO2 Total'], 'rapport_PaO2_FiO2': ['PaO2/FiO2', 'P/F'], 'lactate': ['Lactate', 'Lactates']}
    candidates = aliases.get(str(parametre), [str(parametre).replace('_', ' ')])
    for candidate in sorted(candidates, key=len, reverse=True):
        m = re.search(re.escape(candidate), proof, flags=re.IGNORECASE)
        if m:
            return proof[m.start():m.end()]
    return ''


# -----------------------------------------------------------------------------
# Fonction : ent65__compact_biomarker_name_v63
# Rôle : Construit un nom compact de biomarqueur à partir du paramètre et de la valeur patient.
# -----------------------------------------------------------------------------
def ent65__compact_biomarker_name_v63(entity):
    """
    V6.3 :
      nom = PARAMETRE LITTERAL + VALEUR PATIENT
    et jamais l'intervalle de référence.

    Exemple :
      "LDH 213 85-227 U/L" -> "LDH 213"
    """
    proof = str(entity.get('preuve') or entity.get('name') or '').strip()
    parametre = entity.get('parametre')
    value = entity.get('valeur')
    surface = ent65__find_literal_parameter_surface(proof, parametre)
    if value is not None:
        value_text = ent65_format_value(value)
        variants = [value_text, value_text.replace('.', ','), value_text.replace(',', '.')]
        value_surface = ''
        for variant in variants:
            m = re.search('(?<!\\d)' + re.escape(variant) + '(?!\\d)', proof, flags=re.IGNORECASE)
            if m:
                value_surface = proof[m.start():m.end()]
                break
        if surface and value_surface:
            return f'{surface} {value_surface}'.strip()
        if surface:
            return f'{surface} {value_text}'.strip()
    if surface:
        return surface
    p = ent65_clean_parameter_for_name(parametre)
    if value is not None:
        return f'{p} {ent65_format_value(value)}'.strip()
    return p


# -----------------------------------------------------------------------------
# Fonction : ent65__compact_treatment_name_v63
# Rôle : Extrait le nom du traitement ou de la procédure depuis la preuve textuelle.
# -----------------------------------------------------------------------------
def ent65__compact_treatment_name_v63(entity):
    proof = str(entity.get('preuve') or entity.get('name') or '').strip()
    specific = entity.get('nom_medicament') or entity.get('nom_traitement') or entity.get('nom_intervention')
    terms = [specific, 'Vénofer IV', 'Véinofer IV', 'Vénofer', 'Véinofer', 'Tardyferon', 'Tardiyferon', 'Primpéran', 'Primperan', 'Lasilix', 'lasilix', 'Vancomycine', 'vancomycine', 'tienam', 'Tazocilline', 'Claforan', 'Amiklin', 'amikacine', 'amykacine', 'Augmentin', 'augmentin', 'amoxicilline', 'noradrénaline', 'adrénaline', 'insuline rapide', 'NPH', 'Lovenox', 'LOVENOX', 'Acupan', 'VNI', 'BIPAP', 'kinésithérapie', 'oxygénothérapie', 'Oxygène', 'oxygène', 'ventilation mécanique', 'intubation', 'intubé', 'extubation', 'trachéotomie', 'tracheotomie', 'gastrostomie', 'anticoagulation', 'transfusion', 'restriction hydrique', 'remplissage vasculaire', 'réduction par choc', 'rééducation', 'extractions dentaires', 'diurétiques', 'aérosols', 'Normacol', 'immunoglobulines']
    for term in sorted({str(t) for t in terms if t}, key=len, reverse=True):
        m = re.search(re.escape(term), proof, flags=re.IGNORECASE)
        if m:
            return proof[m.start():m.end()]
    return str(specific or proof).strip()


# -----------------------------------------------------------------------------
# Fonction : ent65__compact_symptom_name_v63
# Rôle : Extrait une mention compacte de symptôme depuis la preuve textuelle.
