# -----------------------------------------------------------------------------
# Fonction : ent65__compact_service_name_v63
# Rôle : Extrait la mention du service médical et élimine certaines formulations non pertinentes.
# -----------------------------------------------------------------------------
def ent65__compact_service_name_v63(entity):
    proof = str(entity.get('preuve') or entity.get('name') or '').strip()
    terms = ['notre réanimation', 'Raymond Poincaré', 'Salpétrière', 'Salpêtrière', 'réanimation', 'Garches', 'Foch', 'SSR', 'urgences']
    for term in sorted(terms, key=len, reverse=True):
        m = re.search(re.escape(term), proof, flags=re.IGNORECASE)
        if m:
            return proof[m.start():m.end()]
    n = ent65_normalize_text(proof)
    if 'clinique d admission' in n or 'clinique d’admission' in proof.lower() or 'clinique respiratoire' in n or ('clinique retrouve' in n) or ('clinique est' in n):
        return ''
    return proof


# -----------------------------------------------------------------------------
# Fonction : ent65__compact_posology_name_v63
# Rôle : Extrait une posologie compacte à l'aide de motifs numériques et d'unités.
# -----------------------------------------------------------------------------
def ent65__compact_posology_name_v63(entity):
    proof = str(entity.get('preuve') or entity.get('name') or '').strip()
    patterns = ['\\b\\d+(?:[.,]\\d+)?\\s*[àa]\\s*\\d+(?:[.,]\\d+)?\\s*mg/h\\b', '\\b\\d+(?:[.,]\\d+)?\\s*/\\s*\\d+(?:[.,]\\d+)?\\s*mg/h(?:\\s+de\\s+NA)?\\b', '\\bFiO2\\s*[:=]?\\s*\\d+(?:[.,]\\d+)?\\s*%', "\\bPEEP\\s*[:=]?\\s*\\d+(?:[.,]\\d+)?(?:\\s*cm\\s*(?:H2O|d['’]eau))?", '\\b\\d+(?:[.,]\\d+)?\\s*L/min\\b', '\\b\\d+\\s*jours?\\b', '\\b\\d+(?:[.,]\\d+)?\\s*(?:mg|g|µg|mcg|ug|UI|U)\\b', '\\b\\d+\\s*/\\s*j\\b']
    for pattern in patterns:
        m = re.search(pattern, proof, flags=re.IGNORECASE)
        if m:
            return m.group(0).strip()
    for field in ('schema_horaire_brut', 'duree_traitement'):
        value = entity.get(field)
        if value:
            return str(value).strip()
    return proof


# -----------------------------------------------------------------------------
# Fonction : ent65_build_canonical_entity_name
# Rôle : Construit le nom canonique d'une entité en fonction de sa catégorie.
# -----------------------------------------------------------------------------
def ent65_build_canonical_entity_name(entity, include_unit=False):
    """
    V6.3 : canonicalisation orientée matching.
    Sépare la représentation ontologique de la frontière NER.
    """
    if not isinstance(entity, dict):
        return ''
    categorie = str(entity.get('categorie') or entity.get('type') or '').strip()
    if categorie == 'BIOMARQUEUR':
        return ent65__compact_biomarker_name_v63(entity)
    if categorie == 'SIGNE_VITAL':
        return ent65__compact_biomarker_name_v63(entity)
    if categorie == 'TRAITEMENT':
        return ent65__compact_treatment_name_v63(entity)
    if categorie == 'SYMPTOME':
        return ent65__compact_symptom_name_v63(entity)
    if categorie == 'SERVICE_MEDICAL':
        return ent65__compact_service_name_v63(entity)
    if categorie == 'POSOLOGIE':
        return ent65__compact_posology_name_v63(entity)
    if categorie == 'MICRO_ORGANISME':
        value = entity.get('nom_micro_organisme') or entity.get('nom_microorganisme') or entity.get('nom')
        return str(value or entity.get('name') or entity.get('preuve') or '').strip()
    if categorie == 'COMORBIDITE_ANTECEDENT':
        value = entity.get('nom_comorbidite') or entity.get('nom_antecedent') or entity.get('nom_pathologie') or entity.get('nom')
        return str(value or entity.get('name') or entity.get('preuve') or entity.get('parametre') or '').strip()
    if categorie == 'IMAGERIE_PROCEDURE':
        value = entity.get('nom_procedure') or entity.get('nom_examen') or entity.get('nom')
        return str(value or entity.get('name') or entity.get('preuve') or entity.get('parametre') or '').strip()
    existing = str(entity.get('name') or '').strip()
    if existing:
        return existing
    preuve = str(entity.get('preuve') or '').strip()
    if preuve:
        return preuve
    return ent65_clean_parameter_for_name(entity.get('parametre'))


# -----------------------------------------------------------------------------
# Fonction : ent65_canonicalize_entity
# Rôle : Canonicalise une entité : normalise son nom et son type sans supprimer les autres informations du JSON.
# -----------------------------------------------------------------------------
def ent65_canonicalize_entity(entity, include_unit=False):
    """
    Ne détruit PAS les champs du JSON original.
    Ajoute / met à jour uniquement :
      name
      type
    """
    if not isinstance(entity, dict):
        return entity
    result = dict(entity)
    categorie = result.get('categorie') or result.get('type') or ''
    result['name'] = ent65_build_canonical_entity_name(result, include_unit=include_unit)
    result['type'] = str(categorie).strip()
    return result


# -----------------------------------------------------------------------------
# Fonction : ent65_canonicalize_document
# Rôle : Applique la canonicalisation à toutes les entités d'un document.
# -----------------------------------------------------------------------------
def ent65_canonicalize_document(document_json, include_unit=False):
    """
    Supporte :
      pages[].entities
      pages[].entites
      global_entities
      entities
    """
    if not isinstance(document_json, dict):
        return document_json
    output = dict(document_json)
    pages = output.get('pages')
    if isinstance(pages, list):
        new_pages = []
        for page in pages:
            if not isinstance(page, dict):
                new_pages.append(page)
                continue
            page_copy = dict(page)
            field = None
            if isinstance(page_copy.get('entities'), list):
                field = 'entities'
            elif isinstance(page_copy.get('entites'), list):
                field = 'entites'
            if field:
                page_copy[field] = [ent65_canonicalize_entity(entity, include_unit=include_unit) for entity in page_copy[field] if isinstance(entity, dict)]
            new_pages.append(page_copy)
        output['pages'] = new_pages
    for field in ('global_entities', 'global_entites'):
        if isinstance(output.get(field), list):
            output[field] = [ent65_canonicalize_entity(entity, include_unit=include_unit) for entity in output[field] if isinstance(entity, dict)]
    return output


# -----------------------------------------------------------------------------
# Fonction : ent65_canonicalize_folder
# Rôle : Applique la canonicalisation à tous les JSON d'un dossier.
# -----------------------------------------------------------------------------
def ent65_canonicalize_folder(input_dir, output_dir, include_unit=False):
    os.makedirs(output_dir, exist_ok=True)
    for old_file in os.listdir(output_dir):
        if old_file.lower().endswith('.json'):
            old_path = os.path.join(output_dir, old_file)
            try:
                os.remove(old_path)
                print(f'🗑️ Ancienne sortie supprimée : {old_file}')
            except OSError as exc:
                print(f'⚠️ Impossible de supprimer {old_file}: {exc}')
    files = sorted((f for f in os.listdir(input_dir) if f.lower().endswith('.json')))
    print(f'📚 {len(files)} JSON détecté(s)')
    for index, filename in enumerate(files, start=1):
        source = os.path.join(input_dir, filename)
        destination = os.path.join(output_dir, filename)
        with open(source, 'r', encoding='utf-8') as f:
            data = json.load(f)
        canonical = ent65_canonicalize_document(data, include_unit=include_unit)
        with open(destination, 'w', encoding='utf-8') as f:
            json.dump(canonical, f, ensure_ascii=False, indent=2)
        print(f'✅ {index}/{len(files)} : {filename}')


# -----------------------------------------------------------------------------
# Fonction : ent65_ntext
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def ent65_ntext(value):
    return ent65_normalize_text(value)


# -----------------------------------------------------------------------------
# Fonction : ent65__literal_regex
# Rôle : Exécute une recherche regex littérale dans le texte.
# -----------------------------------------------------------------------------
def ent65__literal_regex(text, pattern):
    return list(re.finditer(pattern, text or '', flags=re.IGNORECASE))


# -----------------------------------------------------------------------------
# Fonction : ent65__entity_surface
# Rôle : Récupère la mention textuelle principale d'une entité.
# -----------------------------------------------------------------------------
def ent65__entity_surface(entity):
    return str(entity.get('preuve') or entity.get('name') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : ent65__surface_start
# Rôle : Retrouve la position de début d'une mention dans le texte.
# -----------------------------------------------------------------------------
def ent65__surface_start(entity, text):
    start = entity.get('_surface_start')
    if isinstance(start, int):
        return start
    surface = ent65__entity_surface(entity)
    if not surface or not text:
        return -1
    m = re.search(re.escape(surface), text, flags=re.IGNORECASE)
    return m.start() if m else -1


# -----------------------------------------------------------------------------
# Fonction : ent65_reclassify_v65
# Rôle : Corrige certains types d'entités à partir de règles explicites.
# -----------------------------------------------------------------------------
def ent65_reclassify_v65(entity):
    if not isinstance(entity, dict):
        return entity
    result = dict(entity)
    surface = ent65__entity_surface(result)
    norm = ent65_ntext(surface)
    category = str(result.get('categorie') or result.get('type') or '').strip()
    rules = [('^sinusite chronique$', 'FOYER_INFECTIEUX'), ('^hyperglycemie$', 'BIOMARQUEUR'), ('^pic febrile a \\d', 'SIGNE_VITAL'), ('^leucoencephalopathie(?: evoluee)?$', 'LABEL_NOSOLOGIQUE'), ('^deglobulisation$', 'DEFAILLANCE_ORGANE'), ('^hypoxemie$', 'DEFAILLANCE_ORGANE'), ('^hepato\\s*\\(?splenomegalie\\)?$', 'SYMPTOME'), ('^capacite vitale a \\d', 'BIOMARQUEUR'), ('^traumatisme du genou', 'SYMPTOME'), ('^trouble cognitif majeur$', 'SYMPTOME'), ('^decompensation respiratoire$', 'DEFAILLANCE_ORGANE'), ('^episode septique$', 'LABEL_NOSOLOGIQUE'), ('^thrombopenie$', 'LABEL_NOSOLOGIQUE'), ('^hypertension arterielle labile$', 'LABEL_NOSOLOGIQUE'), ('^deficit sensitivomoteur complet', 'DEFAILLANCE_ORGANE'), ('^pas de signe de lutte respiratoire$', 'SYMPTOME'), ('^hepatopathie chronique$', 'COMORBIDITE_ANTECEDENT'), ('^lacune ischemique', 'LABEL_NOSOLOGIQUE'), ('^hypoglycemies?$', 'LABEL_NOSOLOGIQUE'), ('^chimiotherapie adjuvante', 'TRAITEMENT'), ('^hemicolectomie droite', 'TRAITEMENT'), ('^appendicectomie', 'TRAITEMENT'), ('^demineralisation des interphalangiennes', 'COMORBIDITE_ANTECEDENT')]
    for pattern, target in rules:
        if re.search(pattern, norm):
            category = target
            break
    if 'hematome de la cuisse' in norm and 'spontan' not in norm:
        category = 'SYMPTOME'
    result['categorie'] = category
    result['type'] = category
    return result


# -----------------------------------------------------------------------------
# Fonction : ent65_keep_entity_v65
# Rôle : Décide si une entité doit être conservée ou supprimée selon des règles de précision.
# -----------------------------------------------------------------------------
def ent65_keep_entity_v65(entity):
    if not isinstance(entity, dict):
        return False
    category = str(entity.get('categorie') or entity.get('type') or '').strip()
    surface = ent65__entity_surface(entity)
    norm = ent65_ntext(surface)
    if not surface:
        return False
    if category == 'SERVICE_MEDICAL':
        bad = ('clinique d admission', 'clinique respiratoire', 'clinique retrouve', 'clinique est par la suite', 'clinique il est transfere', 'clinique est transfere')
        if any((x in norm for x in bad)):
            return False
        if norm == 'urgence':
            return False
    if category == 'EVOLUTION_PRONOSTIC':
        markers = ('ameliore', 'amelioration', 'aggrave', 'aggravation', 'degradation', 'normalis', 'sevre', 'sevrage', 'recuper', 'favorable', 'deces', 'reprise', 'regression', 'mobilisation', 'station au fauteuil', 'diminution', 'augmentation', 'repondant', 'plateau', 'complication', 'evolu')
        if not any((x in norm for x in markers)):
            return False
        if any((x in norm for x in ('risque de sepsis', 'probabilite', 'sirs significatif', 'sirs eleve'))):
            return False
    if category == 'IMAGERIE_PROCEDURE':
        if any((x in norm for x in ('granulome apical', 'prothese mandibulaire', 'gaz du sang'))):
            return False
    if category == 'CONTEXTE_ACQUISITION':
        if not any((x in norm for x in ('nosocom', 'communaut', 'acquis', 'hospital', 'institution', 'domicile', 'multiresistant', 'multiresistante'))):
            return False
    return True


# -----------------------------------------------------------------------------
# Fonction : ent65__longest_match
# Rôle : Sélectionne la correspondance regex la plus longue afin de conserver la mention la plus informative.
# -----------------------------------------------------------------------------
def ent65__longest_match(proof, patterns):
    best = ''
    for pattern in patterns:
        for m in re.finditer(pattern, proof, flags=re.IGNORECASE):
            candidate = proof[m.start():m.end()].strip()
            if len(candidate) > len(best):
                best = candidate
    return best


# -----------------------------------------------------------------------------
# Fonction : ent65_canonical_name_v65
# Rôle : Construit le nom canonique d'une entité en fonction de sa catégorie.
# -----------------------------------------------------------------------------
def ent65_canonical_name_v65(entity):
    category = str(entity.get('categorie') or entity.get('type') or '').strip()
    proof = ent65__entity_surface(entity)
    if not proof:
        return ''
    if category in {'BIOMARQUEUR', 'SIGNE_VITAL'}:
        if len(proof) <= 130:
            return proof
        return ent65_build_canonical_entity_name(entity, include_unit=True)
    if category == 'TRAITEMENT':
        patterns = ['\\bVNI\\s+diurne\\s+et\\s+nocturne(?:\\s+puis\\s+uniquement\\s+nocturne)?\\b', '\\bVNI\\s+nocturne\\b', '\\bventilation\\s+BIPAP\\b', '\\bventilation\\s+protectrice\\b', "\\bpose\\s+d['’]un\\s+PM\\b", '\\bSonde\\s+naso\\s*gastrique\\b', '\\bremplissage\\s+vasculaire\\b', '\\bdrainage\\s+respiratoire\\b', '\\bkin[eé]sith[eé]rapie\\s+respiratoire\\b', '\\b(?:Oxyg[eè]ne|oxyg[eé]noth[eé]rapie)\\b', '\\bantibioth[eé]rapie\\b', '\\ba[eé]rosols?\\b', '\\bEx[eé]r[eè]se\\s+chirurgicale(?:\\s+le\\s+\\d{1,2}[./-]\\d{1,2}[./-]\\d{2,4})?\\b', '\\bH[eé]micolectomie\\s+droite(?:\\s+le\\s+\\d{1,2}[./-]\\d{1,2}[./-]\\d{2,4})?\\b', "\\bAppendicectomie\\s+dans\\s+l['’]enfance\\b", '\\bChimioth[eé]rapie\\s+adjuvante\\s+par\\s+Folfox\\s+en\\s+attente\\b', '\\b(?:Tazocilline|Tardiyferon|Tardyferon|tienam|Tienam|Ipratropium|Bud[eé]sonide|Normacol|vancomycine|Vancomycine|Augmentin|Amiklin|Claforan)\\b']
        best = ent65__longest_match(proof, patterns)
        if best:
            return best
        return ent65__compact_treatment_name_v63(entity)
    if category == 'SYMPTOME':
        if len(proof) <= 150:
            return proof
        return ent65__compact_symptom_name_v63(entity)
    if category == 'POSOLOGIE':
        patterns = ['\\b\\d+(?:[.,]\\d+)?g/\\d+(?:[.,]\\d+)?mg\\s+PO\\s+\\d-\\d-\\d\\s+pendant\\s+\\d+\\s+jours(?:\\s*\\(J\\d+/\\d+\\))?\\b', '\\b\\d+(?:[.,]\\d+)?\\s*(?:mg|g|UI)\\s*/\\s*\\d+(?:[.,]\\d+)?\\s*mL\\s+SC\\s+la\\s+nuit\\b', '\\b\\d+(?:[.,]\\d+)?\\s*mg/\\d+(?:[.,]\\d+)?mL\\s+PO\\s+si\\s+besoin\\b', '\\b\\d+(?:[.,]\\d+)?\\s*mg\\s+PO\\s+si\\s+besoin\\b', '\\b\\d+(?:[.,]\\d+)?\\s*g\\s*[xX]\\s*\\d+\\s*/\\s*[jJ]\\b', '\\b\\d+(?:[.,]\\d+)?\\s*[xX]\\s*\\d+\\s*/\\s*[jJ]\\b', '\\b\\d+(?:[.,]\\d+)?\\s*g\\s*[xX]\\s*\\d+\\s+par\\s+jour\\b', '\\b\\d-\\d-\\d\\s+si\\s+besoin\\b', '\\b\\d+(?:[.,]\\d+)?\\s*[àa]\\s*\\d+(?:[.,]\\d+)?\\s*mg/h\\b', '\\bdur[eé]e\\s+totale\\s+de\\s+\\d+\\s+jours\\b', '\\bsaturation\\s+\\d{2,3}\\s*[-–]\\s*\\d{2,3}\\s*%\\b', '\\b\\d+\\s*L\\s*O2\\b', '\\b\\d+\\s*/\\s*j\\s+depuis\\s+[^\\n,;.]+\\b', '\\bFiO2\\s*[:=]?\\s*\\d+(?:[.,]\\d+)?\\s*%\\b', '\\bPEEP\\s*[:=]?\\s*\\d+(?:[.,]\\d+)?(?:\\s*cm\\s*H2O)?\\b']
        best = ent65__longest_match(proof, patterns)
        if best:
            return best
        return ent65__compact_posology_name_v63(entity)
    if category == 'COMORBIDITE_ANTECEDENT':
        if len(proof) <= 150:
            return proof
    if category == 'IMAGERIE_PROCEDURE':
        if len(proof) <= 120:
            return proof
    if category == 'EVOLUTION_PRONOSTIC':
        patterns = ["\\b(?:La|L['’])\\s*fonction\\s+respiratoire\\s+s['’]am[eé]liore\\b", "\\b(?:L['’])?encombrement\\s+bronchique\\s+s['’]am[eé]liore\\b", "\\bprogressivement\\s+sevr[eé]\\s+de\\s+l['’]oxyg[eè]ne\\b", "\\bs['’]aggrave\\s+progressivement\\b", "\\bL['’][eé]volution\\s+clinique\\s+est\\s+par\\s+la\\s+suite\\s+favorable\\b", '\\bmobilisation\\s+des\\s+4\\s+membres\\s+possible\\b', '\\bStation\\s+au\\s+fauteuil\\s+plusieurs\\s+heures\\b', "\\breprise\\s+de\\s+l['’]alimentation\\b", "\\bReprise\\s+d['’]une?\\s+alimentation\\s+normale\\b", '\\bd[eé]c[eè]s\\s+du\\s+patient\\b']
        best = ent65__longest_match(proof, patterns)
        if best:
            return best
        if len(proof) <= 120:
            return proof
    if category == 'SERVICE_MEDICAL':
        return ent65__compact_service_name_v63(entity)
    if category in {'LABEL_NOSOLOGIQUE', 'DEFAILLANCE_ORGANE', 'FOYER_INFECTIEUX', 'MICRO_ORGANISME', 'SCORE_NEUROLOGIQUE'}:
        if len(proof) <= 150:
            return proof
    return ent65_build_canonical_entity_name(entity, include_unit=True)


# -----------------------------------------------------------------------------
# Fonction : ent65_make_added
# Rôle : Construit la structure JSON d'une nouvelle entité ajoutée par le post-traitement.
# -----------------------------------------------------------------------------
def ent65_make_added(category, proof, start, page_number, counter, **extra):
    ent = {'identifiant_entite': f'P{page_number}_V65_{counter:03d}', 'categorie': category, 'type': category, 'preuve': proof, 'name': proof, 'nie': False, 'confiance': 'elevee', 'type_inference': 'extraction_directe', '_surface_start': start, '_surface_end': start + len(proof), '_v65_added': True}
    ent.update(extra)
    return ent


# -----------------------------------------------------------------------------
# Fonction : ent65_augment_entities_v65
# Rôle : Recherche dans le texte brut des motifs cliniques ciblés et complète la liste d'entités.
# -----------------------------------------------------------------------------
def ent65_augment_entities_v65(entities, text, page_number):
    if not isinstance(entities, list):
        entities = []
    if not text:
        return entities
    out = [dict(e) for e in entities if isinstance(e, dict)]
    existing = set()
    for ent in out:
        surf = ent65__entity_surface(ent)
        existing.add((str(ent.get('categorie') or ent.get('type') or ''), ent65_ntext(surf), ent65__surface_start(ent, text)))
    specs = {'SYMPTOME': ['\\bencombrement\\s+bronchique\\s+franc\\b', "\\b(?:l['’])?encombrement\\s+bronchique\\b", '\\bencombrement\\s+[àa]\\s+r[eé]p[eé]tition\\b', '\\b(?:[eé]pisodes?\\s+de\\s+)?d[eé]saturations?\\s+[àa]\\s+r[eé]p[eé]tition\\b', '\\btirage\\s+sus[-\\s]?claviculaire\\b', '\\btoux\\s+inefficace\\b', '\\btoux\\s+grasse\\s+moyennement\\s+efficace\\b', '\\bmalaise\\s+syncopal\\b', '\\bprobables?\\s+pertes?\\s+de\\s+connaissance\\b', '\\bampliation\\s+thoracique\\s+faible\\b', "\\balt[eé]ration\\s+de\\s+l['’]?[eé]tat\\s+g[eé]n[eé]ral\\b", '\\bh[eé]patospl[eé]nom[eé]galie\\b', "\\bpas\\s+d['’]h[eé]patospl[eé]nom[eé]galie\\b", '\\bBHA\\s+pr[eé]sents?\\b', '\\bcontexte\\s+f[eé]brile\\b', '\\bmasse\\s+(?:palpable|palp[eé]e)\\b', '\\bpas\\s+de\\s+douleur\\s+thoracique\\b', '\\bROT\\s+rotulien\\s+droit\\s+per[cç]u\\b'], 'TRAITEMENT': ["\\bpose\\s+d['’]un\\s+PM\\b", '\\bVNI\\s+nocturne\\b', '\\bVNI\\s+diurne\\s+et\\s+nocturne(?:\\s+puis\\s+uniquement\\s+nocturne)?\\b', '\\bventilation\\s+BIPAP\\b', '\\bventilation\\s+protectrice\\b', '\\bSonde\\s+naso\\s*gastrique\\b', '\\bremplissage\\s+vasculaire\\b', '\\bdrainage\\s+respiratoire\\b', '\\b(?:Oxyg[eè]ne|oxyg[eé]noth[eé]rapie)\\b', '\\bantibioth[eé]rapie\\b', '\\ba[eé]rosols?\\b', '\\b(?:Tazocilline|Tardiyferon|Tardyferon|tienam|Tienam|Ipratropium|Bud[eé]sonide|Normacol|vancomycine|Vancomycine|Augmentin)\\b'], 'BIOMARQUEUR': ['\\bFEVG\\s+(?:mesur[eé]e\\s+[àa]\\s+)?\\d+(?:[.,]\\d+)?\\s*%', '\\bGB\\s*=\\s*\\d[\\d\\s]*(?:/\\s*mm3)?\\b', '\\bcr[eé]at(?:inine)?\\s+(?:de\\s+base\\s+)?\\d+(?:[.,]\\d+)?\\s*µ?mol\\s*/\\s*[lL]\\b', '\\bur[eé]e\\s+\\d+(?:[.,]\\d+)?\\s*mmol\\s*/\\s*[lL]\\b', '\\bnatr[eé]mie(?:\\s+est\\s+mesur[eé]e\\s+[àa])?\\s+\\d+(?:[.,]\\d+)?\\s*mmol\\s*/\\s*[lL]\\b', '\\b(?:pCO2|pO2)/T°\\s+patient\\s+\\d+(?:[.,]\\d+)?\\b', '\\bLactate\\s+plasmatique\\s+\\d+(?:[.,]\\d+)?\\b', '\\bCortisol\\s+T(?:0|60)\\s+min\\s+\\d+(?:[.,]\\d+)?\\b', '\\bRatio\\s+Patient\\s*/\\s*T[eé]moin\\s+\\d+(?:[.,]\\d+)?\\b', '\\bTP\\s+[àa]\\s+\\d+(?:[.,]\\d+)?\\s*%\\b', '\\bcapacit[eé]\\s+vitale\\s+[àa]\\s+\\d+(?:[.,]\\d+)?\\s*%\\b'], 'SIGNE_VITAL': ['\\bFC\\s*\\(bpm\\)\\s*:\\s*:?[ ]*\\d{2,3}\\b', '\\bFR\\s*\\(c/mn\\)\\s*:\\s*\\d{1,3}\\b', '\\bTRC\\s*[<>]\\s*\\d+(?:[.,]\\d+)?\\s*(?:s|sec)\\b', '\\bTemp[eé]rature\\s+patient\\s+\\d{2}(?:[.,]\\d+)?(?:\\s+°?C)?\\b', '\\bpic\\s+f[eé]brile\\s+[àa]\\s+\\d{2}(?:[.,]\\d+)?\\b'], 'IMAGERIE_PROCEDURE': ['\\bscanner\\s+cervico[-\\s]?thoracique\\b', '\\bscanner\\s+c[eé]r[eé]bral(?:\\s+r[eé]alis[eé]\\s+est\\s+normal)?\\b', '\\bTDM\\s+thoracique\\b', '\\bIRM\\s+m[eé]dullaire\\b', '\\bEMG\\s+r[eé]alis[eé]\\s+le\\s+\\d{1,2}[./-]\\d{1,2}[./-]\\d{2,4}\\b', '\\bEEG\\s+est\\s+r[eé]alis[eé]\\s+le\\s+\\d{1,2}[./-]\\d{1,2}[./-]\\d{2,4}\\b', "\\bPonction\\s+d['’]ascite\\b", '\\bColoscopie\\b', '\\bh[eé]moc\\s+p[eé]rih\\s+et\\s+centrale\\b', '\\bECU\\b'], 'POSOLOGIE': ['\\b\\d+(?:[.,]\\d+)?\\s*g\\s*[xX]\\s*\\d+\\s*/\\s*[jJ]\\b', '\\b\\d+(?:[.,]\\d+)?\\s*[xX]\\s*\\d+\\s*/\\s*[jJ]\\b', '\\b\\d+(?:[.,]\\d+)?\\s*g\\s*[xX]\\s*\\d+\\s+par\\s+jour\\b', '\\b\\d+(?:[.,]\\d+)?\\s*(?:mg|g|UI)\\s*/\\s*\\d+(?:[.,]\\d+)?\\s*mL\\s+SC\\s+la\\s+nuit\\b', '\\b\\d+(?:[.,]\\d+)?\\s*mg\\s+PO\\s+si\\s+besoin\\b', '\\b\\d-\\d-\\d\\s+si\\s+besoin\\b', '\\b\\d+(?:[.,]\\d+)?\\s*[àa]\\s*\\d+(?:[.,]\\d+)?\\s*mg/h\\b', '\\bdur[eé]e\\s+totale\\s+de\\s+\\d+\\s+jours\\b', '\\b\\d+\\s*L\\s*O2\\b', '\\bsaturation\\s+\\d{2,3}\\s*[-–]\\s*\\d{2,3}\\s*%\\b'], 'EVOLUTION_PRONOSTIC': ["\\b(?:La|L['’])\\s*fonction\\s+respiratoire\\s+s['’]am[eé]liore\\b", "\\b(?:L['’])?encombrement\\s+bronchique\\s+s['’]am[eé]liore\\b", "\\bprogressivement\\s+sevr[eé]\\s+de\\s+l['’]oxyg[eè]ne\\b", "\\bs['’]aggrave\\s+progressivement\\b", "\\bL['’][eé]volution\\s+clinique\\s+est\\s+par\\s+la\\s+suite\\s+favorable\\b", '\\bmobilisation\\s+des\\s+4\\s+membres\\s+possible\\b', '\\bStation\\s+au\\s+fauteuil\\s+plusieurs\\s+heures\\b', "\\breprise\\s+de\\s+l['’]alimentation\\b", '\\bd[eé]c[eè]s\\s+du\\s+patient\\b']}
    counter = 1 + sum((1 for e in out if e.get('_v65_added')))
    for category, patterns in specs.items():
        for pattern in patterns:
            for m in re.finditer(pattern, text, flags=re.IGNORECASE):
                proof = text[m.start():m.end()]
                if category == 'TRAITEMENT' and ent65_ntext(proof) in {'oxygene', 'oxygenotherapie'}:
                    left_ctx = ent65_ntext(text[max(0, m.start() - 50):m.start()])
                    if 'sevr' in left_ctx:
                        continue
                key = (category, ent65_ntext(proof), m.start())
                if key in existing:
                    continue
                out.append(ent65_make_added(category, proof, m.start(), page_number, counter))
                existing.add(key)
                counter += 1
    return out


# -----------------------------------------------------------------------------
# Fonction : ent65_drop_nested_short_same_offset
# Rôle : Supprime une mention courte lorsqu'une mention plus longue du même type couvre la même occurrence.
# -----------------------------------------------------------------------------
def ent65_drop_nested_short_same_offset(entities):
    drop = set()
    for i, a in enumerate(entities):
        if not isinstance(a, dict):
            continue
        ca = str(a.get('categorie') or a.get('type') or '')
        na = ent65_ntext(a.get('name') or a.get('preuve') or '')
        sa = a.get('_surface_start')
        if not na or not isinstance(sa, int):
            continue
        for j, b in enumerate(entities):
            if i == j or not isinstance(b, dict):
                continue
            cb = str(b.get('categorie') or b.get('type') or '')
            nb = ent65_ntext(b.get('name') or b.get('preuve') or '')
            sb = b.get('_surface_start')
            if ca != cb or sa != sb or (not nb):
                continue
            if len(na) < len(nb) and na in nb and (ca in {'POSOLOGIE', 'IMAGERIE_PROCEDURE', 'TRAITEMENT', 'SYMPTOME'}):
                drop.add(i)
    return [ent for index, ent in enumerate(entities) if index not in drop]


# -----------------------------------------------------------------------------
# Fonction : ent65_dedup_exact_occurrence_v65
# Rôle : Supprime les doublons en conservant une seule représentation de chaque élément.
# -----------------------------------------------------------------------------
def ent65_dedup_exact_occurrence_v65(entities):
    out = []
    seen = set()
    for ent in entities:
        if not isinstance(ent, dict):
            continue
        category = str(ent.get('categorie') or ent.get('type') or '')
        name = ent65_ntext(ent.get('name') or ent.get('preuve') or '')
        start = ent.get('_surface_start')
        start_key = start if isinstance(start, int) else None
        key = (category, name, start_key)
        generic_key = (category, name, None)
        if name:
            if key in seen or generic_key in seen:
                continue
            if start_key is None and any((k[0] == category and k[1] == name for k in seen)):
                continue
        seen.add(key)
        out.append(ent)
    return out


# -----------------------------------------------------------------------------
# Fonction : ent65_canonicalize_one_v65
# Rôle : Canonicalise une entité : normalise son nom et son type sans supprimer les autres informations du JSON.
# -----------------------------------------------------------------------------
def ent65_canonicalize_one_v65(entity):
    if not isinstance(entity, dict):
        return entity
    result = ent65_reclassify_v65(entity)
    if not ent65_keep_entity_v65(result):
        result = dict(result)
        result['name'] = ''
        return result
    result['name'] = ent65_canonical_name_v65(result)
    result['type'] = str(result.get('categorie') or result.get('type') or '').strip()
    return result


# -----------------------------------------------------------------------------
# Fonction : ent65_canonicalize_document_v65
# Rôle : Applique la canonicalisation à toutes les entités d'un document.
# -----------------------------------------------------------------------------
def ent65_canonicalize_document_v65(document_json):
    if not isinstance(document_json, dict):
        return document_json
    output = copy.deepcopy(document_json)
    pages = output.get('pages')
    if isinstance(pages, list):
        new_pages = []
        for page in pages:
            if not isinstance(page, dict):
                new_pages.append(page)
                continue
            page_copy = dict(page)
            page_number = page_copy.get('page')
            text = str(page_copy.get('texte_brut') or '')
            field = None
            if isinstance(page_copy.get('entities'), list):
                field = 'entities'
            elif isinstance(page_copy.get('entites'), list):
                field = 'entites'
            if field:
                enriched = ent65_augment_entities_v65(page_copy[field], text, page_number)
                canonical = [ent65_canonicalize_one_v65(ent) for ent in enriched if isinstance(ent, dict)]
                canonical = [ent for ent in canonical if str(ent.get('name') or '').strip()]
                canonical = ent65_drop_nested_short_same_offset(canonical)
                canonical = ent65_dedup_exact_occurrence_v65(canonical)
                page_copy[field] = canonical
            new_pages.append(page_copy)
        output['pages'] = new_pages
    for field in ('global_entities', 'global_entites'):
        if isinstance(output.get(field), list):
            output[field] = [ent65_canonicalize_one_v65(ent) for ent in output[field] if isinstance(ent, dict)]
            output[field] = [ent for ent in output[field] if str(ent.get('name') or '').strip()]
    return output


# -----------------------------------------------------------------------------
# Fonction : ent65_canonicalize_folder_v65
# Rôle : Applique la canonicalisation à tous les JSON d'un dossier.
# -----------------------------------------------------------------------------
def ent65_canonicalize_folder_v65(input_dir, output_dir):
    os.makedirs(output_dir, exist_ok=True)
    for old in os.listdir(output_dir):
        if old.lower().endswith('.json'):
            try:
                os.remove(os.path.join(output_dir, old))
            except OSError:
                pass
    files = sorted((f for f in os.listdir(input_dir) if f.lower().endswith('.json')))
    print(f'📚 V6.5 : {len(files)} JSON détecté(s)')
    print(f'📥 INPUT  : {input_dir}')
    print(f'📤 OUTPUT : {output_dir}')
    for index, filename in enumerate(files, start=1):
        source = os.path.join(input_dir, filename)
        destination = os.path.join(output_dir, filename)
        with open(source, 'r', encoding='utf-8') as f:
            data = json.load(f)
        result = ent65_canonicalize_document_v65(data)
        with open(destination, 'w', encoding='utf-8') as f:
            json.dump(result, f, ensure_ascii=False, indent=2)
        print(f'✅ {index}/{len(files)} : {filename}')
    print('\n🏁 Canonicalisation V6.5 SELECTIVE PRECISION terminée.')

