# -----------------------------------------------------------------------------
# Fonction : ent66b_remove_accents
# Rôle : Supprime les accents pour faciliter les comparaisons textuelles sans modifier la logique clinique.
# -----------------------------------------------------------------------------
def ent66b_remove_accents(value):
    value = '' if value is None else str(value)
    value = unicodedata.normalize('NFD', value)
    return ''.join((char for char in value if unicodedata.category(char) != 'Mn'))


# -----------------------------------------------------------------------------
# Fonction : ent66b_normalize
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def ent66b_normalize(value):
    value = ent66b_remove_accents(value).lower()
    value = value.replace('’', "'").replace('`', "'").replace('\xa0', ' ')
    value = re.sub('\\s+', ' ', value).strip()
    return value


# -----------------------------------------------------------------------------
# Fonction : ent66b_entity_id
# Rôle : Récupère l'identifiant d'une entité de manière compatible avec plusieurs formats JSON.
# -----------------------------------------------------------------------------
def ent66b_entity_id(entity):
    return str(entity.get('identifiant_entite') or entity.get('id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : ent66b_entity_type
# Rôle : Récupère la catégorie/type d'une entité.
# -----------------------------------------------------------------------------
def ent66b_entity_type(entity):
    return str(entity.get('categorie') or entity.get('type') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : ent66b_entity_surface
# Rôle : Récupère la mention textuelle principale d'une entité.
# -----------------------------------------------------------------------------
def ent66b_entity_surface(entity):
    return str(entity.get('preuve') or entity.get('name') or entity.get('nom') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : ent66b_set_entity_type
# Rôle : Récupère la catégorie/type d'une entité.
# -----------------------------------------------------------------------------
def ent66b_set_entity_type(entity, category):
    entity['categorie'] = category
    entity['type'] = category


# -----------------------------------------------------------------------------
# Fonction : ent66b_set_entity_surface
# Rôle : Récupère la mention textuelle principale d'une entité.
# -----------------------------------------------------------------------------
def ent66b_set_entity_surface(entity, surface):
    entity['preuve'] = surface
    entity['name'] = surface


# -----------------------------------------------------------------------------
# Fonction : ent66b_clean_surface
# Rôle : Nettoie la surface textuelle d'une entité en retirant les caractères parasites.
# -----------------------------------------------------------------------------
def ent66b_clean_surface(surface):
    surface = str(surface or '')
    surface = surface.strip(' \t\r\n,;:.()[]{}')
    surface = re.sub('\\s+', ' ', surface)
    return surface.strip()


# -----------------------------------------------------------------------------
# Fonction : ent66b_category_entities
# Rôle : Retourne uniquement les entités appartenant à une catégorie donnée.
# -----------------------------------------------------------------------------
def ent66b_category_entities(entities, category):
    return [entity for entity in entities if isinstance(entity, dict) and ent66b_entity_type(entity) == category]


# -----------------------------------------------------------------------------
# Fonction : ent66b_equivalent_surface_exists
# Rôle : Vérifie si une entité équivalente existe déjà afin d'éviter un nouvel ajout.
# -----------------------------------------------------------------------------
def ent66b_equivalent_surface_exists(entities, category, surface):
    """
    Évite les doublons d'une même entité.
    Exact + containment conservateur.
    """
    candidate = ent66b_normalize(surface)
    if not candidate:
        return True
    for entity in entities:
        if not isinstance(entity, dict):
            continue
        if ent66b_entity_type(entity) != category:
            continue
        existing = ent66b_normalize(ent66b_entity_surface(entity))
        if not existing:
            continue
        if existing == candidate:
            return True
        if min(len(existing), len(candidate)) >= 5 and (existing in candidate or candidate in existing):
            return True
    return False


# -----------------------------------------------------------------------------
# Fonction : ent66b_make_new_entity
# Rôle : Construit la structure JSON d'une nouvelle entité ajoutée par le post-traitement.
# -----------------------------------------------------------------------------
def ent66b_make_new_entity(page_number, sequence, category, surface, reason):
    return {'identifiant_entite': f'P{page_number}_V66_E{sequence:03d}', 'categorie': category, 'parametre': '', 'valeur': None, 'unite': None, 'horodatage': 'inconnu', 'preuve': surface, 'nie': False, 'confiance': 'elevee', 'type_inference': 'recuperation_deterministe_v66', 'page': page_number, 'valeur_reference': None, 'name': surface, 'type': category, '_v66_recovered': True, '_v66_reason': reason}


# -----------------------------------------------------------------------------
# Fonction : ent66b_add_candidate
# Rôle : Ajoute une entité candidate seulement si elle est valide et non déjà présente.
# -----------------------------------------------------------------------------
def ent66b_add_candidate(entities, page_number, sequence, category, surface, reason, stats):
    surface = ent66b_clean_surface(surface)
    if not surface:
        return sequence
    if len(ent66b_normalize(surface)) < 2 and ent66b_normalize(surface) not in {'k'}:
        return sequence
    if ent66b_equivalent_surface_exists(entities, category, surface):
        return sequence
    entity = ent66b_make_new_entity(page_number=page_number, sequence=sequence, category=category, surface=surface, reason=reason)
    entities.append(entity)
    stats[f'added_{category}'] += 1
    return sequence + 1

# --- ent66b_VITAL_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_VITAL_PATTERN = re.compile('\n    \\b(\n        hypertherm|\n        febril|\n        tachycard|\n        bradycard|\n        tachypn|\n        polypn|\n        eupne|\n        desaturation|\n        saturation|\n        spo2|\n        sao2|\n        frequence\\s+cardiaque|\n        frequence\\s+respiratoire|\n        pression\\s+arterielle|\n        tension\\s+arterielle|\n        hypotendu|\n        hypotondu|\n        trc\\b|\n        temperature\n    )\n    ', re.IGNORECASE | re.VERBOSE)

# --- ent66b_LAB_GAS_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_LAB_GAS_PATTERN = re.compile('\n    \\b(\n        pco2|paco2|\n        po2|pao2|\n        hco3|\n        bicarbonates?|\n        lactates?|\n        temps\\s+de\\s+quick|\n        \\btq\\b|\n        \\binr\\b|\n        creatinine|\n        uree|\n        natremie|\n        kaliemie|\n        bilirubine|\n        \\basat\\b|\n        \\balat\\b|\n        \\bcrp\\b|\n        procalcitonine|\n        \\bpct\\b|\n        nt[\\s-]*pro[\\s-]*bnp|\n        \\btsh\\b\n    )\n    ', re.IGNORECASE | re.VERBOSE)

# --- ent66b_CHRONIC_COMORBIDITY_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_CHRONIC_COMORBIDITY_PATTERN = re.compile('\n    (\n        chronique|\n        cirrhot|\n        cardiomyopath|\n        myotonie|\n        hypertrophie|\n        antecedent|\n        ancien|\n        ancienne|\n        denutrition\\s+severe|\n        foie\\s+dysmorphique|\n        dilatation\\s+des\\s+bronches\n    )\n    ', re.IGNORECASE | re.VERBOSE)

# --- ent66b_LABEL_FROM_FAILURE_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_LABEL_FROM_FAILURE_PATTERN = re.compile('\n    (\n        acidose\\s+metabolique|\n        insuffisance\\s+surrenale|\n        dysfonction\\s+diastolique|\n        \\bacfa\\b|\n        syndrome\\s+de\\s+renutrition|\n        encephalopathie\\s+hepatique|\n        syndrome\\s+hepato[\\s-]*renal|\n        thrombose\\s+(?:portale|porte)\n    )\n    ', re.IGNORECASE | re.VERBOSE)

# --- ent66b_SYMPTOM_FROM_FAILURE_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_SYMPTOM_FROM_FAILURE_PATTERN = re.compile('\n    (\n        ascite|\n        epanchement\\s+pleural|\n        syndrome\\s+pleural|\n        oligurique|\n        \\banurie\\b|\n        angiomes?\\s+stellaires?|\n        vesicule\\s+biliaire\\s+distendue|\n        aggravation\\s+respiratoire\n    )\n    ', re.IGNORECASE | re.VERBOSE)

# --- ent66b_FOCUS_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_FOCUS_PATTERN = re.compile('\n    (\n        spondylodiscite|\n        epidurite|\n        dermo[\\s-]*hypodermite|\n        peritonite\\s+stercorale|\n        gangrene\\s+gazeuse|\n        angiocholite|\n        cellulite\\s+extensive\n    )\n    ', re.IGNORECASE | re.VERBOSE)

# --- ent66b_TREATMENT_FROM_HISTORY_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_TREATMENT_FROM_HISTORY_PATTERN = re.compile('\n    (\n        resection|\n        chimiotherapie|\n        radiotherapie|\n        metas?tasectomie|\n        greffe|\n        dialys|\n        bricker|\n        pose\\s+de|\n        stripping|\n        tracheotomie|\n        intubation|\n        chirurgie|\n        intervention\n    )\n    ', re.IGNORECASE | re.VERBOSE)


# -----------------------------------------------------------------------------
# Fonction : ent66b_retype_entities
# Rôle : Corrige certains types d'entités à partir de règles explicites.
# -----------------------------------------------------------------------------
def ent66b_retype_entities(entities, stats):
    for entity in entities:
        if not isinstance(entity, dict):
            continue
        category = ent66b_entity_type(entity)
        surface = ent66b_entity_surface(entity)
        normalized = ent66b_normalize(surface)
        if not normalized:
            continue
        new_category = None
        reason = None
        if False:
            pass
        elif category == 'SIGNE_VITAL' and ent66b_LAB_GAS_PATTERN.search(normalized):
            new_category = 'BIOMARQUEUR'
            reason = 'mesure biologique/gazométrique reclassée biomarqueur'
        elif category == 'DEFAILLANCE_ORGANE':
            if ent66b_CHRONIC_COMORBIDITY_PATTERN.search(normalized):
                new_category = 'COMORBIDITE_ANTECEDENT'
                reason = 'terrain chronique reclassé comorbidité/antécédent'
            elif ent66b_LABEL_FROM_FAILURE_PATTERN.search(normalized):
                new_category = 'LABEL_NOSOLOGIQUE'
                reason = 'diagnostic nosologique reclassé label'
            elif ent66b_SYMPTOM_FROM_FAILURE_PATTERN.search(normalized):
                new_category = 'SYMPTOME'
                reason = 'manifestation clinique reclassée symptôme'
        elif category == 'LABEL_NOSOLOGIQUE' and ent66b_FOCUS_PATTERN.search(normalized):
            new_category = 'FOYER_INFECTIEUX'
            reason = 'diagnostic infectieux localisé reclassé foyer'
        elif category == 'COMORBIDITE_ANTECEDENT' and ent66b_TREATMENT_FROM_HISTORY_PATTERN.search(normalized):
            new_category = 'TRAITEMENT'
            reason = 'procédure/prise en charge reclassée traitement'
        if new_category and new_category != category:
            ent66b_set_entity_type(entity, new_category)
            entity['_v66_original_type'] = category
            entity['_v66_retyped'] = True
            entity['_v66_reason'] = reason
            stats[f'retyped_{category}_TO_{new_category}'] += 1
ent66b_BIOMARKER_MARKERS = 'CRP|PCT|procalcitonine|lactate(?:s)?|creatinine|urée|uree|natrémie|natremie|kaliémie|kaliemie|glycémie|glycemie|bilirubine|ASAT|ALAT|INR|TSH|NT[\\s-]*pro[\\s-]*BNP|PaCO2|PCO2|PaO2|PO2|pH|leucocytes?|globules?\\s+blancs?|GB|PNN|polynucléaires?\\s+neutrophiles?|plaquettes?|hémoglobine|hemoglobine|Hb|temps\\s+de\\s+quick|TQ'

# --- ent66b_BIOMARKER_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_BIOMARKER_PATTERN = re.compile(f'\n    (?P<surface>\n        \\b(?:{ent66b_BIOMARKER_MARKERS})\\b\n        [^\\n,;:]{{0,28}}\n        (?:\n            [:=]\\s*\n        )?\n        [-+]?\\d+(?:[.,]\\d+)?\n        \\s*\n        (?:\n            mmol/?L|\n            mmol\\s*/\\s*l|\n            mg/?L|\n            mg\\s*/\\s*l|\n            mg/?dL|\n            g/?L|\n            g\\s*/\\s*l|\n            pg/?mL|\n            ng/?mL|\n            µ?mol/?L|\n            umol/?L|\n            mmHg|\n            secondes?|\n            sec|\n            s\\b|\n            %|\n            \\*?10\\^?\\d+/?L\n        )?\n    )\n    ', re.IGNORECASE | re.VERBOSE)


# -----------------------------------------------------------------------------
# Fonction : ent66b_recover_biomarkers
# Rôle : Récupère des biomarqueurs manquants lorsqu'un marqueur et une valeur sont explicitement présents.
# -----------------------------------------------------------------------------
def ent66b_recover_biomarkers(text, entities, page_number, sequence, stats):
    if not ent66b_RECOVER_BIOMARKERS:
        return sequence
    for match in ent66b_BIOMARKER_PATTERN.finditer(text):
        surface = match.group('surface')
        sequence = ent66b_add_candidate(entities=entities, page_number=page_number, sequence=sequence, category='BIOMARQUEUR', surface=surface, reason='marqueur biologique + valeur numérique dans le texte', stats=stats)
    return sequence

# --- ent66b_MICRO_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_MICRO_PATTERN = re.compile('\n    (?P<surface>\n        \\b(\n            staphylococcus\\s+aureus|\n            staphylocoque(?:\\s+\\w+){0,2}|\n            staph(?:ylocoque)?\\s+(?:dore|méth\\s*[rs]|meth\\s*[rs])|\n            streptocoque(?:\\s+\\w+){0,2}|\n            pseudomonas(?:\\s+aeruginosa)?|\n            p\\.\\s*aeruginosa|\n            escherichia\\s+coli|\n            e\\.?\\s*coli(?:\\s+blse)?|\n            enterococcus\\s+faecalis|\n            enterocoque(?:\\s+\\w+){0,4}|\n            klebsiell?a(?:\\s+\\w+)?|\n            serratia(?:\\s+\\w+)?|\n            enterobacter(?:\\s+\\w+){0,2}|\n            acinetobacter(?:\\s+\\w+){0,2}|\n            proteus(?:\\s+\\w+)?|\n            corynebacterium(?:\\s+\\w+){0,2}|\n            dermabacter(?:\\s+\\w+)?|\n            pneumocoque|\n            candida(?:\\s+\\w+)?|\n            \\bsarm\\b|\n            \\bsams\\b\n        )\\b\n    )\n    ', re.IGNORECASE | re.VERBOSE)


# -----------------------------------------------------------------------------
# Fonction : ent66b_recover_microorganisms
# Rôle : Récupère certains microorganismes explicitement mentionnés dans le texte.
# -----------------------------------------------------------------------------
def ent66b_recover_microorganisms(text, entities, page_number, sequence, stats):
    if not ent66b_RECOVER_MICROORGANISMS:
        return sequence
    for match in ent66b_MICRO_PATTERN.finditer(text):
        surface = match.group('surface')
        sequence = ent66b_add_candidate(entities=entities, page_number=page_number, sequence=sequence, category='MICRO_ORGANISME', surface=surface, reason='nom microbiologique détecté dans le texte', stats=stats)
    return sequence

# --- ent66b_FOCUS_RECOVERY_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_FOCUS_RECOVERY_PATTERN = re.compile('\n    (?P<surface>\n        \\b(\n            spondylodiscite(?:\\s+[^\\n,;.]{0,45})?|\n            epidurite(?:\\s+[^\\n,;.]{0,35})?|\n            ostéite(?:\\s+[^\\n,;.]{0,35})?|\n            osteite(?:\\s+[^\\n,;.]{0,35})?|\n            angiocholite(?:\\s+[^\\n,;.]{0,35})?|\n            péritonite\\s+stercorale|\n            peritonite\\s+stercorale|\n            dermo[\\s-]*hypodermite(?:\\s+[^\\n,;.]{0,40})?|\n            sinusite\\s+(?:maxillaire|sphenoidale|sphénoïdale)\n                (?:\\s+[^\\n,;.]{0,30})?|\n            cellulite\\s+extensive\n        )\n    )\n    ', re.IGNORECASE | re.VERBOSE)


# -----------------------------------------------------------------------------
# Fonction : ent66b_recover_foci
# Rôle : Récupère certains foyers infectieux explicitement mentionnés dans le texte.
# -----------------------------------------------------------------------------
def ent66b_recover_foci(text, entities, page_number, sequence, stats):
    if not ent66b_RECOVER_FOCI:
        return sequence
    for match in ent66b_FOCUS_RECOVERY_PATTERN.finditer(text):
        surface = ent66b_clean_surface(match.group('surface'))
        if len(surface) > 120:
            surface = surface[:120].rstrip()
        sequence = ent66b_add_candidate(entities=entities, page_number=page_number, sequence=sequence, category='FOYER_INFECTIEUX', surface=surface, reason='mention infectieuse localisée fortement typée', stats=stats)
    return sequence

# --- ent66b_TREATMENT_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_TREATMENT_PATTERN = re.compile('\n    (?P<surface>\n        \\b(\n            Tard[iy]feron|\n            Primperan|\n            Primpéran|\n            Lasilix|\n            Vancomycine|\n            Tienam|\n            Tazocilline|\n            Augmentin|\n            Amiklin|\n            Amikacine|\n            Ceftriaxone|\n            Claforan|\n            Oflocet|\n            Ofloct|\n            Noradrenaline|\n            Noradrénaline|\n            Dobutamine|\n            Adrénaline|\n            Adrenaline|\n            Lovenox|\n            Héparine|\n            Heparine|\n            Paracetamol|\n            Paracétamol|\n            Perfalgan|\n            DAFALGAN|\n            Zytiga|\n            oxygenotherapie|\n            oxygénothérapie|\n            O2\\s+au\\s+masque|\n            ventilation\\s+non\\s+invasive|\n            \\bVNI\\b|\n            intubation\\s+orotracheale|\n            intubation\\s+orotrachéale|\n            \\bIOT\\b|\n            tracheotomie|\n            trachéotomie|\n            remplissage\\s+vasculaire|\n            serum\\s+physiologique|\n            sérum\\s+physiologique|\n            alimentation\\s+enterale|\n            alimentation\\s+entérale|\n            drain\\s+thoracique|\n            epuration\\s+extra[\\s-]*renale|\n            épuration\\s+extra[\\s-]*rénale|\n            \\bEER\\b\n        )\\b\n    )\n    ', re.IGNORECASE | re.VERBOSE)


# -----------------------------------------------------------------------------
# Fonction : ent66b_recover_treatments
# Rôle : Récupère certains traitements/procédures explicitement mentionnés dans le texte.
# -----------------------------------------------------------------------------
def ent66b_recover_treatments(text, entities, page_number, sequence, stats):
    if not ent66b_RECOVER_TREATMENTS:
        return sequence
    for match in ent66b_TREATMENT_PATTERN.finditer(text):
        surface = match.group('surface')
        sequence = ent66b_add_candidate(entities=entities, page_number=page_number, sequence=sequence, category='TRAITEMENT', surface=surface, reason='traitement/procédure à forte spécificité lexicale', stats=stats)
    return sequence

# --- ent66b_DOSE_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_DOSE_PATTERN = re.compile("\n    (?P<surface>\n        (?:\n            \\d+(?:[.,]\\d+)?\n            \\s*\n            (?:mg|g|µg|ug|mcg|ml|mL|L|UI)\n            (?:\n                \\s*/\\s*\n                (?:h|j|jour|24h|min)\n            )?\n        )\n        |\n        (?:\n            \\d+(?:[.,]\\d+)?\n            \\s*\n            (?:x|X)\n            \\s*\n            \\d+\n            \\s*/?\\s*j\n        )\n        |\n        (?:\n            \\d+\n            \\s*[-–]\\s*\n            \\d+\n            \\s*[-–]\\s*\n            \\d+(?:/\\d+)?\n        )\n        |\n        (?:\n            \\d+(?:[.,]\\d+)?\n            \\s*L\n            \\s*(?:d['’]O2|O2)?\n        )\n        |\n        (?:\n            toutes?\\s+les\\s+\\d+\\s*h\n        )\n        |\n        (?:\n            \\d+\\s*jours?\n        )\n        |\n        (?:\n            si\\s+besoin\n        )\n    )\n    ", re.IGNORECASE | re.VERBOSE)


# -----------------------------------------------------------------------------
# Fonction : ent66b_find_entity_occurrences
# Rôle : Localise les occurrences textuelles des entités afin de raisonner sur leur proximité.
# -----------------------------------------------------------------------------
def ent66b_find_entity_occurrences(text, entities, category):
    occurrences = []
    for entity in entities:
        if not isinstance(entity, dict):
            continue
        if ent66b_entity_type(entity) != category:
            continue
        surface = ent66b_entity_surface(entity)
        if not surface or len(surface) < 2:
            continue
        try:
            for match in re.finditer(re.escape(surface), text, flags=re.IGNORECASE):
                occurrences.append((match.start(), match.end()))
        except re.error:
            continue
    return occurrences


# -----------------------------------------------------------------------------
# Fonction : ent66b_distance_to_occurrences
# Rôle : Calcule une distance textuelle minimale entre deux mentions pour vérifier leur proximité.
# -----------------------------------------------------------------------------
def ent66b_distance_to_occurrences(start, end, occurrences):
    best = None
    for o_start, o_end in occurrences:
        if end <= o_start:
            distance = o_start - end
        elif o_end <= start:
            distance = start - o_end
        else:
            distance = 0
        if best is None or distance < best:
            best = distance
    return best


# -----------------------------------------------------------------------------
# Fonction : ent66b_recover_posology
# Rôle : Récupère des posologies candidates lorsque les conditions de l'étape l'autorisent.
# -----------------------------------------------------------------------------
def ent66b_recover_posology(text, entities, page_number, sequence, stats):
    if not ent66b_RECOVER_POSOLOGY:
        return sequence
    treatment_occurrences = ent66b_find_entity_occurrences(text, entities, 'TRAITEMENT')
    if not treatment_occurrences:
        return sequence
    for match in ent66b_DOSE_PATTERN.finditer(text):
        surface = match.group('surface')
        distance = ent66b_distance_to_occurrences(match.start(), match.end(), treatment_occurrences)
        if distance is None or distance > 130:
            continue
        sequence = ent66b_add_candidate(entities=entities, page_number=page_number, sequence=sequence, category='POSOLOGIE', surface=surface, reason="dose/fréquence proche d'un traitement", stats=stats)
    return sequence

# --- ent66b_ACQUISITION_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66b_ACQUISITION_PATTERN = re.compile("\n    (?P<surface>\n        \\b(\n            infection\\s+nosocomiale\\s*:\\s*oui|\n            infection\\s+nosocomiale|\n            contexte\\s+nosocomial|\n            pneumopathie\\s+nosocomiale|\n            pneumopathie\\s+communautaire|\n            acquise?\\s+sous\\s+ventilation(?:\\s+mecanique)?|\n            acquis(?:e)?\\s+dans\\s+le\\s+service|\n            probable(?:ment)?\\s+d['’]inhalation\n        )\\b\n    )\n    ", re.IGNORECASE | re.VERBOSE)


# -----------------------------------------------------------------------------
# Fonction : ent66b_recover_acquisition_context
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def ent66b_recover_acquisition_context(text, entities, page_number, sequence, stats):
    if not ent66b_RECOVER_ACQUISITION_CONTEXT:
        return sequence
    for match in ent66b_ACQUISITION_PATTERN.finditer(text):
        surface = match.group('surface')
        sequence = ent66b_add_candidate(entities=entities, page_number=page_number, sequence=sequence, category='CONTEXTE_ACQUISITION', surface=surface, reason="contexte d'acquisition explicitement formulé", stats=stats)
    return sequence


# -----------------------------------------------------------------------------
# Fonction : ent66b_process_page
# Rôle : Applique toutes les règles de cette étape à une page et met à jour ses entités/relations.
# -----------------------------------------------------------------------------
def ent66b_process_page(page, stats):
    page = copy.deepcopy(page)
    entities = page.get('entities')
    if not isinstance(entities, list):
        entities = page.get('entites', [])
    if not isinstance(entities, list):
        entities = []
    entities = [copy.deepcopy(entity) for entity in entities if isinstance(entity, dict)]
    text = str(page.get('texte_brut') or '')
    page_number = page.get('page', 0)
    ent66b_retype_entities(entities, stats)
    sequence = 1
    sequence = ent66b_recover_treatments(text, entities, page_number, sequence, stats)
    sequence = ent66b_recover_biomarkers(text, entities, page_number, sequence, stats)
    sequence = ent66b_recover_microorganisms(text, entities, page_number, sequence, stats)
    sequence = ent66b_recover_foci(text, entities, page_number, sequence, stats)
    sequence = ent66b_recover_acquisition_context(text, entities, page_number, sequence, stats)
    sequence = ent66b_recover_posology(text, entities, page_number, sequence, stats)
    page['entities'] = entities
    if 'entites' in page:
        page['entites'] = entities
    return page


# -----------------------------------------------------------------------------
# Fonction : ent66b_process_document
# Rôle : Applique toutes les règles de cette étape à l'ensemble des pages d'un document et agrège les résultats.
# -----------------------------------------------------------------------------
def ent66b_process_document(data):
    output = copy.deepcopy(data)
    stats = Counter()
    pages = output.get('pages', [])
    if not isinstance(pages, list):
        pages = []
    new_pages = []
    global_entities = []
    for page in pages:
        if not isinstance(page, dict):
            new_pages.append(page)
            continue
        processed = ent66b_process_page(page, stats)
        new_pages.append(processed)
        page_number = processed.get('page')
        for entity in processed.get('entities', []):
            if not isinstance(entity, dict):
                continue
            entity_copy = copy.deepcopy(entity)
            entity_copy['page'] = page_number
            global_entities.append(entity_copy)
    output['pages'] = new_pages
    output['global_entities'] = global_entities
    if isinstance(output.get('document_summary'), dict):
        output['document_summary']['total_entities'] = len(global_entities)
    output['entity_postprocessing_v66'] = {'version': 'V6.6b_ENTITY_CONSERVATIVE', 'source': 'V6.5_SELECTIVE_PRECISION_FULL', 'stats': dict(stats), 'total_entities': len(global_entities)}
    return (output, stats)


# -----------------------------------------------------------------------------
# Fonction : ent66b_process_folder
# Rôle : Traite tous les fichiers JSON d'un dossier avec cette version du post-traitement.
# -----------------------------------------------------------------------------
def ent66b_process_folder(input_dir, output_dir):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)
    if not input_dir.is_dir():
        raise FileNotFoundError(f"Dossier d'entrée introuvable : {input_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)
    for old_file in output_dir.glob('*.json'):
        try:
            old_file.unlink()
        except OSError:
            pass
    json_files = sorted(input_dir.glob('*.json'))
    print('\n============================================================')
    print('TRACE-Sepsis — V6.6b ENTITES CONSERVATIVE')
    print('============================================================')
    print('INPUT  :', input_dir)
    print('OUTPUT :', output_dir)
    print('JSON   :', len(json_files))
    print('============================================================\n')
    if len(json_files) != 43:
        print(f'⚠️ 43 documents attendus ; {len(json_files)} trouvés.')
    total_stats = Counter()
    for index, source in enumerate(json_files, start=1):
        with source.open('r', encoding='utf-8') as file:
            data = json.load(file)
        before = sum((len(page.get('entities', [])) for page in data.get('pages', []) if isinstance(page, dict)))
        result, stats = ent66b_process_document(data)
        total_stats.update(stats)
        after = len(result.get('global_entities', []))
        destination = output_dir / source.name
        with destination.open('w', encoding='utf-8') as file:
            json.dump(result, file, indent=2, ensure_ascii=False)
        print(f'✅ {index:02d}/{len(json_files)} {source.name} | entités {before} -> {after}')
    print('\n--- CORRECTIONS V6.6 ENTITES ---')
    for key, value in sorted(total_stats.items()):
        print(f'{key:60s} : {value}')
    print('\n🏁 V6.6b ENTITES CONSERVATIVE terminée.')

# ============================================================================
# STAGE ENT66C
#
# ÉTAPE ENT66C — Filtrage de précision des entités.
# Cette partie supprime des doublons, des variantes temporelles peu utiles et des
# entités connues comme peu fiables, puis nettoie les relations liées aux entités supprimées.
# ============================================================================

import copy
import json
import os
import re
import sys
import unicodedata
from collections import Counter
from pathlib import Path
if os.name == 'nt':
    ent66c_BASE_DIR = Path(os.environ.get('USERPROFILE', str(Path.home()))) / 'Desktop' / 'TRACE' / 'OCR vers LLM'
else:
    ent66c_BASE_DIR = Path.home() / 'TRACE' / 'OCR vers LLM'
ent66c_DEFAULT_INPUT_DIR = ent66c_BASE_DIR / 'BEST_43_Entites_V6_6b_CONSERVATIVE'
ent66c_DEFAULT_OUTPUT_DIR = ent66c_BASE_DIR / 'BEST_43_Entites_V6_6c_PRECISION_PLUS'


# -----------------------------------------------------------------------------
# Fonction : ent66c_remove_accents
# Rôle : Supprime les accents pour faciliter les comparaisons textuelles sans modifier la logique clinique.
# -----------------------------------------------------------------------------
def ent66c_remove_accents(value):
    value = '' if value is None else str(value)
    value = unicodedata.normalize('NFD', value)
    return ''.join((char for char in value if unicodedata.category(char) != 'Mn'))


# -----------------------------------------------------------------------------
# Fonction : ent66c_normalize
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def ent66c_normalize(value):
    value = ent66c_remove_accents(value).lower()
    value = value.replace('’', "'").replace('`', "'").replace('\xa0', ' ')
    value = re.sub('\\s+', ' ', value)
    value = value.strip(' \t\r\n,;:.()[]{}')
    return value


# -----------------------------------------------------------------------------
# Fonction : ent66c_entity_id
# Rôle : Récupère l'identifiant d'une entité de manière compatible avec plusieurs formats JSON.
# -----------------------------------------------------------------------------
def ent66c_entity_id(entity):
    return str(entity.get('identifiant_entite') or entity.get('id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : ent66c_entity_type
# Rôle : Récupère la catégorie/type d'une entité.
# -----------------------------------------------------------------------------
def ent66c_entity_type(entity):
    return str(entity.get('categorie') or entity.get('type') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : ent66c_entity_surface
# Rôle : Récupère la mention textuelle principale d'une entité.
# -----------------------------------------------------------------------------
def ent66c_entity_surface(entity):
    return str(entity.get('preuve') or entity.get('name') or entity.get('nom') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : ent66c_relation_subject_id
# Rôle : Récupère l'identifiant de l'entité sujet d'une relation.
# -----------------------------------------------------------------------------
def ent66c_relation_subject_id(relation):
    return str(relation.get('identifiant_entite_sujet') or relation.get('subject_id') or relation.get('from_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : ent66c_relation_object_id
# Rôle : Récupère l'identifiant de l'entité objet d'une relation.
# -----------------------------------------------------------------------------
def ent66c_relation_object_id(relation):
    return str(relation.get('identifiant_entite_objet') or relation.get('object_id') or relation.get('to_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : ent66c_build_containment_clusters
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def ent66c_build_containment_clusters(entities):
    """
    Construit des clusters d'entités dont les surfaces se contiennent.
    Le clustering reste local à une page et à un type donné.
    """
    if len(entities) < 2:
        return []
    parent = list(range(len(entities)))

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(first, second):
        root_a = find(first)
        root_b = find(second)
        if root_a != root_b:
            parent[root_b] = root_a
    normalized = [ent66c_normalize(ent66c_entity_surface(entity)) for entity in entities]
    for i in range(len(entities)):
        a = normalized[i]
        if len(a) < 4:
            continue
        for j in range(i + 1, len(entities)):
            b = normalized[j]
            if len(b) < 4:
                continue
            if a in b or b in a:
                union(i, j)
    grouped = {}
    for index in range(len(entities)):
        root = find(index)
        grouped.setdefault(root, []).append(index)
    return [indexes for indexes in grouped.values() if len(indexes) > 1]


# -----------------------------------------------------------------------------
# Fonction : ent66c_dedup_by_containment
# Rôle : Supprime les doublons en conservant une seule représentation de chaque élément.
# -----------------------------------------------------------------------------
def ent66c_dedup_by_containment(entities, category, keep_mode, stats):
    """
    keep_mode:
      - "shortest" : garde la surface la plus courte.
      - "longest"  : garde la surface la plus longue.
    """
    indexes = [index for index, entity in enumerate(entities) if isinstance(entity, dict) and ent66c_entity_type(entity) == category]
    selected_entities = [entities[index] for index in indexes]
    clusters = ent66c_build_containment_clusters(selected_entities)
    remove_ids = set()
    for cluster in clusters:
        cluster_entities = [selected_entities[index] for index in cluster]
        if keep_mode == 'shortest':
            keeper = min(cluster_entities, key=lambda entity: (len(ent66c_normalize(ent66c_entity_surface(entity))), ent66c_normalize(ent66c_entity_surface(entity))))
        elif keep_mode == 'longest':
            keeper = max(cluster_entities, key=lambda entity: (len(ent66c_normalize(ent66c_entity_surface(entity))), ent66c_normalize(ent66c_entity_surface(entity))))
        else:
            raise ValueError(f'keep_mode invalide : {keep_mode}')
        keeper_id = ent66c_entity_id(keeper)
        for entity in cluster_entities:
            current_id = ent66c_entity_id(entity)
            if current_id and current_id != keeper_id:
                remove_ids.add(current_id)
    if not remove_ids:
        return (entities, set())
    output = []
    for entity in entities:
        current_id = ent66c_entity_id(entity)
        if current_id in remove_ids:
            stats[f'removed_duplicate_{category}'] += 1
            continue
        output.append(entity)
    return (output, remove_ids)

# --- ent66c_NEGATIVE_SYMPTOM_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
ent66c_NEGATIVE_SYMPTOM_PATTERN = re.compile("\n    ^(?:\n        pas\\s+de\\b|\n        pas\\s+d'|\n        absence\\s+de\\b|\n        sans\\b|\n        aucun\\b|\n        aucune\\b\n    )\n    ", re.IGNORECASE | re.VERBOSE)
ent66c_BAD_ISOLATED_HOURS = {'00h', '2h', '6h', '8h', '12h', '18h', '24h', '48h', '72h'}


# -----------------------------------------------------------------------------
# Fonction : ent66c_should_remove_entity
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def ent66c_should_remove_entity(entity, stats):
    category = ent66c_entity_type(entity)
    surface = ent66c_entity_surface(entity)
    normalized = ent66c_normalize(surface)
    if category == 'SYMPTOME' and ent66c_NEGATIVE_SYMPTOM_PATTERN.search(normalized):
        stats['removed_negative_SYMPTOME'] += 1
        return True
    if category == 'CONTEXTE_ACQUISITION' and normalized == 'infection nosocomiale':
        stats['removed_generic_CONTEXTE_ACQUISITION'] += 1
        return True
    if category == 'TRAITEMENT' and normalized == 'antibiotherapie':
        stats['removed_generic_TRAITEMENT_antibiotherapie'] += 1
        return True
    if category == 'TRAITEMENT' and normalized == 'na':
        stats['removed_invalid_TRAITEMENT_NA'] += 1
        return True
    if category == 'EVENEMENT_TEMPOREL' and normalized in ent66c_BAD_ISOLATED_HOURS:
        stats['removed_isolated_hour_EVENT'] += 1
        return True
    return False


# -----------------------------------------------------------------------------
# Fonction : ent66c_clean_relations
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def ent66c_clean_relations(relations, valid_entity_ids, stats, counter_name):
    if not isinstance(relations, list):
        return []
    output = []
    for relation in relations:
        if not isinstance(relation, dict):
            continue
        subject = ent66c_relation_subject_id(relation)
        obj = ent66c_relation_object_id(relation)
        if not subject and (not obj):
            output.append(relation)
            continue
        if subject and subject not in valid_entity_ids:
            stats[counter_name] += 1
            continue
        if obj and obj not in valid_entity_ids:
            stats[counter_name] += 1
            continue
        output.append(relation)
    return output


# -----------------------------------------------------------------------------
# Fonction : ent66c_process_page
# Rôle : Applique toutes les règles de cette étape à une page et met à jour ses entités/relations.
# -----------------------------------------------------------------------------
def ent66c_process_page(page, stats):
    page = copy.deepcopy(page)
    entities = page.get('entities')
    if not isinstance(entities, list):
        entities = page.get('entites', [])
    if not isinstance(entities, list):
        entities = []
    entities = [copy.deepcopy(entity) for entity in entities if isinstance(entity, dict)]
    filtered = []
    for entity in entities:
        if ent66c_should_remove_entity(entity, stats):
            continue
        filtered.append(entity)
    entities = filtered
    entities, _ = ent66c_dedup_by_containment(entities=entities, category='EVENEMENT_TEMPOREL', keep_mode='shortest', stats=stats)
    entities, _ = ent66c_dedup_by_containment(entities=entities, category='IMAGERIE_PROCEDURE', keep_mode='longest', stats=stats)
    entities, _ = ent66c_dedup_by_containment(entities=entities, category='SCORE_NEUROLOGIQUE', keep_mode='longest', stats=stats)
    valid_ids = {ent66c_entity_id(entity) for entity in entities if ent66c_entity_id(entity)}
    page['entities'] = entities
    if 'entites' in page:
        page['entites'] = entities
    if 'relations' in page:
        page['relations'] = ent66c_clean_relations(relations=page.get('relations', []), valid_entity_ids=valid_ids, stats=stats, counter_name='removed_page_relation_due_to_removed_entity')
    return page


# -----------------------------------------------------------------------------
# Fonction : ent66c_process_document
# Rôle : Applique toutes les règles de cette étape à l'ensemble des pages d'un document et agrège les résultats.
# -----------------------------------------------------------------------------
def ent66c_process_document(data):
    output = copy.deepcopy(data)
    stats = Counter()
    pages = output.get('pages', [])
    if not isinstance(pages, list):
        pages = []
    new_pages = []
    global_entities = []
    for page in pages:
        if not isinstance(page, dict):
            new_pages.append(page)
            continue
        processed = ent66c_process_page(page, stats)
        new_pages.append(processed)
        page_number = processed.get('page')
        for entity in processed.get('entities', []):
            if not isinstance(entity, dict):
                continue
            entity_copy = copy.deepcopy(entity)
            entity_copy['page'] = page_number
            global_entities.append(entity_copy)
    output['pages'] = new_pages
    output['global_entities'] = global_entities
    valid_global_ids = {ent66c_entity_id(entity) for entity in global_entities if ent66c_entity_id(entity)}
    if 'global_relations' in output:
        output['global_relations'] = ent66c_clean_relations(relations=output.get('global_relations', []), valid_entity_ids=valid_global_ids, stats=stats, counter_name='removed_global_relation_due_to_removed_entity')
    if isinstance(output.get('document_summary'), dict):
        output['document_summary']['total_entities'] = len(global_entities)
        if isinstance(output.get('global_relations'), list):
            output['document_summary']['total_relations'] = len(output['global_relations'])
    output['entity_postprocessing_v66c'] = {'version': 'V6.6c_ENTITY_PRECISION_PLUS', 'source': 'V6.6b_ENTITY_CONSERVATIVE', 'stats': dict(stats), 'total_entities': len(global_entities)}
    return (output, stats)


# -----------------------------------------------------------------------------
# Fonction : ent66c_process_folder
# Rôle : Traite tous les fichiers JSON d'un dossier avec cette version du post-traitement.
# -----------------------------------------------------------------------------
def ent66c_process_folder(input_dir, output_dir):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)
    if not input_dir.is_dir():
        raise FileNotFoundError(f"Dossier d'entrée introuvable : {input_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)
    for old_file in output_dir.glob('*.json'):
        try:
            old_file.unlink()
        except OSError:
            pass
    json_files = sorted(input_dir.glob('*.json'))
    print('\n============================================================')
    print('TRACE-Sepsis — V6.6c ENTITES PRECISION+')
    print('============================================================')
    print('INPUT  :', input_dir)
    print('OUTPUT :', output_dir)
    print('JSON   :', len(json_files))
    print('============================================================\n')
    if len(json_files) != 43:
        print(f'⚠️ 43 documents attendus ; {len(json_files)} trouvés.')
    global_stats = Counter()
    for index, source in enumerate(json_files, start=1):
        with source.open('r', encoding='utf-8') as file:
            data = json.load(file)
        before = len(data.get('global_entities', []))
        result, stats = ent66c_process_document(data)
        global_stats.update(stats)
        after = len(result.get('global_entities', []))
        destination = output_dir / source.name
        with destination.open('w', encoding='utf-8') as file:
            json.dump(result, file, ensure_ascii=False, indent=2)
        print(f'✅ {index:02d}/{len(json_files)} {source.name} | entités {before} -> {after}')
    print('\n--- CORRECTIONS V6.6c PRECISION+ ---')
    for key, value in sorted(global_stats.items()):
        print(f'{key:65s} : {value}')
    print('\n🏁 V6.6c ENTITES PRECISION+ terminée.')

# ============================================================================
# STAGE REL66
#
# ÉTAPE REL66 — Première normalisation des relations.
# Cette étape vérifie les signatures sujet/relation/objet, remappe les références patient,
# met à jour les noms des extrémités et supprime les doublons relationnels.
# ============================================================================

import copy
import json
import os
import re
import sys
import unicodedata
from pathlib import Path
if os.name == 'nt':
    rel66_BASE_DIR = Path(os.environ.get('USERPROFILE', str(Path.home()))) / 'Desktop' / 'TRACE' / 'OCR vers LLM'
else:
    rel66_BASE_DIR = Path.home() / 'TRACE' / 'OCR vers LLM'
rel66_DEFAULT_INPUT_DIR = rel66_BASE_DIR / 'mllm_canonical_par_document_V6_5_SELECTIVE_PRECISION_FULL'
rel66_DEFAULT_OUTPUT_DIR = rel66_BASE_DIR / 'mllm_canonical_relations_V6_6_PRECISION'
rel66_DROP_ALWAYS = {'precede', 'comorbidite_est_facteur_risque_de', 'signe_vital_supporte_defaillance_organe', 'antibiotique_adequat_pour', 'antibiotique_inadequat_pour', 'biomarqueur_obtenu_a', 'traitement_cible_defaillance', 'biomarqueur_est_critere_de'}
rel66_SIGNATURES = {'a_pour_label_nosologique': ('DONNEE_PATIENT', 'LABEL_NOSOLOGIQUE'), 'presente_suspicion_infection': ('DONNEE_PATIENT', 'FOYER_INFECTIEUX'), 'presente_dysfonction_organe': ('DONNEE_PATIENT', 'DEFAILLANCE_ORGANE'), 'traitement_administre_a': ('TRAITEMENT', 'DONNEE_PATIENT'), 'traitement_a_pour_posologie': ('TRAITEMENT', 'POSOLOGIE'), 'traitement_indique_par_label_nosologique': ('TRAITEMENT', 'LABEL_NOSOLOGIQUE'), 'biomarqueur_supporte_defaillance_organe': ('BIOMARQUEUR', 'DEFAILLANCE_ORGANE'), 'micro_organisme_isole_dans': ('MICRO_ORGANISME', 'FOYER_INFECTIEUX'), 'patient_a_pour_evolution': ('DONNEE_PATIENT', 'EVOLUTION_PRONOSTIC'), 'service_medical_accueille': ('SERVICE_MEDICAL', 'DONNEE_PATIENT'), 'imagerie_objective_foyer': ('IMAGERIE_PROCEDURE', 'FOYER_INFECTIEUX'), 'imagerie_objective_comorbidite': ('IMAGERIE_PROCEDURE', 'COMORBIDITE_ANTECEDENT'), 'imagerie_objective_defaillance': ('IMAGERIE_PROCEDURE', 'DEFAILLANCE_ORGANE'), 'presente_symptome': ('DONNEE_PATIENT', 'SYMPTOME')}


# -----------------------------------------------------------------------------
# Fonction : rel66_remove_accents
# Rôle : Supprime les accents pour faciliter les comparaisons textuelles sans modifier la logique clinique.
# -----------------------------------------------------------------------------
def rel66_remove_accents(value):
    text = '' if value is None else str(value)
    text = unicodedata.normalize('NFD', text)
    return ''.join((c for c in text if unicodedata.category(c) != 'Mn'))


# -----------------------------------------------------------------------------
# Fonction : rel66_ntext
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel66_ntext(value):
    text = rel66_remove_accents(value).lower().strip()
    text = text.replace('’', "'").replace('`', "'")
    text = text.replace('_', ' ')
    text = re.sub('\\s+', ' ', text)
    return text.strip()


# -----------------------------------------------------------------------------
# Fonction : rel66_eid
# Rôle : Récupère l'identifiant d'une entité de manière compatible avec plusieurs formats JSON.
# -----------------------------------------------------------------------------
def rel66_eid(entity):
    return str(entity.get('identifiant_entite') or entity.get('id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel66_ecat
# Rôle : Récupère la catégorie/type d'une entité.
# -----------------------------------------------------------------------------
def rel66_ecat(entity):
    return str(entity.get('categorie') or entity.get('type') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel66_esurface
# Rôle : Récupère la mention textuelle principale d'une entité.
# -----------------------------------------------------------------------------
def rel66_esurface(entity):
    return str(entity.get('preuve') or entity.get('name') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel66_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel66_rtype(relation):
    return str(relation.get('type_relation') or relation.get('relation') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel66_sid
# Rôle : Récupère l'identifiant de l'entité sujet d'une relation.
# -----------------------------------------------------------------------------
def rel66_sid(relation):
    return str(relation.get('identifiant_entite_sujet') or relation.get('subject_id') or relation.get('from_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel66_oid
# Rôle : Récupère l'identifiant de l'entité objet d'une relation.
# -----------------------------------------------------------------------------
def rel66_oid(relation):
    return str(relation.get('identifiant_entite_objet') or relation.get('object_id') or relation.get('to_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel66_set_sid
# Rôle : Récupère l'identifiant de l'entité sujet d'une relation.
# -----------------------------------------------------------------------------
def rel66_set_sid(relation, value):
    relation['identifiant_entite_sujet'] = value
    if 'subject_id' in relation:
        relation['subject_id'] = value
    if 'from_id' in relation:
        relation['from_id'] = value


# -----------------------------------------------------------------------------
# Fonction : rel66_set_oid
# Rôle : Récupère l'identifiant de l'entité objet d'une relation.
# -----------------------------------------------------------------------------
def rel66_set_oid(relation, value):
    relation['identifiant_entite_objet'] = value
    if 'object_id' in relation:
        relation['object_id'] = value
    if 'to_id' in relation:
        relation['to_id'] = value


# -----------------------------------------------------------------------------
# Fonction : rel66_patient_rank
# Rôle : Attribue une priorité aux entités patient afin de choisir l'ancrage patient le plus fiable.
# -----------------------------------------------------------------------------
def rel66_patient_rank(entity):
    s = rel66_ntext(rel66_esurface(entity))
    if s in {'patient', 'patiente', 'le patient', 'la patiente', 'un patient', 'une patiente'}:
        return (0, len(s))
    if re.search('\\bpatient(?:e)?\\b', s):
        return (1, len(s))
    if re.search('\\b\\d+\\s*ans\\b', s):
        return (5, len(s))
    if s.startswith(('poids', 'taille', 'bmi', 'imc')):
        return (6, len(s))
    return (4, len(s))


# -----------------------------------------------------------------------------
# Fonction : rel66_choose_patient_id
# Rôle : Identifie ou sélectionne l'entité représentant le patient.
# -----------------------------------------------------------------------------
def rel66_choose_patient_id(entities):
    patients = [e for e in entities if rel66_ecat(e) == 'DONNEE_PATIENT' and rel66_eid(e)]
    if not patients:
        return None
    patients.sort(key=rel66_patient_rank)
    return rel66_eid(patients[0])


# -----------------------------------------------------------------------------
# Fonction : rel66_spans
# Rôle : Localise les positions d'une mention dans le texte.
# -----------------------------------------------------------------------------
def rel66_spans(text, entity):
    candidates = []
    for key in ('preuve', 'name'):
        value = entity.get(key)
        if value:
            value = str(value).strip()
            if value and value not in candidates:
                candidates.append(value)
    output = []
    for surface in candidates:
        for m in re.finditer(re.escape(surface), text, flags=re.IGNORECASE):
            output.append((m.start(), m.end()))
    return sorted(set(output))


# -----------------------------------------------------------------------------
# Fonction : rel66_min_distance
# Rôle : Calcule une distance textuelle minimale entre deux mentions pour vérifier leur proximité.
# -----------------------------------------------------------------------------
def rel66_min_distance(text, e1, e2):
    a = rel66_spans(text, e1)
    b = rel66_spans(text, e2)
    if not a or not b:
        return None
    best = None
    for a1, a2 in a:
        for b1, b2 in b:
            if a2 <= b1:
                dist = b1 - a2
            elif b2 <= a1:
                dist = a1 - b2
            else:
                dist = 0
            best = dist if best is None else min(best, dist)
    return best


# -----------------------------------------------------------------------------
# Fonction : rel66_context
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel66_context(text, entity, before=120, after=180):
    loc = rel66_spans(text, entity)
    if not loc:
        return ''
    start, end = loc[0]
    return text[max(0, start - before):min(len(text), end + after)]


# -----------------------------------------------------------------------------
# Fonction : rel66_valid_signature
# Rôle : Vérifie que le triplet sujet–relation–objet respecte les types attendus par le schéma.
# -----------------------------------------------------------------------------
def rel66_valid_signature(relation, entity_map):
    expected = rel66_SIGNATURES.get(rel66_rtype(relation))
    if expected is None:
        return True
    s = entity_map.get(rel66_sid(relation))
    o = entity_map.get(rel66_oid(relation))
    if not s or not o:
        return False
    return rel66_ecat(s) == expected[0] and rel66_ecat(o) == expected[1]


# -----------------------------------------------------------------------------
# Fonction : rel66_service_supported
# Rôle : Vérifie que la relation est suffisamment supportée par les entités et/ou le contexte.
# -----------------------------------------------------------------------------
def rel66_service_supported(text, service):
    surface = rel66_ntext(rel66_esurface(service))
    if any((bad in surface for bad in ('examen respiratoire', 'examen neurologique', 'examen abdominal', 'examens complementaires', 'clinique d admission', 'signes generaux'))):
        return False
    ctx = rel66_ntext(rel66_context(text, service, before=150, after=190))
    return any((marker in ctx for marker in ('hospitalise', 'hospitalisee', 'admis', 'admise', 'admission', 'adresse', 'adressee', 'transfere', 'transferee', 'transfert', 'sejour', 'service de', 'suite de prise en charge', 'prise en charge', 'retour', 'entree')))


# -----------------------------------------------------------------------------
# Fonction : rel66_relation_supported
# Rôle : Vérifie que la relation est suffisamment supportée par les entités et/ou le contexte.
# -----------------------------------------------------------------------------
def rel66_relation_supported(relation, entity_map, text):
    kind = rel66_rtype(relation)
    if kind in rel66_DROP_ALWAYS:
        return False
    s = entity_map.get(rel66_sid(relation), {})
    o = entity_map.get(rel66_oid(relation), {})
    if kind == 'service_medical_accueille':
        return rel66_service_supported(text, s)
    if kind == 'traitement_a_pour_posologie':
        dist = rel66_min_distance(text, s, o)
        return dist is not None and dist <= 140
    if kind == 'traitement_indique_par_label_nosologique':
        dist = rel66_min_distance(text, s, o)
        if dist is None or dist > 220:
            return False
        ctx = rel66_ntext(rel66_context(text, s, before=120, after=180))
        return any((marker in ctx for marker in ('pour ', 'traite par', 'traitee par', 'traitement par', 'justifie', 'justifiee', 'indique', 'indiquee', 'en raison', 'dans le cadre', 'devant')))
    if kind in {'imagerie_objective_foyer', 'imagerie_objective_comorbidite', 'imagerie_objective_defaillance'}:
        dist = rel66_min_distance(text, s, o)
        if dist is None or dist > 260:
            return False
        ctx = rel66_ntext(rel66_context(text, s, before=50, after=260))
        return any((marker in ctx for marker in ('retrouve', 'objective', 'montre', 'met en evidence', 'visualise', 'revele', 'confirme', 'evoque', 'avec')))
    if kind == 'micro_organisme_isole_dans':
        dist = rel66_min_distance(text, s, o)
        return dist is not None and dist <= 260
    return True


# -----------------------------------------------------------------------------
# Fonction : rel66_remap_patient
# Rôle : Réassocie une relation à l'entité patient sélectionnée lorsque l'ancrage initial est incorrect.
# -----------------------------------------------------------------------------
def rel66_remap_patient(relation, entity_map, patient_id):
    relation = dict(relation)
    if not patient_id:
        return relation
    expected = rel66_SIGNATURES.get(rel66_rtype(relation))
    if not expected:
        return relation
    s = entity_map.get(rel66_sid(relation), {})
    o = entity_map.get(rel66_oid(relation), {})
    if expected[0] == 'DONNEE_PATIENT' and rel66_ecat(s) == 'DONNEE_PATIENT':
        rel66_set_sid(relation, patient_id)
    if expected[1] == 'DONNEE_PATIENT' and rel66_ecat(o) == 'DONNEE_PATIENT':
        rel66_set_oid(relation, patient_id)
    return relation


# -----------------------------------------------------------------------------
# Fonction : rel66_refresh_names
# Rôle : Rafraîchit les noms de sujet/objet à partir des entités réellement référencées.
# -----------------------------------------------------------------------------
def rel66_refresh_names(relation, entity_map):
    relation = dict(relation)
    s = entity_map.get(rel66_sid(relation), {})
    o = entity_map.get(rel66_oid(relation), {})
    sname = str(s.get('name') or s.get('preuve') or '').strip()
    oname = str(o.get('name') or o.get('preuve') or '').strip()
    if sname:
        relation['entite_sujet'] = sname
        relation['subject'] = sname
    if oname:
        relation['entite_objet'] = oname
        relation['object'] = oname
    return relation


# -----------------------------------------------------------------------------
# Fonction : rel66_dedup
# Rôle : Supprime les doublons en conservant une seule représentation de chaque élément.
# -----------------------------------------------------------------------------
def rel66_dedup(relations):
    output = []
    seen = set()
    for relation in relations:
        key = (rel66_sid(relation), rel66_rtype(relation), rel66_oid(relation))
        if not all(key):
            continue
        if key in seen:
            continue
        seen.add(key)
        output.append(relation)
    return output


# -----------------------------------------------------------------------------
# Fonction : rel66_add_nearest_posologies
# Rôle : Associe de façon prudente une posologie au traitement le plus proche dans le texte.
# -----------------------------------------------------------------------------
def rel66_add_nearest_posologies(relations, entities, entity_map, text, page_number):
    treatments = [e for e in entities if rel66_ecat(e) == 'TRAITEMENT' and rel66_eid(e)]
    posologies = [e for e in entities if rel66_ecat(e) == 'POSOLOGIE' and rel66_eid(e)]
    existing = {(rel66_sid(r), rel66_rtype(r), rel66_oid(r)) for r in relations}
    counter = 1
    for posology in posologies:
        candidates = []
        for treatment in treatments:
            dist = rel66_min_distance(text, treatment, posology)
            if dist is not None and dist <= 120:
                candidates.append((dist, treatment))
        if not candidates:
            continue
        candidates.sort(key=lambda item: item[0])
        treatment = candidates[0][1]
        key = (rel66_eid(treatment), 'traitement_a_pour_posologie', rel66_eid(posology))
        if key in existing:
            continue
        relation = {'identifiant_relation': f'P{page_number}_V66R_{counter:03d}', 'identifiant_entite_sujet': rel66_eid(treatment), 'type_relation': 'traitement_a_pour_posologie', 'identifiant_entite_objet': rel66_eid(posology), 'delai_minutes': None, 'preuve': (rel66_esurface(treatment) + ' ' + rel66_esurface(posology)).strip(), 'note_clinique': 'V6.6 nearest local treatment-posology', 'type_inference': 'inference_structurelle', 'confiance': 'elevee'}
        relation = rel66_refresh_names(relation, entity_map)
        relations.append(relation)
        existing.add(key)
        counter += 1
    return relations


# -----------------------------------------------------------------------------
# Fonction : rel66_process_page
# Rôle : Applique toutes les règles de cette étape à une page et met à jour ses entités/relations.
# -----------------------------------------------------------------------------
def rel66_process_page(page):
    page = copy.deepcopy(page)
    entities = page.get('entities') if isinstance(page.get('entities'), list) else page.get('entites', [])
    relations = page.get('relations') if isinstance(page.get('relations'), list) else []
    text = str(page.get('texte_brut') or '')
    page_number = page.get('page', 0)
    entity_map = {rel66_eid(e): e for e in entities if isinstance(e, dict) and rel66_eid(e)}
    patient_id = rel66_choose_patient_id(entities)
    cleaned = []
    for raw in relations:
        if not isinstance(raw, dict):
            continue
        relation = rel66_remap_patient(raw, entity_map, patient_id)
        if not rel66_valid_signature(relation, entity_map):
            continue
        if not rel66_relation_supported(relation, entity_map, text):
            continue
        cleaned.append(rel66_refresh_names(relation, entity_map))
    cleaned = rel66_dedup(cleaned)
    cleaned = rel66_add_nearest_posologies(cleaned, entities, entity_map, text, page_number)
    cleaned = rel66_dedup(cleaned)
    for index, relation in enumerate(cleaned, start=1):
        relation['identifiant_relation'] = f'P{page_number}_R{index:03d}'
    page['relations'] = cleaned
    return page


# -----------------------------------------------------------------------------
# Fonction : rel66_process_document
# Rôle : Applique toutes les règles de cette étape à l'ensemble des pages d'un document et agrège les résultats.
# -----------------------------------------------------------------------------
def rel66_process_document(data):
    output = copy.deepcopy(data)
    pages = output.get('pages', [])
    new_pages = []
    global_relations = []
    for page in pages:
        if not isinstance(page, dict):
            new_pages.append(page)
            continue
        page = rel66_process_page(page)
        new_pages.append(page)
        global_relations.extend(copy.deepcopy(page.get('relations', [])))
    output['pages'] = new_pages
    output['global_relations'] = global_relations
    if isinstance(output.get('document_summary'), dict):
        output['document_summary']['total_relations'] = len(global_relations)
    output['relation_postprocessing'] = {'version': 'V6.6_RELATION_PRECISION', 'patient_anchor_unified': True, 'global_relations_rebuilt': True, 'dropped_relation_types': sorted(rel66_DROP_ALWAYS)}
    return output


# -----------------------------------------------------------------------------
# Fonction : rel66_process_folder
# Rôle : Traite tous les fichiers JSON d'un dossier avec cette version du post-traitement.
# -----------------------------------------------------------------------------
def rel66_process_folder(input_dir, output_dir):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)
    if not input_dir.is_dir():
        raise FileNotFoundError(f"Dossier d'entrée absent : {input_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)
    for old in output_dir.glob('*.json'):
        try:
            old.unlink()
        except OSError:
            pass
    files = sorted(input_dir.glob('*.json'))
    print('\n=== V6.6 RELATION PRECISION ===')
    print('INPUT  =', input_dir)
    print('OUTPUT =', output_dir)
    print('JSON   =', len(files))
    print('================================\n')
    for index, source in enumerate(files, start=1):
        with source.open('r', encoding='utf-8') as f:
            data = json.load(f)
        before = len(data.get('global_relations', []))
        result = rel66_process_document(data)
        after = len(result.get('global_relations', []))
        destination = output_dir / source.name
        with destination.open('w', encoding='utf-8') as f:
            json.dump(result, f, ensure_ascii=False, indent=2)
        print(f'✅ {index}/{len(files)} {source.name} | relations {before} -> {after}')
    print('\n🏁 V6.6 RELATION PRECISION terminée.')

# ============================================================================
# STAGE REL67B
#
# ÉTAPE REL67B — Correction relationnelle conservatrice.
# Cette partie corrige certains types de relations, élimine des relations non supportées
# et ajoute uniquement des relations considérées comme sûres.
# ============================================================================

import copy
import json
import os
import re
import sys
import unicodedata
from collections import Counter
from pathlib import Path
if os.name == 'nt':
    rel67b_BASE_DIR = Path(os.environ.get('USERPROFILE', str(Path.home()))) / 'Desktop' / 'TRACE' / 'OCR vers LLM'
else:
    rel67b_BASE_DIR = Path.home() / 'TRACE' / 'OCR vers LLM'
rel67b_DEFAULT_INPUT_DIR = rel67b_BASE_DIR / 'mllm_canonical_relations_V6_6_PRECISION'
rel67b_DEFAULT_OUTPUT_DIR = rel67b_BASE_DIR / 'mllm_canonical_relations_V6_7b_CONSERVATIVE'


# -----------------------------------------------------------------------------
# Fonction : rel67b_remove_accents
# Rôle : Supprime les accents pour faciliter les comparaisons textuelles sans modifier la logique clinique.
# -----------------------------------------------------------------------------
def rel67b_remove_accents(value):
    text = '' if value is None else str(value)
    text = unicodedata.normalize('NFD', text)
    return ''.join((c for c in text if unicodedata.category(c) != 'Mn'))


# -----------------------------------------------------------------------------
# Fonction : rel67b_ntext
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel67b_ntext(value):
    text = rel67b_remove_accents(value).lower().strip()
    text = text.replace('’', "'").replace('`', "'")
    text = text.replace('_', ' ')
    text = re.sub('\\s+', ' ', text)
    return text.strip()


# -----------------------------------------------------------------------------
# Fonction : rel67b_eid
# Rôle : Récupère l'identifiant d'une entité de manière compatible avec plusieurs formats JSON.
# -----------------------------------------------------------------------------
def rel67b_eid(entity):
    return str(entity.get('identifiant_entite') or entity.get('id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel67b_etype
# Rôle : Récupère la catégorie/type d'une entité.
# -----------------------------------------------------------------------------
def rel67b_etype(entity):
    return str(entity.get('categorie') or entity.get('type') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel67b_esurface
# Rôle : Récupère la mention textuelle principale d'une entité.
# -----------------------------------------------------------------------------
def rel67b_esurface(entity):
    return str(entity.get('preuve') or entity.get('name') or entity.get('nom') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel67b_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel67b_rtype(relation):
    return str(relation.get('type_relation') or relation.get('relation') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel67b_sid
# Rôle : Récupère l'identifiant de l'entité sujet d'une relation.
# -----------------------------------------------------------------------------
def rel67b_sid(relation):
    return str(relation.get('identifiant_entite_sujet') or relation.get('subject_id') or relation.get('from_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel67b_oid
# Rôle : Récupère l'identifiant de l'entité objet d'une relation.
# -----------------------------------------------------------------------------
def rel67b_oid(relation):
    return str(relation.get('identifiant_entite_objet') or relation.get('object_id') or relation.get('to_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel67b_set_sid
# Rôle : Récupère l'identifiant de l'entité sujet d'une relation.
# -----------------------------------------------------------------------------
def rel67b_set_sid(relation, value):
    relation['identifiant_entite_sujet'] = value
    if 'subject_id' in relation:
        relation['subject_id'] = value
    if 'from_id' in relation:
        relation['from_id'] = value


# -----------------------------------------------------------------------------
# Fonction : rel67b_set_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel67b_set_rtype(relation, value):
    relation['type_relation'] = value
    if 'relation' in relation:
        relation['relation'] = value


# -----------------------------------------------------------------------------
# Fonction : rel67b_entity_spans
# Rôle : Localise les positions d'une mention dans le texte.
# -----------------------------------------------------------------------------
def rel67b_entity_spans(text, entity):
    values = []
    for field in ('preuve', 'name', 'nom'):
        value = entity.get(field)
        if value:
            value = str(value).strip()
            if value and value not in values:
                values.append(value)
    spans = []
    for value in values:
        try:
            for match in re.finditer(re.escape(value), text, flags=re.IGNORECASE):
                spans.append((match.start(), match.end()))
        except re.error:
            pass
    return sorted(set(spans))


# -----------------------------------------------------------------------------
# Fonction : rel67b_nearest_pair
# Rôle : Recherche la paire d'entités la plus proche dans le texte.
# -----------------------------------------------------------------------------
def rel67b_nearest_pair(text, first, second):
    first_spans = rel67b_entity_spans(text, first)
    second_spans = rel67b_entity_spans(text, second)
    if not first_spans or not second_spans:
        return None
    best = None
    for a in first_spans:
        for b in second_spans:
            if a[1] <= b[0]:
                distance = b[0] - a[1]
            elif b[1] <= a[0]:
                distance = a[0] - b[1]
            else:
                distance = 0
            candidate = (distance, a, b)
            if best is None or candidate[0] < best[0]:
                best = candidate
    return best


# -----------------------------------------------------------------------------
# Fonction : rel67b_nearest_distance
# Rôle : Calcule une distance textuelle minimale entre deux mentions pour vérifier leur proximité.
# -----------------------------------------------------------------------------
def rel67b_nearest_distance(text, first, second):
    pair = rel67b_nearest_pair(text, first, second)
    return None if pair is None else pair[0]


# -----------------------------------------------------------------------------
# Fonction : rel67b_between_context
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel67b_between_context(text, first, second, margin=60):
    pair = rel67b_nearest_pair(text, first, second)
    if pair is None:
        return ''
    _, a, b = pair
    start = min(a[0], b[0])
    end = max(a[1], b[1])
    return text[max(0, start - margin):min(len(text), end + margin)]


# -----------------------------------------------------------------------------
# Fonction : rel67b_local_context
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel67b_local_context(text, entity, before=130, after=150):
    spans = rel67b_entity_spans(text, entity)
    if not spans:
        return ''
    chunks = []
    for start, end in spans:
        chunks.append(text[max(0, start - before):min(len(text), end + after)])
    return '\n'.join(chunks)


# -----------------------------------------------------------------------------
# Fonction : rel67b_relation_key
# Rôle : Construit une clé unique pour comparer et dédupliquer les relations.
# -----------------------------------------------------------------------------
def rel67b_relation_key(relation):
    return (rel67b_sid(relation), rel67b_rtype(relation), rel67b_oid(relation))


# -----------------------------------------------------------------------------
# Fonction : rel67b_dedup
# Rôle : Supprime les doublons en conservant une seule représentation de chaque élément.
# -----------------------------------------------------------------------------
def rel67b_dedup(relations):
    result = []
    seen = set()
    for relation in relations:
        if not isinstance(relation, dict):
            continue
        key = rel67b_relation_key(relation)
        if not all(key):
            continue
        if key in seen:
            continue
        seen.add(key)
        result.append(relation)
    return result


# -----------------------------------------------------------------------------
# Fonction : rel67b_relation_exists
# Rôle : Vérifie qu'une relation équivalente n'existe pas déjà.
# -----------------------------------------------------------------------------
def rel67b_relation_exists(relations, subject, relation_type, obj):
    key = (str(subject), str(relation_type), str(obj))
    return any((rel67b_relation_key(relation) == key for relation in relations if isinstance(relation, dict)))


# -----------------------------------------------------------------------------
# Fonction : rel67b_add_relation
# Rôle : Crée et ajoute une nouvelle relation lorsque les conditions sont satisfaites.
# -----------------------------------------------------------------------------
def rel67b_add_relation(relations, page_number, subject, relation_type, obj, proof, note):
    if not subject or not obj or subject == obj:
        return False
    if rel67b_relation_exists(relations, subject, relation_type, obj):
        return False
    relations.append({'identifiant_relation': '', 'identifiant_entite_sujet': subject, 'type_relation': relation_type, 'identifiant_entite_objet': obj, 'delai_minutes': None, 'preuve': str(proof or '').strip(), 'note_clinique': note, 'type_inference': 'inference_structurelle', 'confiance': 'elevee', '_v67b_added': True, '_page': page_number})
    return True


# -----------------------------------------------------------------------------
# Fonction : rel67b_correct_wrong_type
# Rôle : Corrige certains types de relations identifiés comme systématiquement erronés.
# -----------------------------------------------------------------------------
def rel67b_correct_wrong_type(relation, entity_map):
    """
    Cas observé dans l'évaluation :
    'abolition des ROT' doit participer à presente_symptome,
    pas presente_dysfonction_organe.
    """
    if rel67b_rtype(relation) != 'presente_dysfonction_organe':
        return (relation, False)
    obj = entity_map.get(rel67b_oid(relation), {})
    surface = rel67b_ntext(rel67b_esurface(obj))
    if 'abolition des rot' in surface or 'abolition des reflexes osteotendineux' in surface:
        relation = dict(relation)
        rel67b_set_rtype(relation, 'presente_symptome')
        relation['note_clinique'] = 'V6.7b : correction du type relationnel pour abolition des ROT.'
        return (relation, True)
    return (relation, False)


# -----------------------------------------------------------------------------
# Fonction : rel67b_is_negated_symptom
# Rôle : Détecte les symptômes niés afin d'éviter de créer ou conserver une relation positive.
# -----------------------------------------------------------------------------
def rel67b_is_negated_symptom(surface):
    value = rel67b_ntext(surface)
    return bool(re.match("^(?:pas\\s+de|pas\\s+d'|absence\\s+de|sans)\\b", value))


# -----------------------------------------------------------------------------
# Fonction : rel67b_safe_drop_relation
# Rôle : Supprime uniquement des relations identifiées comme faux positifs selon les règles de cette étape.
# -----------------------------------------------------------------------------
def rel67b_safe_drop_relation(relation, entity_map, text):
    kind = rel67b_rtype(relation)
    subject = entity_map.get(rel67b_sid(relation), {})
    obj = entity_map.get(rel67b_oid(relation), {})
    s = rel67b_ntext(rel67b_esurface(subject))
    o = rel67b_ntext(rel67b_esurface(obj))
    if kind == 'presente_symptome':
        if rel67b_is_negated_symptom(rel67b_esurface(obj)):
            return True
        if 'homans negatif' in o or 'homan negatif' in o:
            return True
        if o.startswith('amelioration clinique') or o.startswith('aggravation des') or o.startswith('objectif de saturation'):
            return True
    if kind == 'patient_a_pour_evolution':
        if o in {'aggravation du'} or o.endswith(' de la') or o.endswith(' du') or o.endswith(' de 0'):
            return True
        if o.startswith('pas de complication'):
            return True
    if kind == 'presente_dysfonction_organe':
        if o == 'cirrhotique':
            return True
        if o in {'rcp indifferent', 'rcp indifférent'}:
            return True
    if kind == 'traitement_administre_a':
        if o == '':
            pass
        if s in {'oxygenodependance', 'oxygenodependant', 'ventilation spontanee'}:
            return True
        ctx = rel67b_ntext(rel67b_local_context(text, subject, before=220, after=90))
        if any((marker in s for marker in ('operation de la cataracte', 'appendicectomie'))):
            if 'chirurgicaux' in ctx or 'antecedents' in ctx or 'dans l enfance' in ctx:
                return True
        if 'en attente' in s and (not any((marker in ctx for marker in ('administre', 'recoit', 'traite par', 'mis sous', 'mise sous')))):
            return True
    if kind == 'service_medical_accueille':
        if s in {'service', 'salle de reveil'}:
            return True
    return False


# -----------------------------------------------------------------------------
# Fonction : rel67b_posology_role
# Rôle : Détermine le rôle d'une entité de posologie pour vérifier qu'elle peut participer à la relation attendue.
# -----------------------------------------------------------------------------
def rel67b_posology_role(posology):
    value = rel67b_ntext(rel67b_esurface(posology))
    if 'peep' in value or 'fio2' in value or re.search('\\bvt\\b', value):
        return 'ventilation'
    if 'l/min' in value or re.search('\\b\\d+\\s*l\\b', value) or 'o2' in value:
        return 'oxygen'
    return 'generic'


# -----------------------------------------------------------------------------
# Fonction : rel67b_treatment_role
# Rôle : Détermine le rôle d'une entité traitement pour vérifier sa compatibilité relationnelle.
# -----------------------------------------------------------------------------
def rel67b_treatment_role(treatment):
    value = rel67b_ntext(rel67b_esurface(treatment))
    if any((marker in value for marker in ('ventilation', 'vni', 'bipap'))):
        return 'ventilation'
    if value == 'o2' or 'oxygene' in value or 'oxygenotherapie' in value:
        return 'oxygen'
    return 'generic'


# -----------------------------------------------------------------------------
# Fonction : rel67b_choose_best_treatment
# Rôle : Sélectionne le traitement le plus plausible pour une relation donnée.
# -----------------------------------------------------------------------------
def rel67b_choose_best_treatment(treatments, posology, text):
    p_role = rel67b_posology_role(posology)
    candidates = []
    for treatment in treatments:
        pair = rel67b_nearest_pair(text, treatment, posology)
        if pair is None:
            continue
        distance, t_span, p_span = pair
        if distance > 220:
            continue
        score = float(distance)
        if t_span[0] <= p_span[0]:
            score -= 35
        else:
            score += 30
        start = min(t_span[1], p_span[1])
        end = max(t_span[0], p_span[0])
        between = text[start:end]
        if '\n' not in between:
            score -= 55
        t_role = rel67b_treatment_role(treatment)
        if p_role != 'generic' and t_role == p_role:
            score -= 180
        if p_role == 'ventilation' and t_role == 'oxygen':
            score += 180
        p_surface = rel67b_ntext(rel67b_esurface(posology))
        t_surface = rel67b_ntext(rel67b_esurface(treatment))
        if t_surface and t_surface in p_surface:
            score -= 220
        candidates.append((score, distance, treatment))
    if not candidates:
        return None
    candidates.sort(key=lambda item: (item[0], item[1]))
    return candidates[0][2]


# -----------------------------------------------------------------------------
# Fonction : rel67b_correct_posology_links
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel67b_correct_posology_links(relations, entities, text):
    treatments = [entity for entity in entities if rel67b_etype(entity) == 'TRAITEMENT' and rel67b_eid(entity)]
    entity_map = {rel67b_eid(entity): entity for entity in entities if rel67b_eid(entity)}
    corrected = 0
    for relation in relations:
        if rel67b_rtype(relation) != 'traitement_a_pour_posologie':
            continue
        current = entity_map.get(rel67b_sid(relation))
        posology = entity_map.get(rel67b_oid(relation))
        if not current or not posology:
            continue
        preferred = rel67b_choose_best_treatment(treatments, posology, text)
        if not preferred:
            continue
        preferred_id = rel67b_eid(preferred)
        if not preferred_id or preferred_id == rel67b_sid(relation):
            continue
        current_distance = rel67b_nearest_distance(text, current, posology)
        preferred_distance = rel67b_nearest_distance(text, preferred, posology)
        role_match = rel67b_posology_role(posology) != 'generic' and rel67b_treatment_role(preferred) == rel67b_posology_role(posology) and (rel67b_treatment_role(current) != rel67b_posology_role(posology))
        clearly_closer = preferred_distance is not None and (current_distance is None or preferred_distance + 60 < current_distance)
        if not (role_match or clearly_closer):
            continue
        relation['identifiant_entite_sujet'] = preferred_id
        if 'subject_id' in relation:
            relation['subject_id'] = preferred_id
        if 'from_id' in relation:
            relation['from_id'] = preferred_id
        relation['note_clinique'] = 'V6.7b : posologie réassignée au traitement local nettement plus plausible.'
        relation['_v67b_corrected'] = True
        corrected += 1
    return corrected


# -----------------------------------------------------------------------------
# Fonction : rel67b_biomarker_family
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel67b_biomarker_family(entity):
    value = rel67b_ntext(str(entity.get('parametre', '')) + ' ' + rel67b_esurface(entity))
    if 'pco2' in value or 'paco2' in value:
        return 'pco2'
    if 'po2' in value or 'pao2' in value:
        return 'po2'
    if re.search('\\bph\\b', value):
        return 'ph'
    if 'creatinine' in value or 'creat ' in value or value.startswith('creat'):
        return 'creatinine'
    if re.search('\\buree\\b', value):
        return 'uree'
    return ''


# -----------------------------------------------------------------------------
# Fonction : rel67b_failure_family
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel67b_failure_family(entity):
    value = rel67b_ntext(rel67b_esurface(entity))
    if 'acidose respiratoire' in value:
        return 'respiratory_acidosis'
    if 'insuffisance renale' in value or value == 'ira':
        return 'renal_failure'
    if 'hypoxemie' in value:
        return 'hypoxemia'
    return ''


# -----------------------------------------------------------------------------
# Fonction : rel67b_recover_safe_biomarker_failure
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel67b_recover_safe_biomarker_failure(relations, entities, text, page_number):
    biomarkers = [entity for entity in entities if rel67b_etype(entity) == 'BIOMARQUEUR' and rel67b_eid(entity)]
    failures = [entity for entity in entities if rel67b_etype(entity) == 'DEFAILLANCE_ORGANE' and rel67b_eid(entity)]
    allowed = {'respiratory_acidosis': {'ph', 'pco2'}, 'renal_failure': {'creatinine', 'uree'}, 'hypoxemia': {'po2'}}
    added = 0
    for failure in failures:
        f_family = rel67b_failure_family(failure)
        if not f_family:
            continue
        for biomarker in biomarkers:
            b_family = rel67b_biomarker_family(biomarker)
            if b_family not in allowed[f_family]:
                continue
            distance = rel67b_nearest_distance(text, biomarker, failure)
            if distance is None or distance > 300:
                continue
            context = rel67b_ntext(rel67b_between_context(text, biomarker, failure, margin=80))
            if not context:
                continue
            if context.count('\n') > 8:
                continue
            if rel67b_add_relation(relations, page_number, rel67b_eid(biomarker), 'biomarqueur_supporte_defaillance_organe', rel67b_eid(failure), rel67b_between_context(text, biomarker, failure, margin=30), 'V6.7b : récupération biomarqueur-défaillance sur famille clinique et proximité stricte.'):
                added += 1
    return added


# -----------------------------------------------------------------------------
# Fonction : rel67b_process_page
# Rôle : Applique toutes les règles de cette étape à une page et met à jour ses entités/relations.
# -----------------------------------------------------------------------------
def rel67b_process_page(page, stats):
    page = copy.deepcopy(page)
    entities = page.get('entities') if isinstance(page.get('entities'), list) else page.get('entites', [])
    if not isinstance(entities, list):
        entities = []
    relations = page.get('relations') if isinstance(page.get('relations'), list) else []
    text = str(page.get('texte_brut') or '')
    page_number = page.get('page', 0)
    entity_map = {rel67b_eid(entity): entity for entity in entities if isinstance(entity, dict) and rel67b_eid(entity)}
    corrected_relations = []
    for relation in relations:
        if not isinstance(relation, dict):
            continue
        relation, changed = rel67b_correct_wrong_type(relation, entity_map)
        if changed:
            stats['wrong_type_corrected'] += 1
        corrected_relations.append(relation)
    relations = corrected_relations
    kept = []
    for relation in relations:
        if rel67b_safe_drop_relation(relation, entity_map, text):
            stats['removed_' + rel67b_rtype(relation)] += 1
            continue
        kept.append(relation)
    relations = rel67b_dedup(kept)
    stats['posology_corrected'] += rel67b_correct_posology_links(relations, entities, text)
    relations = rel67b_dedup(relations)
    stats['added_biomarqueur_supporte_defaillance_organe'] += rel67b_recover_safe_biomarker_failure(relations, entities, text, page_number)
    relations = rel67b_dedup(relations)
    for index, relation in enumerate(relations, start=1):
        relation['identifiant_relation'] = f'P{page_number}_R{index:03d}'
        relation.setdefault('_page', page_number)
    page['relations'] = relations
    return page


# -----------------------------------------------------------------------------
# Fonction : rel67b_process_document
# Rôle : Applique toutes les règles de cette étape à l'ensemble des pages d'un document et agrège les résultats.
# -----------------------------------------------------------------------------
def rel67b_process_document(data):
    output = copy.deepcopy(data)
    stats = Counter()
    pages = output.get('pages', [])
    if not isinstance(pages, list):
        pages = []
    processed_pages = []
    global_relations = []
    for page in pages:
        if not isinstance(page, dict):
            processed_pages.append(page)
            continue
        processed = rel67b_process_page(page, stats)
        processed_pages.append(processed)
        for relation in processed.get('relations', []):
            relation_copy = copy.deepcopy(relation)
            relation_copy.setdefault('page', processed.get('page'))
            global_relations.append(relation_copy)
    output['pages'] = processed_pages
    output['global_relations'] = global_relations
    if isinstance(output.get('document_summary'), dict):
        output['document_summary']['total_relations'] = len(global_relations)
    output['relation_postprocessing_v67b'] = {'version': 'V6.7b_RELATION_CONSERVATIVE', 'source': 'V6.6_PRECISION', 'aggressive_imaging_recovery': False, 'aggressive_treatment_indication_recovery': False, 'automatic_service_recovery': False, 'automatic_microorganism_recovery': False, 'stats': dict(stats), 'total_relations': len(global_relations)}
    return (output, stats)


# -----------------------------------------------------------------------------
# Fonction : rel67b_process_folder
# Rôle : Traite tous les fichiers JSON d'un dossier avec cette version du post-traitement.
# -----------------------------------------------------------------------------
def rel67b_process_folder(input_dir, output_dir):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)
    if not input_dir.is_dir():
        raise FileNotFoundError(f"Dossier d'entrée absent : {input_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)
    for old_file in output_dir.glob('*.json'):
        try:
            old_file.unlink()
        except OSError:
            pass
    files = sorted(input_dir.glob('*.json'))
    print('\n==================================================')
    print('TRACE-Sepsis V6.7b RELATION CONSERVATIVE')
    print('==================================================')
    print('INPUT  =', input_dir)
    print('OUTPUT =', output_dir)
    print('JSON   =', len(files))
    print('==================================================\n')
    global_stats = Counter()
    for index, source in enumerate(files, start=1):
        with source.open('r', encoding='utf-8') as file:
            data = json.load(file)
        before = len(data.get('global_relations', []))
        result, stats = rel67b_process_document(data)
        global_stats.update(stats)
        after = len(result.get('global_relations', []))
        destination = output_dir / source.name
        with destination.open('w', encoding='utf-8') as file:
            json.dump(result, file, ensure_ascii=False, indent=2)
        print(f'✅ {index}/{len(files)} {source.name} | relations {before} -> {after}')
    print('\n--- CORRECTIONS V6.7b ---')
    for key, value in sorted(global_stats.items()):
        print(f'{key:55s} : {value}')
    print('\n🏁 V6.7b RELATION CONSERVATIVE terminée.')

