rel68_DEFAULT_OUTPUT_DIR = rel68_BASE_DIR / 'BEST_43_Relations_V6_8_BALANCED'


# -----------------------------------------------------------------------------
# Fonction : rel68_remove_accents
# Rôle : Supprime les accents pour faciliter les comparaisons textuelles sans modifier la logique clinique.
# -----------------------------------------------------------------------------
def rel68_remove_accents(value):
    value = '' if value is None else str(value)
    value = unicodedata.normalize('NFD', value)
    return ''.join((c for c in value if unicodedata.category(c) != 'Mn'))


# -----------------------------------------------------------------------------
# Fonction : rel68_ntext
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel68_ntext(value):
    value = rel68_remove_accents(value).lower()
    value = value.replace('’', "'").replace('`', "'").replace('_', ' ')
    value = re.sub('\\s+', ' ', value)
    return value.strip(' \t\r\n,;:.()[]{}')


# -----------------------------------------------------------------------------
# Fonction : rel68_eid
# Rôle : Récupère l'identifiant d'une entité de manière compatible avec plusieurs formats JSON.
# -----------------------------------------------------------------------------
def rel68_eid(entity):
    return str(entity.get('identifiant_entite') or entity.get('id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel68_etype
# Rôle : Récupère la catégorie/type d'une entité.
# -----------------------------------------------------------------------------
def rel68_etype(entity):
    return str(entity.get('categorie') or entity.get('type') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel68_esurface
# Rôle : Récupère la mention textuelle principale d'une entité.
# -----------------------------------------------------------------------------
def rel68_esurface(entity):
    return str(entity.get('preuve') or entity.get('name') or entity.get('nom') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel68_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel68_rtype(relation):
    return str(relation.get('type_relation') or relation.get('relation') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel68_sid
# Rôle : Récupère l'identifiant de l'entité sujet d'une relation.
# -----------------------------------------------------------------------------
def rel68_sid(relation):
    return str(relation.get('identifiant_entite_sujet') or relation.get('subject_id') or relation.get('from_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel68_oid
# Rôle : Récupère l'identifiant de l'entité objet d'une relation.
# -----------------------------------------------------------------------------
def rel68_oid(relation):
    return str(relation.get('identifiant_entite_objet') or relation.get('object_id') or relation.get('to_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel68_set_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel68_set_rtype(relation, value):
    relation['type_relation'] = value
    if 'relation' in relation:
        relation['relation'] = value


# -----------------------------------------------------------------------------
# Fonction : rel68_entity_spans
# Rôle : Localise les positions d'une mention dans le texte.
# -----------------------------------------------------------------------------
def rel68_entity_spans(text, entity):
    surfaces = []
    for field in ('preuve', 'name', 'nom'):
        value = entity.get(field)
        if value:
            value = str(value).strip()
            if value and value not in surfaces:
                surfaces.append(value)
    spans = []
    for surface in surfaces:
        try:
            for match in re.finditer(re.escape(surface), text, flags=re.IGNORECASE):
                spans.append((match.start(), match.end()))
        except re.error:
            pass
    return sorted(set(spans))


# -----------------------------------------------------------------------------
# Fonction : rel68_nearest_pair
# Rôle : Recherche la paire d'entités la plus proche dans le texte.
# -----------------------------------------------------------------------------
def rel68_nearest_pair(text, first, second):
    first_spans = rel68_entity_spans(text, first)
    second_spans = rel68_entity_spans(text, second)
    if not first_spans or not second_spans:
        return None
    best = None
    for a in first_spans:
        for b in second_spans:
            if a[1] <= b[0]:
                distance = b[0] - a[1]
            elif b[1] <= a[0]:
                distance = a[0] - b[1]
            else:
                distance = 0
            candidate = (distance, a, b)
            if best is None or candidate[0] < best[0]:
                best = candidate
    return best


# -----------------------------------------------------------------------------
# Fonction : rel68_nearest_distance
# Rôle : Calcule une distance textuelle minimale entre deux mentions pour vérifier leur proximité.
# -----------------------------------------------------------------------------
def rel68_nearest_distance(text, first, second):
    pair = rel68_nearest_pair(text, first, second)
    return None if pair is None else pair[0]


# -----------------------------------------------------------------------------
# Fonction : rel68_between_context
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel68_between_context(text, first, second, margin=70):
    pair = rel68_nearest_pair(text, first, second)
    if pair is None:
        return ''
    _, a, b = pair
    start = min(a[0], b[0])
    end = max(a[1], b[1])
    return text[max(0, start - margin):min(len(text), end + margin)]


# -----------------------------------------------------------------------------
# Fonction : rel68_is_patient_entity
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_is_patient_entity(entity):
    if rel68_etype(entity) != 'DONNEE_PATIENT':
        return False
    surface = rel68_ntext(rel68_esurface(entity))
    return bool('patient' in surface or 'patiente' in surface or re.search('\\b\\d+\\s*ans\\b', surface) or surface.startswith('m. ') or surface.startswith('mme '))


# -----------------------------------------------------------------------------
# Fonction : rel68_patient_priority
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_patient_priority(entity):
    surface = rel68_ntext(rel68_esurface(entity))
    if surface in {'patient', 'patiente'}:
        return 0
    if surface in {'le patient', 'la patiente'}:
        return 1
    if 'patient' in surface or 'patiente' in surface:
        return 2
    return 3


# -----------------------------------------------------------------------------
# Fonction : rel68_relation_exists
# Rôle : Vérifie qu'une relation équivalente n'existe pas déjà.
# -----------------------------------------------------------------------------
def rel68_relation_exists(relations, subject, relation_type, obj):
    return any((rel68_sid(relation) == subject and rel68_rtype(relation) == relation_type and (rel68_oid(relation) == obj) for relation in relations if isinstance(relation, dict)))


# -----------------------------------------------------------------------------
# Fonction : rel68_add_relation
# Rôle : Crée et ajoute une nouvelle relation lorsque les conditions sont satisfaites.
# -----------------------------------------------------------------------------
def rel68_add_relation(relations, page_number, subject, relation_type, obj, proof, note):
    if not subject or not obj or subject == obj:
        return False
    if rel68_relation_exists(relations, subject, relation_type, obj):
        return False
    relations.append({'identifiant_relation': '', 'identifiant_entite_sujet': subject, 'type_relation': relation_type, 'identifiant_entite_objet': obj, 'delai_minutes': None, 'preuve': str(proof or '').strip(), 'note_clinique': note, 'type_inference': 'inference_structurelle_v68', 'confiance': 'elevee', '_v68_added': True, '_page': page_number})
    return True
rel68_SYMPTOM_FROM_FAILURE = ('ralentissement psychomoteur', 'epanchement pleural', 'syndrome pleural', 'angiomes stellaires', 'vesicule biliaire distendue', 'lesion spontanement dense', 'neuropathie de reanimation', 'dilatation des veines', 'aggravation respiratoire', 'difficultes ventilatoires')
rel68_LABEL_FROM_FAILURE = ('acidose metabolique', 'syndrome hepato-renal', 'htap', '3 passages en acfa')
