# -----------------------------------------------------------------------------
# Fonction : rel68_contains_any
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_contains_any(value, patterns):
    return any((pattern in value for pattern in patterns))


# -----------------------------------------------------------------------------
# Fonction : rel68_correct_relation_type
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel68_correct_relation_type(relation, entity_map):
    relation = copy.deepcopy(relation)
    kind = rel68_rtype(relation)
    subject = entity_map.get(rel68_sid(relation), {})
    obj = entity_map.get(rel68_oid(relation), {})
    s = rel68_ntext(rel68_esurface(subject))
    o = rel68_ntext(rel68_esurface(obj))
    new_type = None
    reason = None
    if kind == 'presente_dysfonction_organe' and rel68_contains_any(o, rel68_SYMPTOM_FROM_FAILURE):
        new_type = 'presente_symptome'
        reason = 'V6.8 : manifestation clinique reclassée symptôme.'
    elif kind == 'presente_dysfonction_organe' and rel68_contains_any(o, rel68_LABEL_FROM_FAILURE):
        new_type = 'a_pour_label_nosologique'
        reason = 'V6.8 : diagnostic reclassé label nosologique.'
    elif kind == 'a_pour_label_nosologique' and rel68_contains_any(o, rel68_FAILURE_FROM_LABEL):
        new_type = 'presente_dysfonction_organe'
        reason = 'V6.8 : dysfonction reclassée défaillance.'
    elif kind == 'a_pour_label_nosologique' and rel68_contains_any(o, rel68_SUSPICION_FROM_LABEL):
        new_type = 'presente_suspicion_infection'
        reason = "V6.8 : foyer infectieux reclassé suspicion d'infection."
    elif kind == 'presente_suspicion_infection' and rel68_contains_any(o, rel68_LABEL_FROM_SUSPICION):
        new_type = 'a_pour_label_nosologique'
        reason = 'V6.8 : diagnostic établi reclassé label nosologique.'
    elif kind == 'a_pour_label_nosologique' and rel68_contains_any(o, rel68_SYMPTOM_FROM_LABEL):
        new_type = 'presente_symptome'
        reason = 'V6.8 : manifestation reclassée symptôme.'
    elif kind == 'presente_symptome' and rel68_contains_any(o, rel68_LABEL_FROM_SYMPTOM):
        new_type = 'a_pour_label_nosologique'
        reason = 'V6.8 : diagnostic reclassé label.'
    elif kind == 'presente_symptome' and 'diminution du syndrome inflammatoire biologique' in o:
        new_type = 'patient_a_pour_evolution'
        reason = 'V6.8 : évolution biologique reclassée.'
    elif kind == 'presente_symptome' and ('cicatrice inflammatoire avec ecoulement purulent' in o or o == 'angiocholite'):
        new_type = 'presente_suspicion_infection'
        reason = 'V6.8 : manifestation infectieuse reclassée suspicion.'
    elif kind == 'presente_symptome' and o == 'hypoxie':
        new_type = 'presente_dysfonction_organe'
        reason = 'V6.8 : hypoxie reclassée dysfonction.'
    elif kind == 'biomarqueur_supporte_defaillance_organe' and (any((marker in s for marker in ('ph', 'hco3', 'hc03'))) and 'acidose metabolique' in o or ('hypophosphoremie' in s and 'syndrome de renutrition' in o)):
        new_type = 'biomarqueur_est_critere_de'
        reason = 'V6.8 : biomarqueur reclassé critère du diagnostic.'
    if new_type and new_type != kind:
        rel68_set_rtype(relation, new_type)
        relation['_v68_original_relation_type'] = kind
        relation['_v68_corrected'] = True
        relation['note_clinique'] = reason
        return (relation, True)
    return (relation, False)
rel68_DROP_ALL_TYPES = {'imagerie_objective_defaillance', 'score_sofa_inclut_score_neurologique', 'score_sofa_inclut_signe_vital'}
rel68_BAD_TREATMENT_ADMIN = {'na', 'g5%', 'pm', 'potassium', 'antibiotherapie', 'o2'}
rel68_BAD_POSOLOGY_TREATMENT = {'na', 'antibiotherapie', 'transfusion', 'iot / vac', 'ventilation en sdra', 'vt 420', 'colimycine', 'remplissage vasculaire', 'o2', 'mode : vac', 'tracheotomie', 'intubation'}
