# -----------------------------------------------------------------------------
# Fonction : rel68_is_invalid_patient_anchor
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_is_invalid_patient_anchor(surface):
    value = rel68_ntext(surface)
    return bool(re.match('^(?:taille\\b|bmi\\b|ce jour$|\\d+\\s*ans$)', value))


# -----------------------------------------------------------------------------
# Fonction : rel68_biomarker_failure_allowed
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_biomarker_failure_allowed(subject, obj):
    """
    Filtre déterministe construit à partir des familles
    biomarqueur-défaillance réellement cohérentes.
    """
    s = rel68_ntext(str(subject.get('parametre', '')) + ' ' + rel68_esurface(subject))
    o = rel68_ntext(rel68_esurface(obj))
    if any((marker in s for marker in ('creat', 'uree', 'hyperkaliem'))) and any((marker in o for marker in ('insuffisance renale', 'ira', 'anurie'))):
        return True
    if any((marker in s for marker in ('p/f', 'rapport p/f', 'pao2', 'po2'))) and any((marker in o for marker in ('sdra', 'hypox', 'defaillance respiratoire'))):
        return True
    if (re.search('\\bph\\b', s) or 'pco2' in s or 'paco2' in s) and any((marker in o for marker in ('acidose respiratoire', 'hypercapnique', 'detresse respiratoire'))):
        return True
    if any((marker in s for marker in ('hemoglob', 'ldh', 'haptoglob', 'plaquette'))) and 'hematolog' in o:
        return True
    if 'lactate' in s and 'hemodynam' in o:
        return True
    if (re.search('\\btp\\b', s) or 'temps de quick' in s) and 'hepat' in o:
        return True
    return False


# -----------------------------------------------------------------------------
# Fonction : rel68_should_drop_relation
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_should_drop_relation(relation, entity_map):
    kind = rel68_rtype(relation)
    if kind in rel68_DROP_ALL_TYPES:
        return (True, 'zero_tp_relation_type')
    subject = entity_map.get(rel68_sid(relation), {})
    obj = entity_map.get(rel68_oid(relation), {})
    s = rel68_ntext(rel68_esurface(subject))
    o = rel68_ntext(rel68_esurface(obj))
    if kind == 'traitement_administre_a':
        if s in rel68_BAD_TREATMENT_ADMIN:
            return (True, 'generic_treatment_admin')
        if rel68_is_invalid_patient_anchor(rel68_esurface(obj)):
            return (True, 'invalid_patient_anchor')
    if kind == 'traitement_a_pour_posologie' and s in rel68_BAD_POSOLOGY_TREATMENT:
        return (True, 'low_precision_posology_subject')
    if kind == 'presente_symptome' and o in rel68_BAD_SYMPTOMS:
        return (True, 'low_precision_symptom')
    if kind == 'a_pour_label_nosologique' and o in rel68_BAD_LABELS:
        return (True, 'generic_inflammatory_label')
    if kind == 'biomarqueur_supporte_defaillance_organe' and (not rel68_biomarker_failure_allowed(subject, obj)):
        return (True, 'unsupported_biomarker_failure_family')
    if kind == 'evenement_associe_evolution':
        proof = rel68_ntext(relation.get('preuve', ''))
        if not re.search('\\b(?:j\\d+|jour|jours|heures?|apres|après|puis|ensuite|le\\s+\\d{1,2}/\\d{1,2})\\b', proof):
            return (True, 'weak_event_evolution')
    if kind == 'traitement_indique_par_label_nosologique':
        proof = rel68_ntext(relation.get('preuve', ''))
        if not any((cue in proof for cue in ('indique pour', 'indiquee pour', 'pour traiter', 'traitement de', 'traite pour', 'mise sous', 'mis sous'))):
            return (True, 'weak_treatment_indication')
    return (False, '')
rel68_PATIENT_CENTERED = {'presente_symptome', 'a_pour_label_nosologique', 'presente_dysfonction_organe', 'patient_a_pour_evolution', 'presente_suspicion_infection', 'a_pour_contexte_acquisition'}


# -----------------------------------------------------------------------------
# Fonction : rel68_semantic_relation_key
# Rôle : Construit une clé unique pour comparer et dédupliquer les relations.
# -----------------------------------------------------------------------------
def rel68_semantic_relation_key(relation, entity_map):
    kind = rel68_rtype(relation)
    subject = entity_map.get(rel68_sid(relation), {})
    obj = entity_map.get(rel68_oid(relation), {})
    s = rel68_ntext(rel68_esurface(subject))
    o = rel68_ntext(rel68_esurface(obj))
    if kind in rel68_PATIENT_CENTERED and rel68_is_patient_entity(subject):
        s = '__patient__'
    if kind in {'traitement_administre_a', 'service_medical_accueille'} and rel68_is_patient_entity(obj):
        o = '__patient__'
    return (kind, s, o)


# -----------------------------------------------------------------------------
# Fonction : rel68_semantic_dedup
# Rôle : Supprime les doublons en conservant une seule représentation de chaque élément.
# -----------------------------------------------------------------------------
def rel68_semantic_dedup(relations, entity_map, stats):
    grouped = {}
    for relation in relations:
        if not isinstance(relation, dict):
            continue
        key = rel68_semantic_relation_key(relation, entity_map)
        grouped.setdefault(key, []).append(relation)
    output = []
    for key, group in grouped.items():
        if len(group) == 1:
            output.append(group[0])
            continue
        kind = key[0]
        if kind in rel68_PATIENT_CENTERED:
            keeper = min(group, key=lambda relation: rel68_patient_priority(entity_map.get(rel68_sid(relation), {})))
        elif kind in {'traitement_administre_a', 'service_medical_accueille'}:
            keeper = min(group, key=lambda relation: rel68_patient_priority(entity_map.get(rel68_oid(relation), {})))
        else:
            keeper = group[0]
        output.append(keeper)
        stats['semantic_duplicates_removed'] += len(group) - 1
    return output


# -----------------------------------------------------------------------------
# Fonction : rel68_recover_micro_foyer
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_recover_micro_foyer(relations, entities, text, page_number):
    organisms = [entity for entity in entities if rel68_etype(entity) == 'MICRO_ORGANISME' and rel68_eid(entity)]
    foyers = [entity for entity in entities if rel68_etype(entity) == 'FOYER_INFECTIEUX' and rel68_eid(entity)]
    added = 0
    for organism in organisms:
        org_norm = rel68_ntext(rel68_esurface(organism))
        if not org_norm or len(org_norm) < 3:
            continue
        for foyer in foyers:
            foyer_norm = rel68_ntext(rel68_esurface(foyer))
            if not foyer_norm:
                continue
            strong = org_norm in foyer_norm
            distance = rel68_nearest_distance(text, organism, foyer)
            context = rel68_ntext(rel68_between_context(text, organism, foyer, margin=100))
            if not strong and distance is not None and (distance <= 220) and any((cue in context for cue in ('a ', 'à ', 'positif', 'positive', 'isole', 'isolee', 'pdp', 'ecbu', 'hemoculture', 'bacteriologie', 'culture'))):
                strong = True
            if not strong:
                continue
            if rel68_add_relation(relations, page_number, rel68_eid(organism), 'micro_organisme_isole_dans', rel68_eid(foyer), rel68_between_context(text, organism, foyer, margin=40), 'V6.8 : microorganisme-foyer sur inclusion/proximité microbiologique forte.'):
                added += 1
    return added


# -----------------------------------------------------------------------------
# Fonction : rel68_vital_family
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_vital_family(entity):
    value = rel68_ntext(rel68_esurface(entity))
    if any((marker in value for marker in ('spo2', 'sao2', 'sat o2', 'saturation', 'desaturation', 'polypnee', 'tachypnee', 'frequence respiratoire', 'cycles/min'))):
        return 'respiratory'
    if any((marker in value for marker in ('pas ', 'pression arterielle', 'tension arterielle', 'hypotension', 'tachycardie', 'frequence cardiaque'))):
        return 'shock'
    return ''


# -----------------------------------------------------------------------------
# Fonction : rel68_failure_family
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_failure_family(entity):
    value = rel68_ntext(rel68_esurface(entity))
    if any((marker in value for marker in ('detresse respiratoire', 'defaillance respiratoire', 'sdra', ' dra', 'hypox'))):
        return 'respiratory'
    if any((marker in value for marker in ('choc', 'collapsus', 'defaillance hemodynamique'))):
        return 'shock'
    if any((marker in value for marker in ('insuffisance renale', 'ira'))):
        return 'renal'
    return ''


# -----------------------------------------------------------------------------
# Fonction : rel68_recover_vital_failure
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_recover_vital_failure(relations, entities, text, page_number):
    vitals = [entity for entity in entities if rel68_etype(entity) == 'SIGNE_VITAL' and rel68_eid(entity) and rel68_vital_family(entity)]
    failures = [entity for entity in entities if rel68_etype(entity) == 'DEFAILLANCE_ORGANE' and rel68_eid(entity) and rel68_failure_family(entity)]
    added = 0
    for vital in vitals:
        family = rel68_vital_family(vital)
        candidates = []
        for failure in failures:
            if rel68_failure_family(failure) != family:
                continue
            distance = rel68_nearest_distance(text, vital, failure)
            if distance is None or distance > 260:
                continue
            candidates.append((distance, failure))
        if not candidates:
            continue
        candidates.sort(key=lambda item: item[0])
        distance, failure = candidates[0]
        if rel68_add_relation(relations, page_number, rel68_eid(vital), 'signe_vital_supporte_defaillance_organe', rel68_eid(failure), rel68_between_context(text, vital, failure, margin=40), 'V6.8 : signe vital-défaillance sur famille physiologique et proximité.'):
            added += 1
    return added


# -----------------------------------------------------------------------------
# Fonction : rel68_treatment_failure_family
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_treatment_failure_family(entity):
    value = rel68_ntext(rel68_esurface(entity))
    if any((marker in value for marker in ('vni', 'ventilation', 'intub', 'iot'))):
        return 'respiratory'
    if any((marker in value for marker in ('noradrenaline', 'adrenaline', 'dobutamine', 'remplissage vasculaire', 'serum physiologique'))):
        return 'shock'
    if any((marker in value for marker in ('dialyse', 'eer', 'epuration extra'))):
        return 'renal'
    return ''


# -----------------------------------------------------------------------------
# Fonction : rel68_recover_treatment_failure
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_recover_treatment_failure(relations, entities, text, page_number):
    treatments = [entity for entity in entities if rel68_etype(entity) == 'TRAITEMENT' and rel68_eid(entity) and rel68_treatment_failure_family(entity)]
    failures = [entity for entity in entities if rel68_etype(entity) == 'DEFAILLANCE_ORGANE' and rel68_eid(entity) and rel68_failure_family(entity)]
    added = 0
    for treatment in treatments:
        family = rel68_treatment_failure_family(treatment)
        candidates = []
        for failure in failures:
            if rel68_failure_family(failure) != family:
                continue
            distance = rel68_nearest_distance(text, treatment, failure)
            if distance is None or distance > 320:
                continue
            candidates.append((distance, failure))
        if not candidates:
            continue
        candidates.sort(key=lambda item: item[0])
        _, failure = candidates[0]
        if rel68_add_relation(relations, page_number, rel68_eid(treatment), 'traitement_cible_defaillance', rel68_eid(failure), rel68_between_context(text, treatment, failure, margin=45), 'V6.8 : traitement-défaillance sur famille thérapeutique forte.'):
            added += 1
    return added


# -----------------------------------------------------------------------------
# Fonction : rel68_criterion_pair_allowed
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_criterion_pair_allowed(biomarker, label):
    b = rel68_ntext(str(biomarker.get('parametre', '')) + ' ' + rel68_esurface(biomarker))
    l = rel68_ntext(rel68_esurface(label))
    if any((x in b for x in ('natremie', 'sodium'))) and 'hyponatrem' in l:
        return True
    if 'lipas' in b and 'pancreat' in l:
        return True
    if any((x in b for x in ('ph', 'hco3', 'hc03', 'bicarbon'))) and 'acidose metabolique' in l:
        return True
    if 'hypophosph' in b and 'renutrition' in l:
        return True
    if any((x in b for x in ('plaquette', 'haptoglob', 'ldh'))) and 'mat' in l:
        return True
    if any((x in b for x in ('crp', 'gb', 'leucocyt', 'hyperleucocyt'))) and 'syndrome inflammatoire' in l:
        return True
    return False


# -----------------------------------------------------------------------------
# Fonction : rel68_recover_biomarker_criterion
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_recover_biomarker_criterion(relations, entities, text, page_number):
    biomarkers = [entity for entity in entities if rel68_etype(entity) == 'BIOMARQUEUR' and rel68_eid(entity)]
    labels = [entity for entity in entities if rel68_etype(entity) == 'LABEL_NOSOLOGIQUE' and rel68_eid(entity)]
    added = 0
    for biomarker in biomarkers:
        candidates = []
        for label in labels:
            if not rel68_criterion_pair_allowed(biomarker, label):
                continue
            distance = rel68_nearest_distance(text, biomarker, label)
            if distance is None or distance > 300:
                continue
            candidates.append((distance, label))
        if not candidates:
            continue
        candidates.sort(key=lambda item: item[0])
        _, label = candidates[0]
        if rel68_add_relation(relations, page_number, rel68_eid(biomarker), 'biomarqueur_est_critere_de', rel68_eid(label), rel68_between_context(text, biomarker, label, margin=45), 'V6.8 : biomarqueur-critère sur paire clinique fortement typée.'):
            added += 1
    return added


# -----------------------------------------------------------------------------
# Fonction : rel68_recover_acquisition
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_recover_acquisition(relations, entities, text, page_number):
    contexts = [entity for entity in entities if rel68_etype(entity) == 'CONTEXTE_ACQUISITION' and rel68_eid(entity)]
    patients = [entity for entity in entities if rel68_is_patient_entity(entity) and rel68_eid(entity)]
    clinical_subjects = [entity for entity in entities if rel68_etype(entity) in {'FOYER_INFECTIEUX', 'LABEL_NOSOLOGIQUE'} and rel68_eid(entity)]
    added = 0
    for context in contexts:
        c = rel68_ntext(rel68_esurface(context))
        if not c:
            continue
        direct = []
        for subject in clinical_subjects:
            s = rel68_ntext(rel68_esurface(subject))
            if c in s or ('nosocomial' in c and 'nosocomial' in s) or ('communautaire' in c and 'communautaire' in s) or ('ventilation' in c and 'ventilation' in s) or ('inhalation' in c and 'inhalation' in s):
                direct.append(subject)
        for subject in direct[:1]:
            if rel68_add_relation(relations, page_number, rel68_eid(subject), 'a_pour_contexte_acquisition', rel68_eid(context), rel68_between_context(text, subject, context, margin=35), "V6.8 : contexte d'acquisition explicitement porté par le diagnostic."):
                added += 1
        if ('infection nosocomiale : oui' in rel68_ntext(text) or 'infection nosocomiale: oui' in rel68_ntext(text)) and patients and ('nosocomial' in c):
            patient = min(patients, key=rel68_patient_priority)
            if rel68_add_relation(relations, page_number, rel68_eid(patient), 'a_pour_contexte_acquisition', rel68_eid(context), rel68_esurface(context), 'V6.8 : contexte nosocomial explicitement affirmé pour le patient.'):
                added += 1
    return added


# -----------------------------------------------------------------------------
# Fonction : rel68_temporal_tokens
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_temporal_tokens(value):
    value = rel68_ntext(value)
    tokens = set(re.findall('\\b(?:t0|t30|t60|j\\d+|\\d{1,2}/\\d{1,2}(?:/\\d{2,4})?)\\b', value))
    return tokens


# -----------------------------------------------------------------------------
# Fonction : rel68_recover_biomarker_time
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_recover_biomarker_time(relations, entities, text, page_number):
    biomarkers = [entity for entity in entities if rel68_etype(entity) == 'BIOMARQUEUR' and rel68_eid(entity)]
    events = [entity for entity in entities if rel68_etype(entity) == 'EVENEMENT_TEMPOREL' and rel68_eid(entity)]
    added = 0
    for biomarker in biomarkers:
        b_tokens = rel68_temporal_tokens(rel68_esurface(biomarker))
        if not b_tokens:
            continue
        for event in events:
            e_tokens = rel68_temporal_tokens(rel68_esurface(event))
            if not b_tokens & e_tokens:
                continue
            if rel68_add_relation(relations, page_number, rel68_eid(biomarker), 'biomarqueur_obtenu_a', rel68_eid(event), rel68_between_context(text, biomarker, event, margin=25), 'V6.8 : temps explicite partagé entre biomarqueur et événement.'):
                added += 1
    return added
rel68_ADEQUATE_CUES = ('sensible a', 'sensible à', 'sensible', 'sensibilite', 'sensibilité', 'antibiogramme', 'adapte a', 'adapté à', 'adaptee a', 'adaptée à')
rel68_INADEQUATE_CUES = ('resistant a', 'résistant à', 'resistante a', 'résistante à', 'resistance', 'résistance', 'intermediaire', 'intermédiaire')


# -----------------------------------------------------------------------------
# Fonction : rel68_is_antimicrobial
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_is_antimicrobial(entity):
    value = rel68_ntext(rel68_esurface(entity))
    return any((marker in value for marker in ('augmentin', 'claforan', 'ticar', 'cipro', 'tazoc', 'vanco', 'rifam', 'dapto', 'ceftaz', 'imipen', 'tienam', 'amik', 'flucon', 'ceftriax', 'meropen', 'antibiot')))


# -----------------------------------------------------------------------------
# Fonction : rel68_recover_antibiotic_relation
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel68_recover_antibiotic_relation(relations, entities, text, page_number):
    treatments = [entity for entity in entities if rel68_etype(entity) == 'TRAITEMENT' and rel68_eid(entity) and rel68_is_antimicrobial(entity)]
    organisms = [entity for entity in entities if rel68_etype(entity) == 'MICRO_ORGANISME' and rel68_eid(entity)]
    added = 0
    for treatment in treatments:
        for organism in organisms:
            distance = rel68_nearest_distance(text, treatment, organism)
            if distance is None or distance > 350:
                continue
            context_raw = rel68_between_context(text, treatment, organism, margin=100)
            context = rel68_ntext(context_raw)
            relation_type = None
            if any((cue in context for cue in rel68_INADEQUATE_CUES)):
                relation_type = 'antibiotique_inadequat_pour'
            elif any((rel68_ntext(cue) in context for cue in rel68_ADEQUATE_CUES)):
                relation_type = 'antibiotique_adequat_pour'
            if not relation_type:
                continue
            if rel68_add_relation(relations, page_number, rel68_eid(treatment), relation_type, rel68_eid(organism), context_raw, "V6.8 : adéquation antibiotique sur signal explicite d'antibiogramme."):
                added += 1
    return added


# -----------------------------------------------------------------------------
# Fonction : rel68_process_page
# Rôle : Applique toutes les règles de cette étape à une page et met à jour ses entités/relations.
# -----------------------------------------------------------------------------
def rel68_process_page(page, stats):
    page = copy.deepcopy(page)
    entities = page.get('entities') if isinstance(page.get('entities'), list) else page.get('entites', [])
    if not isinstance(entities, list):
        entities = []
    relations = page.get('relations') if isinstance(page.get('relations'), list) else []
    text = str(page.get('texte_brut') or '')
    page_number = page.get('page', 0)
    entity_map = {rel68_eid(entity): entity for entity in entities if isinstance(entity, dict) and rel68_eid(entity)}
    corrected = []
    for relation in relations:
        if not isinstance(relation, dict):
            continue
        relation, changed = rel68_correct_relation_type(relation, entity_map)
        if changed:
            stats['wrong_type_corrected'] += 1
        corrected.append(relation)
    relations = corrected
    kept = []
    for relation in relations:
        drop, reason = rel68_should_drop_relation(relation, entity_map)
        if drop:
            stats['removed_' + reason] += 1
            continue
        kept.append(relation)
    relations = kept
    relations = rel68_semantic_dedup(relations, entity_map, stats)
    stats['added_micro_organisme_isole_dans'] += rel68_recover_micro_foyer(relations, entities, text, page_number)
    stats['added_signe_vital_supporte_defaillance_organe'] += rel68_recover_vital_failure(relations, entities, text, page_number)
    stats['added_traitement_cible_defaillance'] += rel68_recover_treatment_failure(relations, entities, text, page_number)
    stats['added_biomarqueur_est_critere_de'] += rel68_recover_biomarker_criterion(relations, entities, text, page_number)
    stats['added_a_pour_contexte_acquisition'] += rel68_recover_acquisition(relations, entities, text, page_number)
    stats['added_biomarqueur_obtenu_a'] += rel68_recover_biomarker_time(relations, entities, text, page_number)
    stats['added_antibiotic_adequacy'] += rel68_recover_antibiotic_relation(relations, entities, text, page_number)
    relations = rel68_semantic_dedup(relations, entity_map, stats)
    for index, relation in enumerate(relations, start=1):
        relation['identifiant_relation'] = f'P{page_number}_R{index:03d}'
        relation.setdefault('_page', page_number)
    page['relations'] = relations
    return page


# -----------------------------------------------------------------------------
# Fonction : rel68_process_document
# Rôle : Applique toutes les règles de cette étape à l'ensemble des pages d'un document et agrège les résultats.
# -----------------------------------------------------------------------------
def rel68_process_document(data):
    output = copy.deepcopy(data)
    stats = Counter()
    pages = output.get('pages', [])
    if not isinstance(pages, list):
        pages = []
    processed_pages = []
    global_relations = []
    for page in pages:
        if not isinstance(page, dict):
            processed_pages.append(page)
            continue
        processed = rel68_process_page(page, stats)
        processed_pages.append(processed)
        for relation in processed.get('relations', []):
            relation_copy = copy.deepcopy(relation)
            relation_copy.setdefault('page', processed.get('page'))
            global_relations.append(relation_copy)
    output['pages'] = processed_pages
    output['global_relations'] = global_relations
    if isinstance(output.get('document_summary'), dict):
        output['document_summary']['total_relations'] = len(global_relations)
    output['relation_postprocessing_v68'] = {'version': 'V6.8_RELATION_BALANCED', 'source': 'V6.7b_RELATION_CONSERVATIVE', 'stats': dict(stats), 'total_relations': len(global_relations)}
    return (output, stats)


# -----------------------------------------------------------------------------
# Fonction : rel68_process_folder
# Rôle : Traite tous les fichiers JSON d'un dossier avec cette version du post-traitement.
# -----------------------------------------------------------------------------
def rel68_process_folder(input_dir, output_dir):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)
    if not input_dir.is_dir():
        raise FileNotFoundError(f"Dossier d'entrée absent : {input_dir}")
    output_dir.mkdir(parents=True, exist_ok=True)
    for old_file in output_dir.glob('*.json'):
        try:
            old_file.unlink()
        except OSError:
            pass
    json_files = sorted(input_dir.glob('*.json'))
    print('\n============================================================')
    print('TRACE-Sepsis — V6.8 RELATION BALANCED')
    print('============================================================')
