# -----------------------------------------------------------------------------
# Fonction : rel69b_is_patient_entity
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_is_patient_entity(entity):
    if rel69b_etype(entity) != 'DONNEE_PATIENT':
        return False
    value = rel69b_norm(rel69b_esurface(entity))
    if not value:
        return False
    if value == 'ce jour' or value.startswith('taille') or value.startswith('bmi') or value.startswith('poids'):
        return False
    return bool('patient' in value or 'patiente' in value or re.search('\\b(?:m\\.|mr|mme)\\s+[a-z]', value) or re.search('\\b\\d{2}\\s*ans\\b', value) or (value in {'homme', 'femme'}))


# -----------------------------------------------------------------------------
# Fonction : rel69b_patient_priority
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_patient_priority(entity):
    value = rel69b_norm(rel69b_esurface(entity))
    if value in {'patient', 'patiente'}:
        return 0
    if value in {'le patient', 'la patiente'}:
        return 1
    if 'patient de' in value or 'patiente de' in value:
        return 2
    if value.startswith('mr ') or value.startswith('m. ') or value.startswith('mme '):
        return 3
    if 'patient' in value or 'patiente' in value:
        return 4
    return 5


# -----------------------------------------------------------------------------
# Fonction : rel69b_surfaces
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_surfaces(entity):
    output = []
    for field in ('preuve', 'name', 'nom'):
        value = entity.get(field)
        if value:
            value = str(value).strip()
            if value and value not in output:
                output.append(value)
    return output


# -----------------------------------------------------------------------------
# Fonction : rel69b_spans
# Rôle : Localise les positions d'une mention dans le texte.
# -----------------------------------------------------------------------------
def rel69b_spans(text, entity):
    output = []
    for surface in rel69b_surfaces(entity):
        if len(surface) < 2:
            continue
        try:
            for match in re.finditer(re.escape(surface), text, flags=re.IGNORECASE):
                output.append((match.start(), match.end()))
        except re.error:
            continue
    return sorted(set(output))


# -----------------------------------------------------------------------------
# Fonction : rel69b_nearest_pair
# Rôle : Recherche la paire d'entités la plus proche dans le texte.
# -----------------------------------------------------------------------------
def rel69b_nearest_pair(text, first, second):
    a_spans = rel69b_spans(text, first)
    b_spans = rel69b_spans(text, second)
    if not a_spans or not b_spans:
        return None
    best = None
    for a in a_spans:
        for b in b_spans:
            if a[1] <= b[0]:
                distance = b[0] - a[1]
            elif b[1] <= a[0]:
                distance = a[0] - b[1]
            else:
                distance = 0
            candidate = (distance, a, b)
            if best is None or distance < best[0]:
                best = candidate
    return best


# -----------------------------------------------------------------------------
# Fonction : rel69b_nearest_distance
# Rôle : Calcule une distance textuelle minimale entre deux mentions pour vérifier leur proximité.
# -----------------------------------------------------------------------------
def rel69b_nearest_distance(text, first, second):
    pair = rel69b_nearest_pair(text, first, second)
    return None if pair is None else pair[0]


# -----------------------------------------------------------------------------
# Fonction : rel69b_context_between
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel69b_context_between(text, first, second, margin=60):
    pair = rel69b_nearest_pair(text, first, second)
    if pair is None:
        return ''
    _, a, b = pair
    start = min(a[0], b[0])
    end = max(a[1], b[1])
    return text[max(0, start - margin):min(len(text), end + margin)]


# -----------------------------------------------------------------------------
# Fonction : rel69b_build_entity_map
# Rôle : Construit un dictionnaire d'entités indexées par identifiant pour résoudre les relations.
# -----------------------------------------------------------------------------
def rel69b_build_entity_map(data):
    result = {}
    for entity in data.get('global_entities', []):
        if isinstance(entity, dict) and rel69b_eid(entity):
            result[rel69b_eid(entity)] = entity
    for page in data.get('pages', []):
        if not isinstance(page, dict):
            continue
        page_entities = page.get('entities')
        if not isinstance(page_entities, list):
            page_entities = page.get('entites', [])
        if not isinstance(page_entities, list):
            continue
        for entity in page_entities:
            if isinstance(entity, dict) and rel69b_eid(entity):
                result[rel69b_eid(entity)] = entity
    return result


# -----------------------------------------------------------------------------
# Fonction : rel69b_semantic_relation_exists
# Rôle : Vérifie qu'une relation équivalente n'existe pas déjà.
# -----------------------------------------------------------------------------
def rel69b_semantic_relation_exists(relations, relation_type, subject, obj, entity_map):
    target_s = rel69b_norm(rel69b_esurface(subject))
    target_o = rel69b_norm(rel69b_esurface(obj))
    for relation in relations:
        if not isinstance(relation, dict):
            continue
        if rel69b_rtype(relation) != relation_type:
            continue
        s_entity = entity_map.get(rel69b_sid(relation), {})
        o_entity = entity_map.get(rel69b_oid(relation), {})
        s = rel69b_norm(rel69b_esurface(s_entity))
        o = rel69b_norm(rel69b_esurface(o_entity))
        if s == target_s and o == target_o:
            return True
        if rel69b_is_patient_entity(subject) and rel69b_is_patient_entity(s_entity) and (o == target_o):
            return True
        if rel69b_is_patient_entity(obj) and rel69b_is_patient_entity(o_entity) and (s == target_s):
            return True
    return False


# -----------------------------------------------------------------------------
# Fonction : rel69b_add_relation
# Rôle : Crée et ajoute une nouvelle relation lorsque les conditions sont satisfaites.
# -----------------------------------------------------------------------------
def rel69b_add_relation(relations, relation_type, subject, obj, page_number, proof, rule, entity_map, stats):
    subject_id = rel69b_eid(subject)
    object_id = rel69b_eid(obj)
    if not subject_id or not object_id or subject_id == object_id:
        return False
    if rel69b_semantic_relation_exists(relations, relation_type, subject, obj, entity_map):
        return False
    relation = {'identifiant_relation': '', 'identifiant_entite_sujet': subject_id, 'type_relation': relation_type, 'identifiant_entite_objet': object_id, 'delai_minutes': None, 'preuve': str(proof or '').strip(), 'note_clinique': 'V6.9b RECALL-CONTROLLED : ' + rule, 'type_inference': 'recall_controlled_v69b', 'confiance': 'elevee', '_v69b_added': True, '_v69b_rule': rule, '_page': page_number, 'page': page_number}
    relations.append(relation)
    stats['added_' + relation_type] += 1
    return True

# --- rel69b_NEGATION_PATTERN ---
# Expression régulière utilisée pour détecter un motif textuel précis dans les preuves ou le texte brut.
rel69b_NEGATION_PATTERN = re.compile("\n    \\b(\n        pas\\s+de|\n        pas\\s+d'|\n        absence\\s+de|\n        sans|\n        aucun|\n        aucune|\n        non\\s+retrouve|\n        non\\s+retrouvee\n    )\\b\n    ", flags=re.IGNORECASE | re.VERBOSE)
rel69b_BAD_GENERIC_TREATMENTS = {'na', 'pm', 'antibiotherapie', 'anticoagulation', 'transfusion', 'g5%', 'cv', 'aerosol', 'aerosols'}


# -----------------------------------------------------------------------------
# Fonction : rel69b_candidate_is_negated
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_candidate_is_negated(text, entity):
    entity_spans = rel69b_spans(text, entity)
    if not entity_spans:
        return False
    start = entity_spans[0][0]
    prefix = text[max(0, start - 45):start]
    return bool(rel69b_NEGATION_PATTERN.search(prefix))
rel69b_TREATMENT_ADMIN_CUES = ('sous ', 'mis sous', 'mise sous', 'traite par', 'traitee par', 'traitement par', 'recoit', 'reçoit', 'administr', 'instaur', 'introdu', 'prescrit', 'poursuite', 'poursuivi', 'mise en place', 'realisation', 'réalisation')


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_treatment_admin
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_recover_treatment_admin(relations, entities, patients, text, page_number, entity_map, stats):
    if not patients:
        return
    patient = min(patients, key=rel69b_patient_priority)
    candidates = []
    for treatment in entities:
        if rel69b_etype(treatment) != 'TRAITEMENT':
            continue
        value = rel69b_norm(rel69b_esurface(treatment))
        if not value or value in rel69b_BAD_GENERIC_TREATMENTS:
            continue
        if rel69b_candidate_is_negated(text, treatment):
            continue
        if rel69b_semantic_relation_exists(relations, 'traitement_administre_a', treatment, patient, entity_map):
            continue
        treatment_spans = rel69b_spans(text, treatment)
        if not treatment_spans:
            continue
        pos = treatment_spans[0][0]
        local = rel69b_norm(text[max(0, pos - 100):min(len(text), treatment_spans[0][1] + 100)])
        strong_cue = any((rel69b_norm(cue) in local for cue in rel69b_TREATMENT_ADMIN_CUES))
        medication_like = bool(re.search('\n                (\n                    amik|tienam|vanco|tazoc|claforan|\n                    augmentin|flagyl|oflocet|ciflox|\n                    ceftriax|noradren|adrenalin|\n                    lasilix|lovenox|inexium|insulin|\n                    oxygen|oxygene|vni|ventilation|\n                    intub|extub|tracheot|dialys|\n                    hemofiltr|serum\\s+physiologique\n                )\n                ', value, flags=re.VERBOSE))
        if not (strong_cue or medication_like):
            continue
        candidates.append((0 if strong_cue else 1, treatment))
    candidates.sort(key=lambda item: item[0])
    added = 0
    for _, treatment in candidates:
        if added >= rel69b_MAX_ADD_TREATMENT_ADMIN:
            break
        if rel69b_add_relation(relations, 'traitement_administre_a', treatment, patient, page_number, rel69b_esurface(treatment), "TRAITEMENT proche du contexte patient avec indice d'administration.", entity_map, stats):
            added += 1


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_posology
# Rôle : Récupère des posologies candidates lorsque les conditions de l'étape l'autorisent.
# -----------------------------------------------------------------------------
def rel69b_recover_posology(relations, entities, text, page_number, entity_map, stats):
    treatments = [entity for entity in entities if rel69b_etype(entity) == 'TRAITEMENT' and rel69b_norm(rel69b_esurface(entity)) not in rel69b_BAD_GENERIC_TREATMENTS]
    doses = [entity for entity in entities if rel69b_etype(entity) == 'POSOLOGIE']
    pairs = []
    for dose in doses:
        best = None
        for treatment in treatments:
            distance = rel69b_nearest_distance(text, treatment, dose)
            if distance is None or distance > 70:
                continue
            candidate = (distance, treatment, dose)
            if best is None or distance < best[0]:
                best = candidate
        if best is not None:
            pairs.append(best)
    pairs.sort(key=lambda item: item[0])
    added = 0
    for _, treatment, dose in pairs:
        if added >= rel69b_MAX_ADD_POSOLOGY:
            break
        if rel69b_add_relation(relations, 'traitement_a_pour_posologie', treatment, dose, page_number, rel69b_context_between(text, treatment, dose, margin=25), 'POSOLOGIE associée au TRAITEMENT le plus proche (<=70 caractères).', entity_map, stats):
            added += 1


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_symptoms
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_recover_symptoms(relations, entities, patients, text, page_number, entity_map, stats):
    if not patients:
        return
    patient = min(patients, key=rel69b_patient_priority)
    symptoms = []
    for symptom in entities:
        if rel69b_etype(symptom) != 'SYMPTOME':
            continue
        if rel69b_candidate_is_negated(text, symptom):
            continue
        if not rel69b_spans(text, symptom):
            continue
        symptoms.append(symptom)
    added = 0
    for symptom in symptoms:
        if added >= rel69b_MAX_ADD_SYMPTOM:
            break
        if rel69b_add_relation(relations, 'presente_symptome', patient, symptom, page_number, rel69b_esurface(symptom), 'SYMPTOME explicitement présent sur une page avec ancre patient.', entity_map, stats):
            added += 1


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_focus
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_recover_focus(relations, entities, patients, text, page_number, entity_map, stats):
    if not patients:
        return
    patient = min(patients, key=rel69b_patient_priority)
    foyers = [entity for entity in entities if rel69b_etype(entity) == 'FOYER_INFECTIEUX' and rel69b_spans(text, entity) and (not rel69b_candidate_is_negated(text, entity))]
    added = 0
    for foyer in foyers:
        if added >= rel69b_MAX_ADD_FOCUS:
            break
        if rel69b_add_relation(relations, 'presente_suspicion_infection', patient, foyer, page_number, rel69b_esurface(foyer), 'FOYER_INFECTIEUX explicite rattaché au patient.', entity_map, stats):
            added += 1
rel69b_SERVICE_CUES = ('admis', 'admise', 'hospitalise', 'hospitalisee', 'hospitalisé', 'hospitalisée', 'transfere', 'transferee', 'transféré', 'transférée', 'service', 'reanimation', 'réanimation', 'urgences', 'hopital', 'hôpital')


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_service
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_recover_service(relations, entities, patients, text, page_number, entity_map, stats):
    if not patients:
        return
    patient = min(patients, key=rel69b_patient_priority)
    services = [entity for entity in entities if rel69b_etype(entity) == 'SERVICE_MEDICAL']
    candidates = []
    for service in services:
        service_spans = rel69b_spans(text, service)
        if not service_spans:
            continue
        pos = service_spans[0][0]
        local = rel69b_norm(text[max(0, pos - 90):min(len(text), service_spans[0][1] + 90)])
        if not any((rel69b_norm(cue) in local for cue in rel69b_SERVICE_CUES)):
            continue
        candidates.append(service)
    added = 0
    for service in candidates:
        if added >= rel69b_MAX_ADD_SERVICE:
            break
        if rel69b_add_relation(relations, 'service_medical_accueille', service, patient, page_number, rel69b_esurface(service), "SERVICE_MEDICAL avec contexte d'admission/hospitalisation.", entity_map, stats):
            added += 1


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_imaging_focus
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_recover_imaging_focus(relations, entities, text, page_number, entity_map, stats):
    imaging = [entity for entity in entities if rel69b_etype(entity) == 'IMAGERIE_PROCEDURE']
    foyers = [entity for entity in entities if rel69b_etype(entity) == 'FOYER_INFECTIEUX']
    candidates = []
    for image_entity in imaging:
        best = None
        for foyer in foyers:
            distance = rel69b_nearest_distance(text, image_entity, foyer)
            if distance is None or distance > 240:
                continue
            context = rel69b_norm(rel69b_context_between(text, image_entity, foyer, margin=50))
            if not any((cue in context for cue in ('montre', 'retrouve', 'met en evidence', 'objective', 'visualise', 'revele', 'opacite', 'condensation', 'foyer', 'pneumopath', 'sinusite', 'abces', 'osteite', 'spondylodiscite'))):
                continue
            candidate = (distance, image_entity, foyer)
            if best is None or distance < best[0]:
                best = candidate
        if best is not None:
            candidates.append(best)
    candidates.sort(key=lambda item: item[0])
    added = 0
    for _, image_entity, foyer in candidates:
        if added >= rel69b_MAX_ADD_IMAGING_FOCUS:
            break
        if rel69b_add_relation(relations, 'imagerie_objective_foyer', image_entity, foyer, page_number, rel69b_context_between(text, image_entity, foyer, margin=40), "IMAGERIE_PROCEDURE et FOYER proches avec indice d'objectivation.", entity_map, stats):
            added += 1
rel69b_MICRO_CUES = ('pdp', 'ecbu', 'hemoculture', 'hémoculture', 'culture', 'bacteriologie', 'bactériologie', 'isole', 'isolé', 'isolee', 'isolée', 'positif', 'positive', 'retrouve', 'retrouvé')


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_micro_focus
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_recover_micro_focus(relations, entities, text, page_number, entity_map, stats):
    organisms = [entity for entity in entities if rel69b_etype(entity) == 'MICRO_ORGANISME']
    foyers = [entity for entity in entities if rel69b_etype(entity) == 'FOYER_INFECTIEUX']
    candidates = []
    for organism in organisms:
        best = None
        for foyer in foyers:
            org_name = rel69b_norm(rel69b_esurface(organism))
            focus_name = rel69b_norm(rel69b_esurface(foyer))
            inclusion = bool(org_name and focus_name and (org_name in focus_name))
            distance = rel69b_nearest_distance(text, organism, foyer)
            if not inclusion and (distance is None or distance > 150):
                continue
            context = rel69b_norm(rel69b_context_between(text, organism, foyer, margin=70))
            if not inclusion and (not any((rel69b_norm(cue) in context for cue in rel69b_MICRO_CUES))):
                continue
            score = 0 if inclusion else distance
            candidate = (score, organism, foyer)
            if best is None or score < best[0]:
                best = candidate
        if best is not None:
            candidates.append(best)
    candidates.sort(key=lambda item: item[0])
    added = 0
    for _, organism, foyer in candidates:
        if added >= rel69b_MAX_ADD_MICRO_FOCUS:
            break
        if rel69b_add_relation(relations, 'micro_organisme_isole_dans', organism, foyer, page_number, rel69b_context_between(text, organism, foyer, margin=40), 'MICRO_ORGANISME lié au FOYER par inclusion/proximité microbiologique forte.', entity_map, stats):
            added += 1


# -----------------------------------------------------------------------------
# Fonction : rel69b_biomarker_family
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_biomarker_family(entity):
    value = rel69b_norm(str(entity.get('parametre', '')) + ' ' + rel69b_esurface(entity))
    if any((marker in value for marker in ('p/f', 'pao2', 'po2', 'pco2', 'paco2', 'hypercapnie', 'hypoxemie', 'hypoxémie', 'ph ', 'bicar', 'hco3'))):
        return 'respiratory'
    if any((marker in value for marker in ('creat', 'uree', 'urée', 'proteinur', 'diurese', 'diurèse'))):
        return 'renal'
    if any((marker in value for marker in ('plaquette', 'schizocyte', 'hemoglob', 'haptoglob', 'ldh'))):
        return 'hematologic'
    if any((marker in value for marker in ('asat', 'alat', 'ggt', 'bilirub', 'tp ', 'temps de quick'))):
        return 'hepatic'
    if 'lactate' in value:
        return 'shock'
    return ''


# -----------------------------------------------------------------------------
# Fonction : rel69b_failure_family
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_failure_family(entity):
    value = rel69b_norm(rel69b_esurface(entity))
    if any((marker in value for marker in ('respiratoire', 'sdra', 'dra', 'hypox', 'acidose respiratoire', 'hypercap'))):
        return 'respiratory'
    if any((marker in value for marker in ('renale', 'rénale', 'ira', 'anurie', 'oligo'))):
        return 'renal'
    if any((marker in value for marker in ('hematolog', 'hématolog', 'civd'))):
        return 'hematologic'
    if any((marker in value for marker in ('hepat', 'hépat', 'cytolyse'))):
        return 'hepatic'
    if any((marker in value for marker in ('choc', 'hemodynam', 'hémodynam', 'collapsus'))):
        return 'shock'
    return ''


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_biomarker_failure
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_recover_biomarker_failure(relations, entities, text, page_number, entity_map, stats):
    biomarkers = [entity for entity in entities if rel69b_etype(entity) == 'BIOMARQUEUR' and rel69b_biomarker_family(entity)]
    failures = [entity for entity in entities if rel69b_etype(entity) == 'DEFAILLANCE_ORGANE' and rel69b_failure_family(entity)]
    candidates = []
    for biomarker in biomarkers:
        family = rel69b_biomarker_family(biomarker)
        best = None
        for failure in failures:
            if rel69b_failure_family(failure) != family:
                continue
            distance = rel69b_nearest_distance(text, biomarker, failure)
            if distance is None or distance > 180:
                continue
            candidate = (distance, biomarker, failure)
            if best is None or distance < best[0]:
                best = candidate
        if best is not None:
            candidates.append(best)
    candidates.sort(key=lambda item: item[0])
    added = 0
    for _, biomarker, failure in candidates:
        if added >= rel69b_MAX_ADD_BIOMARKER_FAILURE:
            break
        if rel69b_add_relation(relations, 'biomarqueur_supporte_defaillance_organe', biomarker, failure, page_number, rel69b_context_between(text, biomarker, failure, margin=35), 'BIOMARQUEUR et DEFAILLANCE de même famille clinique à proximité <=180 caractères.', entity_map, stats):
            added += 1


# -----------------------------------------------------------------------------
# Fonction : rel69b_vital_family
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_vital_family(entity):
    value = rel69b_norm(rel69b_esurface(entity))
    if any((marker in value for marker in ('saturation', 'spo2', 'sao2', 'desaturation', 'polypnee', 'tachypnee', 'frequence respiratoire'))):
        return 'respiratory'
    if any((marker in value for marker in ('pression arterielle', 'tension arterielle', 'hypotension', 'tachycardie', 'frequence cardiaque'))):
        return 'shock'
    return ''


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_vital_failure
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_recover_vital_failure(relations, entities, text, page_number, entity_map, stats):
    vitals = [entity for entity in entities if rel69b_etype(entity) == 'SIGNE_VITAL' and rel69b_vital_family(entity)]
    failures = [entity for entity in entities if rel69b_etype(entity) == 'DEFAILLANCE_ORGANE' and rel69b_failure_family(entity) in {'respiratory', 'shock'}]
    candidates = []
    for vital in vitals:
        family = rel69b_vital_family(vital)
        best = None
        for failure in failures:
            if rel69b_failure_family(failure) != family:
                continue
            distance = rel69b_nearest_distance(text, vital, failure)
            if distance is None or distance > 180:
                continue
            candidate = (distance, vital, failure)
            if best is None or distance < best[0]:
                best = candidate
        if best is not None:
            candidates.append(best)
    candidates.sort(key=lambda item: item[0])
    added = 0
    for _, vital, failure in candidates:
        if added >= rel69b_MAX_ADD_VITAL_FAILURE:
            break
        if rel69b_add_relation(relations, 'signe_vital_supporte_defaillance_organe', vital, failure, page_number, rel69b_context_between(text, vital, failure, margin=35), 'SIGNE_VITAL et DEFAILLANCE de même famille physiologique à proximité.', entity_map, stats):
            added += 1
rel69b_INDICATION_CUES = ('pour traiter', 'traitement de', 'traite pour', 'traité pour', 'traitee pour', 'traitée pour', 'indique pour', 'indiquée pour', 'mise sous', 'mis sous', 'en raison de')


# -----------------------------------------------------------------------------
# Fonction : rel69b_recover_treatment_label
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_recover_treatment_label(relations, entities, text, page_number, entity_map, stats):
    treatments = [entity for entity in entities if rel69b_etype(entity) == 'TRAITEMENT']
    labels = [entity for entity in entities if rel69b_etype(entity) == 'LABEL_NOSOLOGIQUE']
    candidates = []
    for treatment in treatments:
        for label in labels:
            distance = rel69b_nearest_distance(text, treatment, label)
            if distance is None or distance > 150:
                continue
            context = rel69b_norm(rel69b_context_between(text, treatment, label, margin=50))
            if not any((rel69b_norm(cue) in context for cue in rel69b_INDICATION_CUES)):
                continue
            candidates.append((distance, treatment, label))
    candidates.sort(key=lambda item: item[0])
    added = 0
    for _, treatment, label in candidates:
        if added >= rel69b_MAX_ADD_TREATMENT_LABEL:
            break
        if rel69b_add_relation(relations, 'traitement_indique_par_label_nosologique', treatment, label, page_number, rel69b_context_between(text, treatment, label, margin=35), 'Indication thérapeutique explicitement formulée.', entity_map, stats):
            added += 1


# -----------------------------------------------------------------------------
# Fonction : rel69b_get_page_entities
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69b_get_page_entities(page):
    entities = page.get('entities')
    if not isinstance(entities, list):
        entities = page.get('entites', [])
    if not isinstance(entities, list):
        return []
    return [entity for entity in entities if isinstance(entity, dict)]


# -----------------------------------------------------------------------------
# Fonction : rel69b_process_document
# Rôle : Applique toutes les règles de cette étape à l'ensemble des pages d'un document et agrège les résultats.
# -----------------------------------------------------------------------------
def rel69b_process_document(data):
    output = copy.deepcopy(data)
    stats = Counter()
    entity_map = rel69b_build_entity_map(output)
    relations = output.get('global_relations', [])
    if not isinstance(relations, list):
        relations = []
    relations = [copy.deepcopy(relation) for relation in relations if isinstance(relation, dict)]
    pages = output.get('pages', [])
    if not isinstance(pages, list):
        pages = []
    for page in pages:
        if not isinstance(page, dict):
            continue
        page_number = page.get('page')
        text = str(page.get('texte_brut') or '')
        if not text:
            continue
        entities = rel69b_get_page_entities(page)
        patients = [entity for entity in entities if rel69b_is_patient_entity(entity)]
        rel69b_recover_treatment_admin(relations, entities, patients, text, page_number, entity_map, stats)
        rel69b_recover_posology(relations, entities, text, page_number, entity_map, stats)
        rel69b_recover_symptoms(relations, entities, patients, text, page_number, entity_map, stats)
        rel69b_recover_focus(relations, entities, patients, text, page_number, entity_map, stats)
        rel69b_recover_service(relations, entities, patients, text, page_number, entity_map, stats)
        rel69b_recover_imaging_focus(relations, entities, text, page_number, entity_map, stats)
        rel69b_recover_micro_focus(relations, entities, text, page_number, entity_map, stats)
        rel69b_recover_biomarker_failure(relations, entities, text, page_number, entity_map, stats)
        rel69b_recover_vital_failure(relations, entities, text, page_number, entity_map, stats)
        rel69b_recover_treatment_label(relations, entities, text, page_number, entity_map, stats)
    for index, relation in enumerate(relations, start=1):
        relation['identifiant_relation'] = f'R_V69B_{index:05d}'
    output['global_relations'] = relations
    if isinstance(output.get('document_summary'), dict):
        output['document_summary']['total_relations'] = len(relations)
    output['relation_postprocessing_v69b'] = {'version': 'V6.9b_RECALL_CONTROLLED', 'source': 'V6.9_ERROR_GUIDED_PRECISION_PLUS', 'stats': dict(stats), 'total_relations': len(relations)}
    return (output, stats)


# -----------------------------------------------------------------------------
# Fonction : rel69b_process_folder
# Rôle : Traite tous les fichiers JSON d'un dossier avec cette version du post-traitement.
# -----------------------------------------------------------------------------
def rel69b_process_folder(input_dir, output_dir):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)
    if not input_dir.is_dir():
        raise FileNotFoundError(f'Dossier source introuvable : {input_dir}')
    output_dir.mkdir(parents=True, exist_ok=True)
    for old_file in output_dir.glob('*.json'):
        try:
            old_file.unlink()
        except OSError:
            pass
    files = sorted(input_dir.glob('*.json'))
    print('\n============================================================')
    print('TRACE-Sepsis — V6.9b RELATION RECALL-CONTROLLED')
    print('============================================================')
    print('INPUT  :', input_dir)
    print('OUTPUT :', output_dir)
    print('JSON   :', len(files))
    print('============================================================\n')
    if len(files) != 43:
        print(f'⚠️ 43 documents attendus ; {len(files)} trouvés.')
    total_stats = Counter()
    for index, source in enumerate(files, start=1):
        with source.open('r', encoding='utf-8') as handle:
            data = json.load(handle)
        before = len(data.get('global_relations', []))
        result, stats = rel69b_process_document(data)
        total_stats.update(stats)
        after = len(result.get('global_relations', []))
        destination = output_dir / source.name
        with destination.open('w', encoding='utf-8') as handle:
            json.dump(result, handle, ensure_ascii=False, indent=2)
        print(f'✅ {index:02d}/{len(files)} {source.name} | relations {before} -> {after}')
    print('\n--- AJOUTS V6.9b ---')
    for key, value in sorted(total_stats.items()):
        print(f'{key:70s} : {value}')
    print('\n🏁 V6.9b RECALL-CONTROLLED terminée.')

