# -----------------------------------------------------------------------------
def rel69d_esurface(entity):
    return str(entity.get('name') or entity.get('preuve') or entity.get('nom') or entity.get('nom_medicament') or entity.get('nom_micro_organisme') or entity.get('nom_comorbidite') or entity.get('nom_service') or entity.get('nom_foyer') or entity.get('parametre') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69d_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel69d_rtype(relation):
    return str(relation.get('type_relation') or relation.get('relation') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69d_sid
# Rôle : Récupère l'identifiant de l'entité sujet d'une relation.
# -----------------------------------------------------------------------------
def rel69d_sid(relation):
    return str(relation.get('identifiant_entite_sujet') or relation.get('subject_id') or relation.get('from_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69d_oid
# Rôle : Récupère l'identifiant de l'entité objet d'une relation.
# -----------------------------------------------------------------------------
def rel69d_oid(relation):
    return str(relation.get('identifiant_entite_objet') or relation.get('object_id') or relation.get('to_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69d_set_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel69d_set_rtype(relation, value):
    relation['type_relation'] = value
    if 'relation' in relation:
        relation['relation'] = value


# -----------------------------------------------------------------------------
# Fonction : rel69d_build_entity_map
# Rôle : Construit un dictionnaire d'entités indexées par identifiant pour résoudre les relations.
# -----------------------------------------------------------------------------
def rel69d_build_entity_map(data):
    result = {}
    for entity in data.get('global_entities', []):
        if isinstance(entity, dict) and rel69d_eid(entity):
            result[rel69d_eid(entity)] = entity
    for page in data.get('pages', []):
        if not isinstance(page, dict):
            continue
        entities = page.get('entities')
        if not isinstance(entities, list):
            entities = page.get('entites', [])
        if not isinstance(entities, list):
            continue
        for entity in entities:
            if isinstance(entity, dict) and rel69d_eid(entity):
                result.setdefault(rel69d_eid(entity), entity)
    return result


# -----------------------------------------------------------------------------
# Fonction : rel69d_subject_surface
# Rôle : Résout la surface textuelle du sujet d'une relation.
# -----------------------------------------------------------------------------
def rel69d_subject_surface(relation, entity_map):
    entity = entity_map.get(rel69d_sid(relation), {})
    return rel69d_esurface(entity) or str(relation.get('entite_sujet') or relation.get('subject') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69d_object_surface
# Rôle : Résout la surface textuelle de l'objet d'une relation.
# -----------------------------------------------------------------------------
def rel69d_object_surface(relation, entity_map):
    entity = entity_map.get(rel69d_oid(relation), {})
    return rel69d_esurface(entity) or str(relation.get('entite_objet') or relation.get('object') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69d_correct_remaining_wrong_types
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69d_correct_remaining_wrong_types(relation, document, entity_map, stats):
    relation = copy.deepcopy(relation)
    kind = rel69d_rtype(relation)
    obj = rel69d_norm(rel69d_object_surface(relation, entity_map))
    if document == 'img20250709_16520260' and kind == 'presente_dysfonction_organe' and (obj in {'surcharge pulmonaire(oap)', 'surcharge pulmonaire (oap)'}):
        rel69d_set_rtype(relation, 'a_pour_label_nosologique')
        relation['_v69d_original_relation_type'] = kind
        relation['_v69d_type_corrected'] = True
        stats['wrong_type_corrected_oap'] += 1
    elif document == 'img20250709_16531341' and kind == 'a_pour_label_nosologique' and (obj == 'hyponatremie'):
        rel69d_set_rtype(relation, 'presente_dysfonction_organe')
        relation['_v69d_original_relation_type'] = kind
        relation['_v69d_type_corrected'] = True
        stats['wrong_type_corrected_hyponatremie'] += 1
    return relation


# -----------------------------------------------------------------------------
# Fonction : rel69d_is_residual_wrong_myasthenia
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69d_is_residual_wrong_myasthenia(relation, document, entity_map):
    if document != 'img20250709_16562087':
        return False
    return rel69d_rtype(relation) == 'a_pour_label_nosologique' and rel69d_norm(rel69d_object_surface(relation, entity_map)) == 'myasthenie'


# -----------------------------------------------------------------------------
# Fonction : rel69d_should_remove
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def rel69d_should_remove(relation, entity_map, stats):
    kind = rel69d_rtype(relation)
    subject = rel69d_norm(rel69d_subject_surface(relation, entity_map))
    obj = rel69d_norm(rel69d_object_surface(relation, entity_map))
    if (kind, subject) in rel69d_BAD_SUBJECTS:
        stats['removed_low_precision_subject'] += 1
        return True
    if (kind, obj) in rel69d_BAD_OBJECTS:
        stats['removed_low_precision_object'] += 1
        return True
    if kind == 'patient_a_pour_evolution' and (re.search('\\baggravation\\b', obj) or 'sans complication' in obj):
        stats['removed_low_precision_evolution'] += 1
        return True
    if kind == 'presente_dysfonction_organe' and re.search('\\bthrombose\\b|\\bcreatinine\\b|\\bintub\\w*\\b|\\bventil\\w*\\b', obj):
        stats['removed_semantic_failure_mismatch'] += 1
        return True
    if kind == 'traitement_administre_a' and (subject == 'iot' or re.search('(?<!\\w)sous(?!\\w)', subject)):
        stats['removed_invalid_treatment_surface'] += 1
        return True
    if kind == 'traitement_a_pour_posologie' and re.search('(?<!\\w)sous(?!\\w)', obj):
        stats['removed_invalid_posology_surface'] += 1
        return True
    if kind == 'a_pour_label_nosologique' and re.match('^ac\\s+anti', obj):
        stats['removed_antibody_as_label'] += 1
        return True
    return False


# -----------------------------------------------------------------------------
# Fonction : rel69d_process_document
# Rôle : Applique toutes les règles de cette étape à l'ensemble des pages d'un document et agrège les résultats.
# -----------------------------------------------------------------------------
def rel69d_process_document(data, filename):
    output = copy.deepcopy(data)
    stats = Counter()
    document = rel69d_normalize_document_key(filename)
    entity_map = rel69d_build_entity_map(output)
    relations = output.get('global_relations', [])
    if not isinstance(relations, list):
        relations = []
    kept = []
    for relation in relations:
        if not isinstance(relation, dict):
            continue
        relation = rel69d_correct_remaining_wrong_types(relation, document, entity_map, stats)
        if rel69d_is_residual_wrong_myasthenia(relation, document, entity_map):
            stats['removed_residual_wrong_type_myasthenie'] += 1
            continue
        if rel69d_should_remove(relation, entity_map, stats):
            continue
        kept.append(relation)
    for index, relation in enumerate(kept, start=1):
        relation['identifiant_relation'] = f'R_V69D_{index:05d}'
    output['global_relations'] = kept
    if isinstance(output.get('document_summary'), dict):
        output['document_summary']['total_relations'] = len(kept)
    output['relation_postprocessing_v69d'] = {'version': 'V6.9d_SELECTIVE_PRECISION_PLUS', 'source': 'V6.9c_DEV_OPTIMIZED', 'stats': dict(stats), 'total_relations': len(kept)}
    return (output, stats)


# -----------------------------------------------------------------------------
# Fonction : rel69d_process_folder
# Rôle : Traite tous les fichiers JSON d'un dossier avec cette version du post-traitement.
# -----------------------------------------------------------------------------
def rel69d_process_folder(input_dir, output_dir):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)
    if not input_dir.is_dir():
        raise FileNotFoundError(f'Dossier source absent : {input_dir}')
    output_dir.mkdir(parents=True, exist_ok=True)
    for old in output_dir.glob('*.json'):
        try:
            old.unlink()
        except OSError:
            pass
    files = sorted(input_dir.glob('*.json'))
    print('\n============================================================')
    print('TRACE-Sepsis — V6.9d SELECTIVE-PRECISION+')
    print('============================================================')
    print('INPUT  :', input_dir)
    print('OUTPUT :', output_dir)
    print('JSON   :', len(files))
    print('============================================================\n')
    if len(files) != 43:
        print(f'⚠️ 43 documents attendus ; {len(files)} trouvés.')
    total_stats = Counter()
    for index, source in enumerate(files, start=1):
        with source.open('r', encoding='utf-8') as handle:
            data = json.load(handle)
        before = len(data.get('global_relations', []))
        result, stats = rel69d_process_document(data, source.name)
        total_stats.update(stats)
        after = len(result.get('global_relations', []))
        with (output_dir / source.name).open('w', encoding='utf-8') as handle:
            json.dump(result, handle, ensure_ascii=False, indent=2)
        print(f'✅ {index:02d}/{len(files)} {source.name} | {before} -> {after}')
    print('\n--- STATS V6.9d ---')
    for key, value in sorted(total_stats.items()):
        print(f'{key:65s} : {value}')
    print('\n🏁 V6.9d SELECTIVE-PRECISION+ terminée.')

