import copy
import json
import os
import re
import sys
import unicodedata
from collections import Counter
from pathlib import Path
if os.name == 'nt':
    rel69f_BASE_DIR = Path(os.environ.get('USERPROFILE', str(Path.home()))) / 'Desktop' / 'TRACE' / 'OCR vers LLM'
else:
    rel69f_BASE_DIR = Path.home() / 'TRACE' / 'OCR vers LLM'
rel69f_INPUT_DIR = rel69f_BASE_DIR / 'BEST_43_Relations_V6_9e_HIGH_CONFIDENCE_RECALL'
rel69f_OUTPUT_DIR = rel69f_BASE_DIR / 'BEST_43_Relations_V6_9f_DEV_RECALL_PLUS'

# --- rel69f_MATCH_THRESHOLD ---
# Seuil de décision utilisé pour accepter ou rejeter une correspondance.
rel69f_MATCH_THRESHOLD = 0.85
rel69f_MIN_MARGIN = 0.02

# --- rel69f_MAX_ADD_PER_DOCUMENT ---
# Limite le nombre d'ajouts automatiques afin de contrôler le risque de faux positifs.
rel69f_MAX_ADD_PER_DOCUMENT = 12

