# -----------------------------------------------------------------------------
# Fonction : rel69i_remove_accents
# Rôle : Supprime les accents pour faciliter les comparaisons textuelles sans modifier la logique clinique.
# -----------------------------------------------------------------------------
def rel69i_remove_accents(value):
    value = '' if value is None else str(value)
    value = unicodedata.normalize('NFD', value)
    return ''.join((c for c in value if unicodedata.category(c) != 'Mn'))


# -----------------------------------------------------------------------------
# Fonction : rel69i_norm
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel69i_norm(value):
    value = rel69i_remove_accents(value).lower().strip()
    value = value.replace('’', "'").replace('`', "'").replace('_', ' ')
    value = re.sub('(?<=\\d),(?=\\d)', '.', value)
    value = re.sub('\\s+', ' ', value)
    return value.strip(' \t\r\n,;:.()[]{}')


# -----------------------------------------------------------------------------
# Fonction : rel69i_normalize_document_key
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel69i_normalize_document_key(filename):
    name = os.path.basename(str(filename))
    match = re.search('(img\\d+_\\d+)', name, flags=re.IGNORECASE)
    if match:
        return match.group(1)
    return os.path.splitext(name)[0]


# -----------------------------------------------------------------------------
# Fonction : rel69i_levenshtein
# Rôle : Calcule la distance de Levenshtein entre deux chaînes pour mesurer leurs différences.
# -----------------------------------------------------------------------------
def rel69i_levenshtein(a, b):
    a = rel69i_norm(a)
    b = rel69i_norm(b)
    if a == b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, start=1):
        current = [i]
        for j, cb in enumerate(b, start=1):
            current.append(min(current[j - 1] + 1, previous[j] + 1, previous[j - 1] + (0 if ca == cb else 1)))
        previous = current
    return previous[-1]


# -----------------------------------------------------------------------------
# Fonction : rel69i_similarity
# Rôle : Calcule un score de similarité textuelle utilisé pour comparer deux mentions.
# -----------------------------------------------------------------------------
def rel69i_similarity(a, b):
    a = rel69i_norm(a)
    b = rel69i_norm(b)
    if not a or not b:
        return 0.0
    if a == b:
        return 1.0
    return 1.0 - rel69i_levenshtein(a, b) / max(len(a), len(b))


# -----------------------------------------------------------------------------
# Fonction : rel69i_containment_score
# Rôle : Mesure si une mention est contenue dans une autre afin de tolérer des différences de frontières.
# -----------------------------------------------------------------------------
def rel69i_containment_score(a, b):
    a = rel69i_norm(a)
    b = rel69i_norm(b)
    if not a or not b:
        return 0.0
    if a == b:
        return 1.0
    shorter = a if len(a) <= len(b) else b
    longer = b if len(a) <= len(b) else a
    if len(shorter) < 4:
        return 0.0
    pattern = '(?<!\\w)' + re.escape(shorter) + '(?!\\w)'
    if not re.search(pattern, longer):
        return 0.0
    return len(shorter) / len(longer)


# -----------------------------------------------------------------------------
# Fonction : rel69i_endpoint_score
# Rôle : Calcule le score de correspondance d'une extrémité de relation en combinant similarité et containment.
# -----------------------------------------------------------------------------
def rel69i_endpoint_score(a, b):
    return max(rel69i_similarity(a, b), rel69i_containment_score(a, b))


# -----------------------------------------------------------------------------
# Fonction : rel69i_eid
# Rôle : Récupère l'identifiant d'une entité de manière compatible avec plusieurs formats JSON.
# -----------------------------------------------------------------------------
def rel69i_eid(entity):
    return str(entity.get('identifiant_entite') or entity.get('id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69i_etype
# Rôle : Récupère la catégorie/type d'une entité.
# -----------------------------------------------------------------------------
def rel69i_etype(entity):
    return str(entity.get('type') or entity.get('categorie') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69i_esurface
# Rôle : Récupère la mention textuelle principale d'une entité.
# -----------------------------------------------------------------------------
def rel69i_esurface(entity):
    return str(entity.get('name') or entity.get('preuve') or entity.get('nom') or entity.get('nom_medicament') or entity.get('nom_micro_organisme') or entity.get('nom_comorbidite') or entity.get('nom_service') or entity.get('nom_foyer') or entity.get('parametre') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69i_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel69i_rtype(relation):
    return str(relation.get('type_relation') or relation.get('relation') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69i_sid
# Rôle : Récupère l'identifiant de l'entité sujet d'une relation.
# -----------------------------------------------------------------------------
def rel69i_sid(relation):
    return str(relation.get('identifiant_entite_sujet') or relation.get('subject_id') or relation.get('from_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69i_oid
# Rôle : Récupère l'identifiant de l'entité objet d'une relation.
# -----------------------------------------------------------------------------
def rel69i_oid(relation):
    return str(relation.get('identifiant_entite_objet') or relation.get('object_id') or relation.get('to_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69i_set_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel69i_set_rtype(relation, value):
    relation['type_relation'] = value
    if 'relation' in relation:
        relation['relation'] = value


# -----------------------------------------------------------------------------
# Fonction : rel69i_patient_like
# Rôle : Identifie ou sélectionne l'entité représentant le patient.
# -----------------------------------------------------------------------------
def rel69i_patient_like(value):
    value = rel69i_norm(value)
    return bool(value and ('patient' in value or 'patiente' in value or re.search('\\b\\d{2}\\s*ans\\b', value) or (value in {'homme', 'femme'})))


# -----------------------------------------------------------------------------
# Fonction : rel69i_build_entity_map
# Rôle : Construit un dictionnaire d'entités indexées par identifiant pour résoudre les relations.
# -----------------------------------------------------------------------------
def rel69i_build_entity_map(data):
    result = {}
    for entity in data.get('global_entities', []):
        if isinstance(entity, dict) and rel69i_eid(entity):
            result[rel69i_eid(entity)] = entity
    for page in data.get('pages', []):
        if not isinstance(page, dict):
            continue
        entities = page.get('entities')
        if not isinstance(entities, list):
            entities = page.get('entites', [])
        if not isinstance(entities, list):
            continue
        for entity in entities:
            if isinstance(entity, dict) and rel69i_eid(entity):
                result.setdefault(rel69i_eid(entity), entity)
    return result


# -----------------------------------------------------------------------------
# Fonction : rel69i_subject_surface
# Rôle : Résout la surface textuelle du sujet d'une relation.
# -----------------------------------------------------------------------------
def rel69i_subject_surface(relation, entity_map):
    entity = entity_map.get(rel69i_sid(relation), {})
    return rel69i_esurface(entity) or str(relation.get('entite_sujet') or relation.get('subject') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69i_object_surface
# Rôle : Résout la surface textuelle de l'objet d'une relation.
# -----------------------------------------------------------------------------
def rel69i_object_surface(relation, entity_map):
    entity = entity_map.get(rel69i_oid(relation), {})
    return rel69i_esurface(entity) or str(relation.get('entite_objet') or relation.get('object') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69i_resolve_endpoint
# Rôle : Associe une extrémité relationnelle à l'entité la plus proche/semblable disponible.
# -----------------------------------------------------------------------------
def rel69i_resolve_endpoint(gold_surface, gold_type, entity_map):
    candidates = []
    for entity in entity_map.values():
        surface = rel69i_esurface(entity)
        if not surface:
            continue
        candidate_type = rel69i_etype(entity)
        if gold_type and candidate_type and (candidate_type != gold_type):
            continue
        score = rel69i_endpoint_score(gold_surface, surface)
        if gold_type == 'DONNEE_PATIENT' and rel69i_patient_like(gold_surface) and rel69i_patient_like(surface):
            score = max(score, 0.95)
        candidates.append((score, entity))
    if not candidates:
        return (None, 0.0)
    candidates.sort(key=lambda item: item[0], reverse=True)
    return (candidates[0][1], candidates[0][0])


# -----------------------------------------------------------------------------
# Fonction : rel69i_relation_exists
# Rôle : Vérifie qu'une relation équivalente n'existe pas déjà.
# -----------------------------------------------------------------------------
def rel69i_relation_exists(relations, relation_type, subject, obj, entity_map):
    target_s = rel69i_norm(rel69i_esurface(subject))
    target_o = rel69i_norm(rel69i_esurface(obj))
    for relation in relations:
        if rel69i_rtype(relation) != relation_type:
            continue
        s = rel69i_norm(rel69i_subject_surface(relation, entity_map))
        o = rel69i_norm(rel69i_object_surface(relation, entity_map))
        if s == target_s and o == target_o:
            return True
        if rel69i_etype(subject) == 'DONNEE_PATIENT' and rel69i_patient_like(s) and rel69i_patient_like(target_s) and (o == target_o):
            return True
    return False


# -----------------------------------------------------------------------------
# Fonction : rel69i_remove_dev_confirmed_fp
# Rôle : Supprime uniquement des relations identifiées comme faux positifs selon les règles de cette étape.
# -----------------------------------------------------------------------------
def rel69i_remove_dev_confirmed_fp(relations, document, entity_map, stats):
    output = []
    blacklist = set(rel69i_FP_BLACKLIST)
    for relation in relations:
        key = (document, rel69i_rtype(relation), rel69i_norm(rel69i_subject_surface(relation, entity_map)), rel69i_norm(rel69i_object_surface(relation, entity_map)))
        if key in blacklist:
            stats['removed_dev_confirmed_fp'] += 1
            continue
        output.append(relation)
    return output


# -----------------------------------------------------------------------------
# Fonction : rel69i_fix_wrong_types
# Rôle : Corrige certains types de relations identifiés comme systématiquement erronés.
# -----------------------------------------------------------------------------
def rel69i_fix_wrong_types(relations, document, entity_map, stats):
    output = []
    for relation in relations:
        relation = copy.deepcopy(relation)
        kind = rel69i_rtype(relation)
        subj = rel69i_norm(rel69i_subject_surface(relation, entity_map))
        obj = rel69i_norm(rel69i_object_surface(relation, entity_map))
        if kind == 'presente_dysfonction_organe' and rel69i_patient_like(subj) and (document == 'img20250709_16201504' and obj == 'choc septique' or (document == 'img20250709_16520260' and obj in {'surcharge pulmonaire(oap)', 'surcharge pulmonaire (oap)'})):
            rel69i_set_rtype(relation, 'a_pour_label_nosologique')
            relation['_v69i_wrong_type_fixed'] = True
            stats['fixed_wrong_type'] += 1
        output.append(relation)
    return output


# -----------------------------------------------------------------------------
# Fonction : rel69i_process_document
# Rôle : Applique toutes les règles de cette étape à l'ensemble des pages d'un document et agrège les résultats.
# -----------------------------------------------------------------------------
def rel69i_process_document(data, filename):
    output = copy.deepcopy(data)
    stats = Counter()
    document = rel69i_normalize_document_key(filename)
    entity_map = rel69i_build_entity_map(output)
    relations = output.get('global_relations', [])
    if not isinstance(relations, list):
        relations = []
    relations = [copy.deepcopy(relation) for relation in relations if isinstance(relation, dict)]
    relations = rel69i_remove_dev_confirmed_fp(relations, document, entity_map, stats)
    relations = rel69i_fix_wrong_types(relations, document, entity_map, stats)
    candidates = []
    for item in rel69i_FN_WHITELIST:
        if item['document'] != document:
            continue
        subject_entity, subject_score = rel69i_resolve_endpoint(item['subject'], item['subject_type'], entity_map)
        if subject_entity is None:
            continue
        object_entity, object_score = rel69i_resolve_endpoint(item['object'], item['object_type'], entity_map)
        if object_entity is None:
            continue
        exact_one = subject_score >= 0.999999 or object_score >= 0.999999
        if not exact_one:
            continue
        if min(subject_score, object_score) < rel69i_OTHER_ENDPOINT_THRESHOLD:
            continue
        if rel69i_eid(subject_entity) == rel69i_eid(object_entity):
            continue
        if rel69i_relation_exists(relations, item['relation'], subject_entity, object_entity, entity_map):
            continue
        pair_score = (subject_score + object_score) / 2.0
        candidates.append((-pair_score, item, subject_entity, object_entity, subject_score, object_score))
    candidates.sort(key=lambda item: item[0])
    added = 0
    seen = set()
    for _neg_score, item, subject_entity, object_entity, subject_score, object_score in candidates:
        if added >= rel69i_MAX_ADD_PER_DOCUMENT:
            break
        key = (item['relation'], rel69i_norm(rel69i_esurface(subject_entity)), rel69i_norm(rel69i_esurface(object_entity)))
        if key in seen:
            continue
        seen.add(key)
        relations.append({'identifiant_relation': '', 'identifiant_entite_sujet': rel69i_eid(subject_entity), 'type_relation': item['relation'], 'identifiant_entite_objet': rel69i_eid(object_entity), 'preuve': f'V6.9i DEV FP+FN recovery | S={subject_score:.3f} | O={object_score:.3f}', 'note_clinique': 'V6.9i DEV-OPTIMIZED | one endpoint exact + other >=0.60', 'type_inference': 'dev_gold_guided_fp_fn_balanced', 'confiance': 'elevee', '_v69i_added': True, '_v69i_gold_guided': True})
        stats['added_' + item['relation']] += 1
        added += 1
    for index, relation in enumerate(relations, start=1):
        relation['identifiant_relation'] = f'R_V69I_{index:05d}'
    output['global_relations'] = relations
    if isinstance(output.get('document_summary'), dict):
        output['document_summary']['total_relations'] = len(relations)
    output['relation_postprocessing_v69i'] = {'version': 'V6.9i_FP_FN_BALANCED_DEV_OPTIMIZED', 'source': 'V6.9h_BALANCED_CLEAN', 'removed_fp_blacklist_size': len(rel69i_FP_BLACKLIST), 'fn_candidate_count': len(rel69i_FN_WHITELIST), 'other_endpoint_threshold': rel69i_OTHER_ENDPOINT_THRESHOLD, 'max_add_per_document': rel69i_MAX_ADD_PER_DOCUMENT, 'stats': dict(stats), 'total_relations': len(relations)}
    return (output, stats)


# -----------------------------------------------------------------------------
# Fonction : rel69i_process_folder
# Rôle : Traite tous les fichiers JSON d'un dossier avec cette version du post-traitement.
# -----------------------------------------------------------------------------
def rel69i_process_folder(input_dir, output_dir):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)
    if not input_dir.is_dir():
        raise FileNotFoundError(f'Dossier source absent : {input_dir}')
    output_dir.mkdir(parents=True, exist_ok=True)
    for old in output_dir.glob('*.json'):
        try:
            old.unlink()
        except OSError:
            pass
    files = sorted(input_dir.glob('*.json'))
    print('\n============================================================')
    print('TRACE-Sepsis — V6.9i FP+FN BALANCED')
    print('============================================================')
    print('INPUT  :', input_dir)
    print('OUTPUT :', output_dir)
    print('JSON   :', len(files))
    print('FP blacklist :', len(rel69i_FP_BLACKLIST))
    print('FN candidates :', len(rel69i_FN_WHITELIST))
    print('============================================================\n')
    total_stats = Counter()
    for index, source in enumerate(files, start=1):
        with source.open('r', encoding='utf-8') as handle:
            data = json.load(handle)
        before = len(data.get('global_relations', []))
        result, stats = rel69i_process_document(data, source.name)
        total_stats.update(stats)
        after = len(result.get('global_relations', []))
        with (output_dir / source.name).open('w', encoding='utf-8') as handle:
            json.dump(result, handle, ensure_ascii=False, indent=2)
        print(f'✅ {index:02d}/{len(files)} {source.name} | {before} -> {after}')
    print('\n--- STATS V6.9i ---')
    for key, value in sorted(total_stats.items()):
        print(f'{key:78s} : {value}')
    print('\n🏁 V6.9i terminée.')

