# -----------------------------------------------------------------------------
# Fonction : rel69k_remove_accents
# Rôle : Supprime les accents pour faciliter les comparaisons textuelles sans modifier la logique clinique.
# -----------------------------------------------------------------------------
def rel69k_remove_accents(value):
    value = '' if value is None else str(value)
    value = unicodedata.normalize('NFD', value)
    return ''.join((c for c in value if unicodedata.category(c) != 'Mn'))


# -----------------------------------------------------------------------------
# Fonction : rel69k_norm
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel69k_norm(value):
    value = rel69k_remove_accents(value).lower().strip()
    value = value.replace('’', "'").replace('`', "'").replace('_', ' ')
    value = re.sub('(?<=\\d),(?=\\d)', '.', value)
    value = re.sub('\\s+', ' ', value)
    return value.strip(' \t\r\n,;:.()[]{}')


# -----------------------------------------------------------------------------
# Fonction : rel69k_normalize_document_key
# Rôle : Normalise le texte (minuscules, accents, espaces, ponctuation selon l'étape) pour rendre les comparaisons robustes.
# -----------------------------------------------------------------------------
def rel69k_normalize_document_key(filename):
    name = os.path.basename(str(filename))
    match = re.search('(img\\d+_\\d+)', name, flags=re.IGNORECASE)
    if match:
        return match.group(1)
    return os.path.splitext(name)[0]


# -----------------------------------------------------------------------------
# Fonction : rel69k_levenshtein
# Rôle : Calcule la distance de Levenshtein entre deux chaînes pour mesurer leurs différences.
# -----------------------------------------------------------------------------
def rel69k_levenshtein(a, b):
    a = rel69k_norm(a)
    b = rel69k_norm(b)
    if a == b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, start=1):
        current = [i]
        for j, cb in enumerate(b, start=1):
            current.append(min(current[j - 1] + 1, previous[j] + 1, previous[j - 1] + (0 if ca == cb else 1)))
        previous = current
    return previous[-1]


# -----------------------------------------------------------------------------
# Fonction : rel69k_similarity
# Rôle : Calcule un score de similarité textuelle utilisé pour comparer deux mentions.
# -----------------------------------------------------------------------------
def rel69k_similarity(a, b):
    a = rel69k_norm(a)
    b = rel69k_norm(b)
    if not a or not b:
        return 0.0
    if a == b:
        return 1.0
    return 1.0 - rel69k_levenshtein(a, b) / max(len(a), len(b))


# -----------------------------------------------------------------------------
# Fonction : rel69k_containment_score
# Rôle : Mesure si une mention est contenue dans une autre afin de tolérer des différences de frontières.
# -----------------------------------------------------------------------------
def rel69k_containment_score(a, b):
    a = rel69k_norm(a)
    b = rel69k_norm(b)
    if not a or not b:
        return 0.0
    if a == b:
        return 1.0
    shorter = a if len(a) <= len(b) else b
    longer = b if len(a) <= len(b) else a
    if len(shorter) < 4:
        return 0.0
    pattern = '(?<!\\w)' + re.escape(shorter) + '(?!\\w)'
    if not re.search(pattern, longer):
        return 0.0
    return len(shorter) / len(longer)


# -----------------------------------------------------------------------------
# Fonction : rel69k_endpoint_score
# Rôle : Calcule le score de correspondance d'une extrémité de relation en combinant similarité et containment.
# -----------------------------------------------------------------------------
def rel69k_endpoint_score(a, b):
    return max(rel69k_similarity(a, b), rel69k_containment_score(a, b))


# -----------------------------------------------------------------------------
# Fonction : rel69k_eid
# Rôle : Récupère l'identifiant d'une entité de manière compatible avec plusieurs formats JSON.
# -----------------------------------------------------------------------------
def rel69k_eid(entity):
    return str(entity.get('identifiant_entite') or entity.get('id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69k_etype
# Rôle : Récupère la catégorie/type d'une entité.
# -----------------------------------------------------------------------------
def rel69k_etype(entity):
    return str(entity.get('type') or entity.get('categorie') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69k_esurface
# Rôle : Récupère la mention textuelle principale d'une entité.
# -----------------------------------------------------------------------------
def rel69k_esurface(entity):
    return str(entity.get('name') or entity.get('preuve') or entity.get('nom') or entity.get('nom_medicament') or entity.get('nom_micro_organisme') or entity.get('nom_comorbidite') or entity.get('nom_service') or entity.get('nom_foyer') or entity.get('parametre') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69k_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel69k_rtype(relation):
    return str(relation.get('type_relation') or relation.get('relation') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69k_sid
# Rôle : Récupère l'identifiant de l'entité sujet d'une relation.
# -----------------------------------------------------------------------------
def rel69k_sid(relation):
    return str(relation.get('identifiant_entite_sujet') or relation.get('subject_id') or relation.get('from_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69k_oid
# Rôle : Récupère l'identifiant de l'entité objet d'une relation.
# -----------------------------------------------------------------------------
def rel69k_oid(relation):
    return str(relation.get('identifiant_entite_objet') or relation.get('object_id') or relation.get('to_id') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69k_set_rtype
# Rôle : Récupère le type d'une relation.
# -----------------------------------------------------------------------------
def rel69k_set_rtype(relation, value):
    relation['type_relation'] = value
    if 'relation' in relation:
        relation['relation'] = value


# -----------------------------------------------------------------------------
# Fonction : rel69k_patient_like
# Rôle : Identifie ou sélectionne l'entité représentant le patient.
# -----------------------------------------------------------------------------
def rel69k_patient_like(value):
    value = rel69k_norm(value)
    if not value:
        return False
    return bool('patient' in value or 'patiente' in value or re.search('\\b\\d{2}\\s*ans\\b', value) or (value in {'homme', 'femme'}))


# -----------------------------------------------------------------------------
# Fonction : rel69k_build_entity_map
# Rôle : Construit un dictionnaire d'entités indexées par identifiant pour résoudre les relations.
# -----------------------------------------------------------------------------
def rel69k_build_entity_map(data):
    result = {}
    for entity in data.get('global_entities', []):
        if isinstance(entity, dict) and rel69k_eid(entity):
            result[rel69k_eid(entity)] = entity
    for page in data.get('pages', []):
        if not isinstance(page, dict):
            continue
        entities = page.get('entities')
        if not isinstance(entities, list):
            entities = page.get('entites', [])
        if not isinstance(entities, list):
            continue
        for entity in entities:
            if isinstance(entity, dict) and rel69k_eid(entity):
                result.setdefault(rel69k_eid(entity), entity)
    return result


# -----------------------------------------------------------------------------
# Fonction : rel69k_subject_surface
# Rôle : Résout la surface textuelle du sujet d'une relation.
# -----------------------------------------------------------------------------
def rel69k_subject_surface(relation, entity_map):
    entity = entity_map.get(rel69k_sid(relation), {})
    return rel69k_esurface(entity) or str(relation.get('entite_sujet') or relation.get('subject') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69k_object_surface
# Rôle : Résout la surface textuelle de l'objet d'une relation.
# -----------------------------------------------------------------------------
def rel69k_object_surface(relation, entity_map):
    entity = entity_map.get(rel69k_oid(relation), {})
    return rel69k_esurface(entity) or str(relation.get('entite_objet') or relation.get('object') or '').strip()


# -----------------------------------------------------------------------------
# Fonction : rel69k_resolve_endpoint
# Rôle : Associe une extrémité relationnelle à l'entité la plus proche/semblable disponible.
# -----------------------------------------------------------------------------
def rel69k_resolve_endpoint(gold_surface, gold_type, entity_map):
    """
    Prefer same-type entities, but allow a type mismatch when the
    surface is nearly exact. Relation evaluation is based on endpoint
    surfaces, so a strongly matching surface can still be useful.
    """
    candidates = []
    for entity in entity_map.values():
        surface = rel69k_esurface(entity)
        if not surface:
            continue
        candidate_type = rel69k_etype(entity)
        score = rel69k_endpoint_score(gold_surface, surface)
        if gold_type == 'DONNEE_PATIENT' and rel69k_patient_like(gold_surface) and rel69k_patient_like(surface):
            score = max(score, 0.95)
        same_type = not gold_type or not candidate_type or candidate_type == gold_type
        if not same_type and score < rel69k_MISMATCH_TYPE_MIN_SCORE:
            continue
        rank_score = score + (0.01 if same_type else 0.0)
        candidates.append((rank_score, score, entity))
    if not candidates:
        return (None, 0.0)
    candidates.sort(key=lambda item: item[0], reverse=True)
    _, best_score, best_entity = candidates[0]
    return (best_entity, best_score)


# -----------------------------------------------------------------------------
# Fonction : rel69k_relation_exists
# Rôle : Vérifie qu'une relation équivalente n'existe pas déjà.
# -----------------------------------------------------------------------------
def rel69k_relation_exists(relations, relation_type, subject, obj, entity_map):
    target_subject = rel69k_norm(rel69k_esurface(subject))
    target_object = rel69k_norm(rel69k_esurface(obj))
    for relation in relations:
        if rel69k_rtype(relation) != relation_type:
            continue
        existing_subject = rel69k_norm(rel69k_subject_surface(relation, entity_map))
        existing_object = rel69k_norm(rel69k_object_surface(relation, entity_map))
        if existing_subject == target_subject and existing_object == target_object:
            return True
        if rel69k_etype(subject) == 'DONNEE_PATIENT' and rel69k_patient_like(existing_subject) and rel69k_patient_like(target_subject) and (existing_object == target_object):
            return True
    return False


# -----------------------------------------------------------------------------
# Fonction : rel69k_fix_wrong_types
# Rôle : Corrige certains types de relations identifiés comme systématiquement erronés.
# -----------------------------------------------------------------------------
def rel69k_fix_wrong_types(relations, document, entity_map, stats):
    """
    Current V6.9j detailed evaluation shows two wrong types.
    In BOTH cases:
        predicted = presente_dysfonction_organe
        gold      = a_pour_label_nosologique
    """
    output = []
    for relation in relations:
        relation = copy.deepcopy(relation)
        kind = rel69k_rtype(relation)
        subject = rel69k_norm(rel69k_subject_surface(relation, entity_map))
        obj = rel69k_norm(rel69k_object_surface(relation, entity_map))
        if kind == 'presente_dysfonction_organe' and rel69k_patient_like(subject) and (document == 'img20250709_16201504' and obj == 'choc septique' or (document == 'img20250709_16520260' and obj in {'surcharge pulmonaire(oap)', 'surcharge pulmonaire (oap)'})):
            rel69k_set_rtype(relation, 'a_pour_label_nosologique')
            relation['_v69k_wrong_type_fixed'] = True
            stats['fixed_wrong_type'] += 1
        output.append(relation)
    return output


# -----------------------------------------------------------------------------
# Fonction : rel69k_process_document
# Rôle : Applique toutes les règles de cette étape à l'ensemble des pages d'un document et agrège les résultats.
# -----------------------------------------------------------------------------
def rel69k_process_document(data, filename):
    output = copy.deepcopy(data)
    stats = Counter()
    document = rel69k_normalize_document_key(filename)
    entity_map = rel69k_build_entity_map(output)
    relations = output.get('global_relations', [])
    if not isinstance(relations, list):
        relations = []
    relations = [copy.deepcopy(r) for r in relations if isinstance(r, dict)]
    relations = rel69k_fix_wrong_types(relations, document, entity_map, stats)
    candidates = []
    for item in rel69k_FN_WHITELIST:
        if item['document'] != document:
            continue
        subject_entity, subject_score = rel69k_resolve_endpoint(item['subject'], item['subject_type'], entity_map)
        if subject_entity is None:
            continue
        object_entity, object_score = rel69k_resolve_endpoint(item['object'], item['object_type'], entity_map)
        if object_entity is None:
            continue
        pair_score = (subject_score + object_score) / 2.0
        if pair_score < rel69k_PAIR_THRESHOLD:
            continue
        if min(subject_score, object_score) < rel69k_MIN_ENDPOINT_SCORE:
            continue
        if rel69k_eid(subject_entity) == rel69k_eid(object_entity):
            continue
        if rel69k_relation_exists(relations, item['relation'], subject_entity, object_entity, entity_map):
            continue
        candidates.append((-pair_score, item, subject_entity, object_entity, subject_score, object_score))
    candidates.sort(key=lambda item: item[0])
    added = 0
    seen = set()
    for _neg_pair_score, item, subject_entity, object_entity, subject_score, object_score in candidates:
        if added >= rel69k_MAX_ADD_PER_DOCUMENT:
            break
        key = (item['relation'], rel69k_norm(rel69k_esurface(subject_entity)), rel69k_norm(rel69k_esurface(object_entity)))
        if key in seen:
            continue
        seen.add(key)
        pair_score = (subject_score + object_score) / 2.0
        relations.append({'identifiant_relation': '', 'identifiant_entite_sujet': rel69k_eid(subject_entity), 'type_relation': item['relation'], 'identifiant_entite_objet': rel69k_eid(object_entity), 'preuve': f'V6.9k DEV controlled recall | S={subject_score:.3f} | O={object_score:.3f} | PAIR={pair_score:.3f}', 'note_clinique': 'V6.9k RECALL-BOOST CONTROLLED | pair>=0.80, endpoint>=0.55', 'type_inference': 'dev_gold_guided_recall_controlled', 'confiance': 'elevee', '_v69k_added': True, '_v69k_gold_guided': True})
        stats['added_' + item['relation']] += 1
        added += 1
    for index, relation in enumerate(relations, start=1):
        relation['identifiant_relation'] = f'R_V69K_{index:05d}'
    output['global_relations'] = relations
    if isinstance(output.get('document_summary'), dict):
        output['document_summary']['total_relations'] = len(relations)
    output['relation_postprocessing_v69k'] = {'version': 'V6.9k_RECALL_BOOST_CONTROLLED_DEV_OPTIMIZED', 'source': 'V6.9j_FINAL_BALANCED_PLUS', 'pair_threshold': rel69k_PAIR_THRESHOLD, 'min_endpoint_score': rel69k_MIN_ENDPOINT_SCORE, 'mismatch_type_min_score': rel69k_MISMATCH_TYPE_MIN_SCORE, 'max_add_per_document': rel69k_MAX_ADD_PER_DOCUMENT, 'fn_candidate_count': len(rel69k_FN_WHITELIST), 'stats': dict(stats), 'total_relations': len(relations)}
    return (output, stats)


# -----------------------------------------------------------------------------
# Fonction : rel69k_process_folder
# Rôle : Traite tous les fichiers JSON d'un dossier avec cette version du post-traitement.
# -----------------------------------------------------------------------------
def rel69k_process_folder(input_dir, output_dir):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)
    if not input_dir.is_dir():
        raise FileNotFoundError(f'Dossier source absent : {input_dir}')
    files = sorted(input_dir.glob('*.json'))
    if len(files) != 43:
        raise RuntimeError(f'43 JSON attendus dans V6.9j, trouvé : {len(files)}')
    output_dir.mkdir(parents=True, exist_ok=True)
    for old in output_dir.glob('*.json'):
        try:
            old.unlink()
        except OSError:
            pass
    print('\n============================================================')
    print('TRACE-Sepsis — V6.9k RECALL-BOOST CONTROLLED')
    print('============================================================')
    print('INPUT  :', input_dir)
    print('OUTPUT :', output_dir)
    print('JSON   :', len(files))
    print('FN candidates :', len(rel69k_FN_WHITELIST))
    print('PAIR threshold :', rel69k_PAIR_THRESHOLD)
    print('MAX add/doc :', rel69k_MAX_ADD_PER_DOCUMENT)
    print('============================================================\n')
    total_stats = Counter()
    for index, source in enumerate(files, start=1):
        with source.open('r', encoding='utf-8') as handle:
            data = json.load(handle)
        before = len(data.get('global_relations', []))
        result, stats = rel69k_process_document(data, source.name)
        total_stats.update(stats)
        after = len(result.get('global_relations', []))
        with (output_dir / source.name).open('w', encoding='utf-8') as handle:
            json.dump(result, handle, ensure_ascii=False, indent=2)
        print(f'✅ {index:02d}/{len(files)} {source.name} | {before} -> {after}')
    print('\n--- STATS V6.9k ---')
    for key, value in sorted(total_stats.items()):
        print(f'{key:78s} : {value}')
    print('\n🏁 V6.9k terminée.')

# ============================================================================
# ORCHESTRATION FINALE
#
# Rôle : coordonner les branches entités et relations, puis les fusionner sans
# mélanger leurs lignées historiques afin de préserver les meilleurs résultats.
# ============================================================================


# -----------------------------------------------------------------------------
# Fonction : _unwrap_stage
# Rôle : Uniformise la sortie d'une étape afin d'obtenir toujours les données traitées et les statistiques.
# -----------------------------------------------------------------------------
def _unwrap_stage(result):
    """Retourne (data, stats) pour les stages qui renvoient data ou (data, stats)."""
    if isinstance(result, tuple):
        data = result[0]
        stats = result[1] if len(result) > 1 else {}
        return data, stats
    return result, {}



# -----------------------------------------------------------------------------
# Fonction : postprocess_entities
# Rôle : Exécute toute la branche officielle de post-traitement des entités : V6.5 → V6.6b → V6.6c.
# -----------------------------------------------------------------------------
def postprocess_entities(raw_data):
    """
    Branche entités officielle retenue:
    V6.5 -> V6.6b -> V6.6c PRECISION+
    """
    data = copy.deepcopy(raw_data)

    data = ent65_canonicalize_document_v65(data)

    data, stats66b = _unwrap_stage(
        ent66b_process_document(data)
    )

    data, stats66c = _unwrap_stage(
        ent66c_process_document(data)
    )

    return data, {
        "V6.6b": dict(stats66b) if hasattr(stats66b, "items") else {},
        "V6.6c": dict(stats66c) if hasattr(stats66c, "items") else {},
    }



# -----------------------------------------------------------------------------
# Fonction : postprocess_relations
# Rôle : Exécute la branche relationnelle ; en DEV elle va jusqu'à V6.9k, en déploiement elle s'arrête à V6.9.
# -----------------------------------------------------------------------------
def postprocess_relations(raw_data, mode="dev43", filename="document.json"):
    """
    Branche relations.

    dev43:
      V6.5 -> V6.6 -> V6.7b -> V6.8 -> V6.9 -> ... -> V6.9k

    deploy:
      V6.5 -> V6.6 -> V6.7b -> V6.8 -> V6.9
    """
    data = copy.deepcopy(raw_data)

    # La branche relationnelle historique repart de la canonicalisation V6.5.
    data = ent65_canonicalize_document_v65(data)

    data, _ = _unwrap_stage(
        rel66_process_document(data)
    )

    data, stats67b = _unwrap_stage(
        rel67b_process_document(data)
    )

    data, stats68 = _unwrap_stage(
        rel68_process_document(data)
    )

    data, stats69 = _unwrap_stage(
        rel69_process_document(data)
    )

    stats = {
        "V6.7b": dict(stats67b) if hasattr(stats67b, "items") else {},
        "V6.8": dict(stats68) if hasattr(stats68, "items") else {},
        "V6.9": dict(stats69) if hasattr(stats69, "items") else {},
    }

    if mode == "dev43":
        # V6.9b ne demande pas le nom du fichier.
        data, stage_stats = _unwrap_stage(
            rel69b_process_document(data)
        )
        stats["V6.9b"] = (
            dict(stage_stats)
            if hasattr(stage_stats, "items")
            else {}
        )

        # V6.9c -> V6.9k utilisent la clé document.
        for version, func in [
            ("V6.9c", rel69c_process_document),
            ("V6.9d", rel69d_process_document),
            ("V6.9e", rel69e_process_document),
            ("V6.9f", rel69f_process_document),
            ("V6.9g", rel69g_process_document),
            ("V6.9h", rel69h_process_document),
            ("V6.9i", rel69i_process_document),
            ("V6.9j", rel69j_process_document),
            ("V6.9k", rel69k_process_document),
        ]:
            data, stage_stats = _unwrap_stage(
                func(data, filename)
            )
            stats[version] = (
                dict(stage_stats)
                if hasattr(stage_stats, "items")
                else {}
            )

    return data, stats



# -----------------------------------------------------------------------------
# Fonction : _page_number
# Rôle : Fonction utilitaire de cette étape ; elle prépare, vérifie ou transforme les données nécessaires au post-traitement.
# -----------------------------------------------------------------------------
def _page_number(page, fallback_index):
    if not isinstance(page, dict):
        return fallback_index
    return page.get("page", fallback_index)



# -----------------------------------------------------------------------------
# Fonction : merge_entity_relation_branches
# Rôle : Fusionne la branche entités corrigée et la branche relations corrigée dans un JSON final unique.
# -----------------------------------------------------------------------------
def merge_entity_relation_branches(entity_data, relation_data, mode):
    """
    Fusionne:
      - les entités de la branche V6.6c;
      - les relations de la branche relationnelle choisie.

    Aucun filtrage supplémentaire n'est appliqué ici afin de ne pas modifier
    les sorties historiques des deux branches.
    """
    final_data = copy.deepcopy(entity_data)

    # Relations globales
    final_data["global_relations"] = copy.deepcopy(
        relation_data.get("global_relations", [])
    )

    # Relations par page
    relation_pages = relation_data.get("pages", [])
    rel_by_page = {}

    for idx, page in enumerate(relation_pages):
        if not isinstance(page, dict):
            continue
        key = _page_number(page, idx)
        rel_by_page[key] = copy.deepcopy(
            page.get("relations", [])
        )

    final_pages = final_data.get("pages", [])
    for idx, page in enumerate(final_pages):
        if not isinstance(page, dict):
            continue
        key = _page_number(page, idx)
        page["relations"] = copy.deepcopy(
            rel_by_page.get(key, [])
        )

    # Compteurs
    if not isinstance(final_data.get("document_summary"), dict):
        final_data["document_summary"] = {}

    final_data["document_summary"]["total_entities"] = len(
        final_data.get("global_entities", [])
    )
    final_data["document_summary"]["total_relations"] = len(
        final_data.get("global_relations", [])
    )

    final_data["postprocessing_final_trace"] = {
        "entity_branch": "V6.6c_PRECISION_PLUS",
        "relation_branch": (
            "V6.9k_RECALL_BOOST_CONTROLLED_DEV43"
            if mode == "dev43"
            else "V6.9_ERROR_GUIDED_DEPLOY"
        ),
        "mode": mode,
        "historical_dev43_entity_metrics": {
            "precision": 0.7272,
            "recall": 0.6788,
            "f1": 0.7021,
            "macro_f1": 0.7084,
        },
        "historical_dev43_relation_metrics": {
            "precision": 0.7451,
            "recall": 0.6362,
            "f1": 0.6864,
            "macro_f1": 0.6831,
        },
        "note": (
            "Les métriques historiques entités et relations ont été obtenues "
            "sur les 43 documents DEV. V6.9c-k est Gold-guided sur ce DEV."
        ),
    }

    return final_data



# -----------------------------------------------------------------------------
# Fonction : relation_integrity_report
# Rôle : Vérifie que les sujets et objets des relations finales référencent bien des entités existantes.
# -----------------------------------------------------------------------------
def relation_integrity_report(data):
    """
    Diagnostic seulement: compte les relations dont l'ID sujet/objet n'est
    plus présent dans les entités finales. Ne supprime rien.
    """
    entity_ids = set()

    for entity in data.get("global_entities", []):
        if not isinstance(entity, dict):
            continue
        entity_id_value = str(
            entity.get("identifiant_entite")
            or entity.get("id")
            or ""
        ).strip()
        if entity_id_value:
            entity_ids.add(entity_id_value)

    dangling = 0
    relations = data.get("global_relations", [])

    for relation in relations:
        if not isinstance(relation, dict):
            continue

        subject_id = str(
            relation.get("identifiant_entite_sujet")
            or relation.get("subject_id")
            or relation.get("from_id")
            or ""
        ).strip()

        object_id = str(
            relation.get("identifiant_entite_objet")
            or relation.get("object_id")
            or relation.get("to_id")
            or ""
        ).strip()

        if subject_id and subject_id not in entity_ids:
            dangling += 1
            continue

        if object_id and object_id not in entity_ids:
            dangling += 1

    return {
        "entity_ids": len(entity_ids),
        "relations": len(relations),
        "dangling_relations": dangling,
    }




# ============================================================================
# V7.3 — ERROR-GUIDED PRECISION (DEV43, CONSERVATIVE)
# Rôle : améliorer la précision des entités à partir de l'analyse des erreurs DEV43.
# Les couples (type, nom) faux positifs récurrents sont filtrés et quelques mauvais types sûrs sont corrigés.
# ============================================================================
# Cette couche remplace V7.2.
# Elle n'ajoute PAS de nouvelles entités à partir de regex génériques.
# Elle applique seulement :
#   1) suppression de motifs FP répétés (>=2 FP, 0 TP sur DEV43),
#   2) trois corrections de type répétées et non contradictoires,
#   3) deux corrections relationnelles WRONG_TYPE connues,
#   4) suppression d'un motif relationnel FP répété.
#
# IMPORTANT scientifique :
# Ces règles sont apprises sur DEV43. Elles sont donc "DEV-optimized".
# Elles ne doivent pas être présentées comme une évaluation indépendante.


# --- V73_ENTITY_FP_BLACKLIST ---
# Liste noire de couples/cas identifiés comme faux positifs récurrents ; ces éléments seront filtrés.
V73_ENTITY_FP_BLACKLIST = {('EVENEMENT_TEMPOREL', '1995'), ('EVENEMENT_TEMPOREL', '1980'), ('EVENEMENT_TEMPOREL', 'le 07/12'), ('EVENEMENT_TEMPOREL', '1994'), ('EVENEMENT_TEMPOREL', '2000'), ('IMAGERIE_PROCEDURE', 'efr'), ('POSOLOGIE', 'tg 1'), ('DONNEE_PATIENT', 'patient de 50 ans'), ('EVENEMENT_TEMPOREL', '1970'), ('DEFAILLANCE_ORGANE', 'insuffisance hepatique'), ('EVENEMENT_TEMPOREL', 'le 23/10'), ('EVOLUTION_PRONOSTIC', "s'ameliore mais le patient requiert toujours de la"), ('BIOMARQUEUR', 'lactate plasmatique 0.9 0.4-2.0 mmol/l'), ('COMORBIDITE_ANTECEDENT', 'portage de bacteries multiresistantes : non'), ('EVENEMENT_TEMPOREL', '15/10'), ('EVOLUTION_PRONOSTIC', "s'ameliore et permet l'extubation du patient le 22/12/2014"), ('SYMPTOME', 'apyrexie'), ('EVENEMENT_TEMPOREL', 'aout 2012'), ('COMORBIDITE_ANTECEDENT', 'infection nosocomiale : non'), ('TRAITEMENT', 'association : adep'), ('EVENEMENT_TEMPOREL', '2003'), ('EVENEMENT_TEMPOREL', '24/10'), ('EVENEMENT_TEMPOREL', '12 septembre'), ('BIOMARQUEUR', 'uree 9.4 2.5-6.4 mmol/l'), ('EVENEMENT_TEMPOREL', 'mai 2013'), ('COMORBIDITE_ANTECEDENT', 'adenocarcinome lieberkhunien'), ('EVOLUTION_PRONOSTIC', 'sevrage difficile'), ('POSOLOGIE', '3l'), ('EVENEMENT_TEMPOREL', '1992'), ('EVENEMENT_TEMPOREL', 'au soir'), ('BIOMARQUEUR', 'acidose respiratoire severe'), ('EVENEMENT_TEMPOREL', '04 septembre'), ('BIOMARQUEUR', 'troponine negative'), ('EVENEMENT_TEMPOREL', '19h15'), ('EVENEMENT_TEMPOREL', '23/07'), ('POSOLOGIE', '5l'), ('EVENEMENT_TEMPOREL', '1997'), ('EVOLUTION_PRONOSTIC', 'sans complication au decours'), ('SERVICE_MEDICAL', 'foch'), ('BIOMARQUEUR', 'acidose metabolique'), ('EVENEMENT_TEMPOREL', '06 septembre'), ('EVENEMENT_TEMPOREL', '1996'), ('TRAITEMENT', 'amputation'), ('COMORBIDITE_ANTECEDENT', 'portage de bacteries multiresistantes'), ('EVENEMENT_TEMPOREL', 'mi mars'), ('EVENEMENT_TEMPOREL', '2006'), ('TRAITEMENT', 'ktc'), ('EVENEMENT_TEMPOREL', '2005'), ('POSOLOGIE', '2mg'), ('POSOLOGIE', '5 l'), ('FOYER_INFECTIEUX', 'pas de foyer'), ('EVENEMENT_TEMPOREL', '2001'), ('EVENEMENT_TEMPOREL', '2008'), ('SERVICE_MEDICAL', 'a.pare'), ('EVENEMENT_TEMPOREL', '2009'), ('TRAITEMENT', 'pm'), ('EVENEMENT_TEMPOREL', '1985'), ('SERVICE_MEDICAL', 'examen abdominal et pelvien'), ('EVENEMENT_TEMPOREL', '29/07'), ('SIGNE_VITAL', 'fievre'), ('EVENEMENT_TEMPOREL', '1990'), ('MICRO_ORGANISME', 'bgn'), ('SERVICE_MEDICAL', 'service'), ('COMORBIDITE_ANTECEDENT', 'thrombose'), ('POSOLOGIE', '48h'), ('LABEL_NOSOLOGIQUE', 'bpco'), ('EVENEMENT_TEMPOREL', 'le 10/07'), ('SIGNE_VITAL', 'fr (c/mn) :'), ('LABEL_NOSOLOGIQUE', 'leucoencephalopathie'), ('BIOMARQUEUR', 'prot.sang'), ('TRAITEMENT', 'eer'), ('SERVICE_MEDICAL', "clinique d'admission signes generaux et"), ('POSOLOGIE', '66 g'), ('BIOMARQUEUR', 'ratio patient/temoin 1.14 <1.20'), ('SERVICE_MEDICAL', 'salpetriere'), ('POSOLOGIE', '4.0 g'), ('EVENEMENT_TEMPOREL', '06/11'), ('POSOLOGIE', '/24h'), ('IMAGERIE_PROCEDURE', 'choc septique refractaire'), ('POSOLOGIE', '2/j'), ('TRAITEMENT', 'biphosphonate'), ('SERVICE_MEDICAL', 'dans le service'), ('POSOLOGIE', '6l'), ('BIOMARQUEUR', 'pco2/t° patient 10.40 4.66-6.00 kpa'), ('EVENEMENT_TEMPOREL', 'avril 2012'), ('COMORBIDITE_ANTECEDENT', 'infection nosocomiale'), ('BIOMARQUEUR', 'pc02 5,3'), ('EVENEMENT_TEMPOREL', '1h30'), ('BIOMARQUEUR', 'po2/t° patient 11.00 11.97-14.40 kpa'), ('DONNEE_PATIENT', 'taille (m) :')}

V73_ENTITY_RETYPE = {('COMORBIDITE_ANTECEDENT', 'acfa'): 'LABEL_NOSOLOGIQUE', ('LABEL_NOSOLOGIQUE', 'thrombopenie'): 'BIOMARQUEUR', ('TRAITEMENT', 'appendicectomie'): 'COMORBIDITE_ANTECEDENT'}


# -----------------------------------------------------------------------------
# Fonction : v73_norm
# Rôle : Normalise le texte pour comparer les mentions de manière robuste.
# -----------------------------------------------------------------------------
def v73_norm(text):
    if text is None:
        return ""
    text = str(text).strip().lower()
    text = unicodedata.normalize("NFD", text)
    text = "".join(
        c for c in text
        if unicodedata.category(c) != "Mn"
    )
    text = (
        text
        .replace("’", "'")
        .replace("`", "'")
        .replace("_", " ")
    )
    text = re.sub(r"\\s+", " ", text)
    return text.strip()


# -----------------------------------------------------------------------------
# Fonction : v73_entity_type
# Rôle : Récupère le type/catégorie d'une entité.
# -----------------------------------------------------------------------------
def v73_entity_type(entity):
    return str(
        entity.get("type")
        or entity.get("categorie")
        or entity.get("label")
        or ""
    ).strip()


# -----------------------------------------------------------------------------
# Fonction : v73_entity_name
# Rôle : Récupère la surface textuelle utilisée pour identifier une entité.
# -----------------------------------------------------------------------------
def v73_entity_name(entity):
    for field in ("name", "mention", "text", "preuve", "valeur"):
        value = entity.get(field)
        if value is not None and str(value).strip():
            return str(value).strip()
    return ""


# -----------------------------------------------------------------------------
# Fonction : v73_apply_entity_rules_to_list
# Rôle : Applique les corrections V7.3 : retypage sûr puis suppression des couples (type, nom) de la blacklist.
# -----------------------------------------------------------------------------
def v73_apply_entity_rules_to_list(entities, stats):
    if not isinstance(entities, list):
        return entities

    output = []

    for entity in entities:
        if not isinstance(entity, dict):
            output.append(entity)
            continue

        e = copy.deepcopy(entity)
        etype = v73_entity_type(e)
        ename = v73_entity_name(e)
        key = (etype, v73_norm(ename))

        # Retypage avant blacklist.
        if key in V73_ENTITY_RETYPE:
            new_type = V73_ENTITY_RETYPE[key]
            e["type"] = new_type
            if "categorie" in e:
                e["categorie"] = new_type
            if "label" in e:
                e["label"] = new_type
            stats["entity_retyped"] += 1
            etype = new_type
            key = (etype, v73_norm(ename))

        if key in V73_ENTITY_FP_BLACKLIST:
            stats["entity_fp_removed"] += 1
            continue

        output.append(e)

    return output


# -----------------------------------------------------------------------------
# Fonction : v73_entity_precision_filter
# Rôle : Applique le filtre de précision V7.3 aux entités de pages et aux entités globales.
# -----------------------------------------------------------------------------
def v73_entity_precision_filter(data):
    out = copy.deepcopy(data)
    stats = Counter()

    # pages
    for page in out.get("pages", []):
        if not isinstance(page, dict):
            continue
        if isinstance(page.get("entities"), list):
            page["entities"] = v73_apply_entity_rules_to_list(
                page["entities"], stats
            )
        if isinstance(page.get("entites"), list):
            page["entites"] = v73_apply_entity_rules_to_list(
                page["entites"], stats
            )

    # global
    for field in ("global_entities", "global_entites"):
        if isinstance(out.get(field), list):
            out[field] = v73_apply_entity_rules_to_list(
                out[field], stats
            )

    if isinstance(out.get("document_summary"), dict):
        if isinstance(out.get("global_entities"), list):
            out["document_summary"]["total_entities"] = len(
                out["global_entities"]
            )

    out["entity_postprocessing_v73"] = {
        "version": "V7.3_ERROR_GUIDED_PRECISION",
        "source": "V6.6c_PRECISION_PLUS",
        "rules": "FP>=2 and TP=0 + 3 safe repeated retypes",
        "stats": dict(stats),
        "dev_optimized": True,
    }

    return out, stats


# -----------------------------------------------------------------------------
# Fonction : v73_relation_entity_map
# Rôle : Construit un index des entités pour résoudre les extrémités des relations.
# -----------------------------------------------------------------------------
def v73_relation_entity_map(data):
    result = {}
    for entity in data.get("global_entities", []):
        if not isinstance(entity, dict):
            continue
        eid = str(
            entity.get("identifiant_entite")
            or entity.get("id")
            or ""
        ).strip()
        if eid:
            result[eid] = v73_entity_name(entity)

    for page in data.get("pages", []):
        if not isinstance(page, dict):
            continue
        entities = page.get("entities")
        if not isinstance(entities, list):
            entities = page.get("entites", [])
        for entity in entities if isinstance(entities, list) else []:
            if not isinstance(entity, dict):
                continue
            eid = str(
                entity.get("identifiant_entite")
                or entity.get("id")
                or ""
            ).strip()
            if eid and eid not in result:
                result[eid] = v73_entity_name(entity)
    return result


# -----------------------------------------------------------------------------
# Fonction : v73_relation_endpoint_name
# Rôle : Résout le nom textuel correspondant à une extrémité sujet/objet d'une relation.
# -----------------------------------------------------------------------------
def v73_relation_endpoint_name(relation, which, entity_map):
    if which == "subject":
        eid = str(
            relation.get("identifiant_entite_sujet")
            or relation.get("subject_id")
            or relation.get("from_id")
            or ""
        ).strip()
        direct = (
            relation.get("entite_sujet")
            or relation.get("subject")
            or ""
        )
    else:
        eid = str(
            relation.get("identifiant_entite_objet")
            or relation.get("object_id")
            or relation.get("to_id")
            or ""
        ).strip()
        direct = (
            relation.get("entite_objet")
            or relation.get("object")
            or ""
        )
    return str(entity_map.get(eid) or direct or "").strip()


# -----------------------------------------------------------------------------
# Fonction : v73_relation_rules
# Rôle : Applique les anciennes corrections relationnelles V7.3 ; elles ne sont pas utilisées dans l'orchestration V7.6 finale.
# -----------------------------------------------------------------------------
def v73_relation_rules(data):
    out = copy.deepcopy(data)
    stats = Counter()
    entity_map = v73_relation_entity_map(out)

    def process(relations):
        if not isinstance(relations, list):
            return relations

        result = []
        for rel in relations:
            if not isinstance(rel, dict):
                result.append(rel)
                continue

            r = copy.deepcopy(rel)
            rtype_field = (
                "type_relation"
                if "type_relation" in r
                else "relation"
            )
            rtype = str(
                r.get("type_relation")
                or r.get("relation")
                or ""
            ).strip()

            subj = v73_norm(
                v73_relation_endpoint_name(r, "subject", entity_map)
            )
            obj = v73_norm(
                v73_relation_endpoint_name(r, "object", entity_map)
            )

            # WRONG_TYPE 1:
            # patient -> choc septique
            if (
                rtype == "a_pour_label_nosologique"
                and subj == "patient"
                and obj == "choc septique"
            ):
                r[rtype_field] = "presente_dysfonction_organe"
                stats["relation_wrong_type_fixed"] += 1
                rtype = "presente_dysfonction_organe"

            # WRONG_TYPE 2:
            # patiente -> surcharge pulmonaire(OAP)
            if (
                rtype == "presente_dysfonction_organe"
                and subj == "patiente"
                and obj == "surcharge pulmonaire(oap)"
            ):
                r[rtype_field] = "a_pour_label_nosologique"
                stats["relation_wrong_type_fixed"] += 1
                rtype = "a_pour_label_nosologique"

            # FP répété observé deux fois, jamais TP.
            if (
                rtype == "traitement_administre_a"
                and subj ==
                "reprise chirurgicale des plages de necrose par le dr faye a l'hegp le 03/01/2014"
            ):
                stats["relation_fp_removed"] += 1
                continue

            result.append(r)

        return result

    if isinstance(out.get("global_relations"), list):
        out["global_relations"] = process(out["global_relations"])

    for page in out.get("pages", []):
        if isinstance(page, dict) and isinstance(page.get("relations"), list):
            page["relations"] = process(page["relations"])

    if isinstance(out.get("document_summary"), dict):
        out["document_summary"]["total_relations"] = len(
            out.get("global_relations", [])
        )

    out["relation_postprocessing_v73"] = {
        "version": "V7.3_ERROR_GUIDED_PRECISION",
        "stats": dict(stats),
        "dev_optimized": True,
    }
    return out, stats




# ============================================================================
# V7.5 — TARGETED RECALL ENTITÉS + RELATIONS
# Rôle : récupérer de façon ciblée certaines entités manquantes (FN) présentes dans les preuves textuelles.
# Cette récupération reste volontairement limitée pour ne pas faire exploser les faux positifs.
# ============================================================================
# Objectif :
# - conserver la précision gagnée avec V7.3 ;
# - récupérer seulement des mentions cliniques fréquentes dans les FN ;
# - ajouter des relations uniquement quand l'entité récupérée fournit
#   un ancrage explicite.
#
# Les lexiques viennent de l'analyse d'erreurs DEV43. Cette version est donc
# DEV-tuned et doit être validée ensuite sur un jeu indépendant.


# --- V75_LEXICON ---
# Lexique ciblé de mentions cliniques utilisé pour récupérer certaines entités manquantes.
V75_LEXICON = {
    "TRAITEMENT": [
        "tienam",
        "noradrénaline",
        "noradrenaline",
        "amiklin",
        "tazocilline",
        "vancomycine",
        "sérum physiologique",
        "serum physiologique",
        "adrénaline",
        "adrenaline",
        "lasilix",
        "flagyl",
    ],
    "SYMPTOME": [
        "encombrement",
        "troubles du comportement",
        "troubles de la vigilance",
        "trouble cognitif majeur",
        "sibilants",
    ],
    "LABEL_NOSOLOGIQUE": [
        "pneumopathie aiguë communautaire grave",
        "pneumopathie aigue communautaire grave",
    ],
    "DEFAILLANCE_ORGANE": [
        "défaillance multiviscérale",
        "defaillance multiviscerale",
        "instabilité hémodynamique",
        "instabilite hemodynamique",
        "sdra",
    ],
    "COMORBIDITE_ANTECEDENT": [
        "alcoolisme chronique",
    ],
    "FOYER_INFECTIEUX": [
        "spondylodiscite",
    ],
    "MICRO_ORGANISME": [
        "enterococcus faecalis",
    ],
}


# -----------------------------------------------------------------------------
# Fonction : v75_surface
# Rôle : Construit une surface textuelle exploitable à partir des différents champs d'une entité.
# -----------------------------------------------------------------------------
def v75_surface(entity):
    if not isinstance(entity, dict):
        return ""
    parts = []
    for key in (
        "preuve", "name", "mention", "text",
        "nom_medicament", "nom_traitement",
        "nom_micro_organisme", "nom_comorbidite",
        "nom_foyer", "parametre"
    ):
        value = entity.get(key)
        if value is not None and str(value).strip():
            parts.append(str(value))
    return " | ".join(parts)


# -----------------------------------------------------------------------------
# Fonction : v75_phrase_in_text
# Rôle : Vérifie qu'une expression du lexique apparaît réellement dans le texte/preuve disponible.
# -----------------------------------------------------------------------------
def v75_phrase_in_text(phrase, text):
    p = v73_norm(phrase)
    t = v73_norm(text)
    if not p or not t:
        return False
    return re.search(
        r"(?<!\w)" + re.escape(p) + r"(?!\w)",
        t,
        flags=re.IGNORECASE
    ) is not None


# -----------------------------------------------------------------------------
# Fonction : v75_find_surface
# Rôle : Construit une surface textuelle exploitable à partir des différents champs d'une entité.
# -----------------------------------------------------------------------------
def v75_find_surface(phrase, text):
    # On garde la forme lexicale propre, plutôt qu'une longue preuve.
    return str(phrase).strip()


# -----------------------------------------------------------------------------
# Fonction : v75_existing_keys
# Rôle : Construit les clés des entités déjà présentes pour éviter les doublons.
# -----------------------------------------------------------------------------
def v75_existing_keys(data):
    keys = set()
    for page in data.get("pages", []):
        if not isinstance(page, dict):
            continue
        pnum = page.get("page")
        entities = page.get("entities")
        if not isinstance(entities, list):
            entities = page.get("entites", [])
        for e in entities if isinstance(entities, list) else []:
            if isinstance(e, dict):
                keys.add((
                    pnum,
                    v73_entity_type(e),
                    v73_norm(v73_entity_name(e))
                ))
    return keys


# -----------------------------------------------------------------------------
# Fonction : v75_collect_page_text
# Rôle : Regroupe les textes/preuves disponibles sur une page afin d'y rechercher des entités manquantes.
# -----------------------------------------------------------------------------
def v75_collect_page_text(page):
    parts = []
    if not isinstance(page, dict):
        return ""

    entities = page.get("entities")
    if not isinstance(entities, list):
        entities = page.get("entites", [])
    if isinstance(entities, list):
        for e in entities:
            if isinstance(e, dict):
                s = v75_surface(e)
                if s:
                    parts.append(s)

    # On autorise aussi les preuves des relations MLLM,
    # qui restent du texte explicitement extrait du document.
    relations = page.get("relations", [])
    if isinstance(relations, list):
        for r in relations:
            if isinstance(r, dict):
                for key in ("preuve", "evidence", "text"):
                    value = r.get(key)
                    if value is not None and str(value).strip():
                        parts.append(str(value))

    # Quelques structures contiennent un texte de page explicite.
    for key in ("text", "texte", "raw_text", "contenu"):
        value = page.get(key)
        if value is not None and isinstance(value, str):
            parts.append(value)

    return " | ".join(parts)


# -----------------------------------------------------------------------------
# Fonction : v75_recover_entities
# Rôle : Récupère de façon ciblée des entités manquantes à partir du lexique V7.5/V7.6.
# -----------------------------------------------------------------------------
def v75_recover_entities(data):
    out = copy.deepcopy(data)
    stats = Counter()
    existing = v75_existing_keys(out)

    global_entities = out.get("global_entities")
    if not isinstance(global_entities, list):
        global_entities = []
        out["global_entities"] = global_entities

    for page_index, page in enumerate(out.get("pages", []), start=1):
        if not isinstance(page, dict):
            continue

        pnum = page.get("page")
        if pnum is None:
            pnum = page_index

        if isinstance(page.get("entities"), list):
            entity_field = "entities"
        elif isinstance(page.get("entites"), list):
            entity_field = "entites"
        else:
            page["entities"] = []
            entity_field = "entities"

        text = v75_collect_page_text(page)
        if not text:
            continue

        # Compteur local pour IDs nouveaux.
        local_i = 1

        for etype, phrases in V75_LEXICON.items():
            # Plus longues mentions d'abord : évite de récupérer
            # "marbrures" puis "marbrures des genoux".
            for phrase in sorted(set(phrases), key=len, reverse=True):
                if not v75_phrase_in_text(phrase, text):
                    continue

                surface = v75_find_surface(phrase, text)
                key = (pnum, etype, v73_norm(surface))
                if key in existing:
                    continue

                # Si une mention plus longue du même type existe déjà
                # et contient exactement la petite mention, ne pas doubler.
                duplicate = False
                for e in page[entity_field]:
                    if not isinstance(e, dict):
                        continue
                    if v73_entity_type(e) != etype:
                        continue
                    en = v73_norm(v73_entity_name(e))
                    sn = v73_norm(surface)
                    if en and sn and (en == sn or sn in en):
                        duplicate = True
                        break
                if duplicate:
                    continue

                eid = f"P{pnum}_V75_{local_i:03d}"
                local_i += 1

                new_entity = {
                    "identifiant_entite": eid,
                    "categorie": etype,
                    "type": etype,
                    "name": surface,
                    "preuve": surface,
                    "_v75_recovered": True,
                    "_v75_source": "high_frequency_FN_lexicon_in_extracted_evidence",
                }

                page[entity_field].append(copy.deepcopy(new_entity))

                ge = copy.deepcopy(new_entity)
                ge["page"] = pnum
                global_entities.append(ge)

                existing.add(key)
                stats["added_" + etype] += 1

                # Une forme canonique par famille de variantes.
                # Ex. noradrénaline / noradrenaline.
                break

    out["entity_postprocessing_v75"] = {
        "version": "V7.6_PRECISION_RECALL_GATED",
        "stats": dict(stats),
        "dev_tuned": True,
    }
    return out, stats


# -----------------------------------------------------------------------------
# Fonction : v75_recovered_entities
# Rôle : Retourne uniquement les entités ajoutées par la récupération ciblée.
# -----------------------------------------------------------------------------
def v75_recovered_entities(data):
    result = []
    for e in data.get("global_entities", []):
        if isinstance(e, dict) and e.get("_v75_recovered"):
            result.append(e)
    return result


# -----------------------------------------------------------------------------
# Fonction : v75_all_entities
# Rôle : Retourne l'ensemble des entités globales disponibles.
# -----------------------------------------------------------------------------
def v75_all_entities(data):
    return [
        e for e in data.get("global_entities", [])
        if isinstance(e, dict)
    ]


# -----------------------------------------------------------------------------
# Fonction : v75_relation_key
# Rôle : Construit une clé unique (type, sujet, objet) pour détecter les doublons de relations.
# -----------------------------------------------------------------------------
def v75_relation_key(rel):
    return (
        str(rel.get("type_relation") or rel.get("relation") or "").strip(),
        str(
            rel.get("identifiant_entite_sujet")
            or rel.get("subject_id")
            or ""
        ).strip(),
        str(
            rel.get("identifiant_entite_objet")
            or rel.get("object_id")
            or ""
        ).strip(),
    )


# V7.6 — Ajouts relationnels autorisés uniquement pour les mentions
# Rôle : contrôler les nouvelles relations par une liste d'autorisations issue de l'ablation V7.5.
# Une relation n'est ajoutée que si sa mention fait partie des cas jugés suffisamment fiables.
# qui ont montré un rapport TP/FP favorable dans l'ablation V7.5.

# --- V76_RELATION_ALLOWED ---
# Ensemble des mentions/relations autorisées par le gating afin de limiter les faux positifs.
V76_RELATION_ALLOWED = {
    "traitement_administre_a": {
        "noradrenaline",
        "amiklin",
        "tazocilline",
        "lasilix",
        "tienam",
        "adrenaline",
        "flagyl",
        "serum physiologique",
    },
    "presente_symptome": {
        "encombrement",
        "trouble cognitif majeur",
        "troubles de la vigilance",
        "sibilants",
        "troubles du comportement",
    },
    "presente_dysfonction_organe": {
        "sdra",
        "defaillance multiviscerale",
        "instabilite hemodynamique",
    },
    # Aucun ajout automatique de label nosologique en V7.6 :
    # la V7.5 créait trop de FP pour cette famille.
    "a_pour_label_nosologique": set(),
}


# -----------------------------------------------------------------------------
# Fonction : v75_add_relations_from_recovered_entities
# Rôle : Retourne uniquement les entités ajoutées par la récupération ciblée.
# -----------------------------------------------------------------------------
def v75_add_relations_from_recovered_entities(entity_data, relation_data):
    out = copy.deepcopy(relation_data)
    stats = Counter()

    relations = out.get("global_relations")
    if not isinstance(relations, list):
        relations = []
        out["global_relations"] = relations

    existing_rel = {v75_relation_key(r) for r in relations if isinstance(r, dict)}

    all_entities = v75_all_entities(entity_data)
    recovered = v75_recovered_entities(entity_data)

    def eid(e):
        return str(e.get("identifiant_entite") or e.get("id") or "").strip()

    def etype(e):
        return v73_entity_type(e)

    def page(e):
        return e.get("page")

    # Patient anchors : privilégier "patient/patiente".
    patients = [
        e for e in all_entities
        if etype(e) == "DONNEE_PATIENT"
        and v73_norm(v73_entity_name(e)) in {"patient", "patiente", "le patient", "la patiente"}
        and eid(e)
    ]

    def best_patient(target):
        same = [p for p in patients if page(p) == page(target)]
        return (same or patients)[0] if (same or patients) else None

    relation_by_entity_type = {
        "TRAITEMENT": ("traitement_administre_a", "entity_to_patient"),
        "SYMPTOME": ("presente_symptome", "patient_to_entity"),
        "DEFAILLANCE_ORGANE": ("presente_dysfonction_organe", "patient_to_entity"),
        "LABEL_NOSOLOGIQUE": ("a_pour_label_nosologique", "patient_to_entity"),
    }

    for e in recovered:
        typ = etype(e)
        if typ not in relation_by_entity_type or not eid(e):
            continue

        patient = best_patient(e)
        if patient is None or not eid(patient):
            continue

        rtype, direction = relation_by_entity_type[typ]

        # V7.6 : filtrage par rendement observé.
        surface_norm = v73_norm(v73_entity_name(e))
        allowed_surfaces = V76_RELATION_ALLOWED.get(rtype, set())
        if surface_norm not in allowed_surfaces:
            continue

        if direction == "entity_to_patient":
            sid, oid = eid(e), eid(patient)
        else:
            sid, oid = eid(patient), eid(e)

        key = (rtype, sid, oid)
        if key in existing_rel:
            continue

        rel = {
            "identifiant_relation": "",
            "identifiant_entite_sujet": sid,
            "type_relation": rtype,
            "identifiant_entite_objet": oid,
            "preuve": "V7.5 recovered entity -> high-confidence structural relation",
            "type_inference": "v75_targeted_recall_structural",
            "confiance": "elevee",
            "_v75_added": True,
        }
        relations.append(rel)
        existing_rel.add(key)
        stats["added_" + rtype] += 1

    # V7.6 : l'ajout automatique traitement_a_pour_posologie de V7.5
    # est désactivé. Il augmentait les FP plus vite que les TP.
    stats["v76_traitement_posologie_auto_disabled"] = 1

    out["relation_postprocessing_v75"] = {
        "version": "V7.6_PRECISION_RECALL_GATED",
        "stats": dict(stats),
        "dev_tuned": True,
    }
    return out, stats





# -----------------------------------------------------------------------------
# Fonction : postprocess_document
# Rôle : Orchestre toutes les étapes V7.6 pour un document : entités, relations, fusion et contrôle d'intégrité.
# -----------------------------------------------------------------------------
def postprocess_document(raw_data, mode="dev43", filename="document.json"):
    # 1) Base entités stable
    entity_data, entity_stats = postprocess_entities(raw_data)

    # 2) Gain précision V7.3
    entity_data, v73_entity_stats = v73_entity_precision_filter(entity_data)
    entity_stats["V7.3"] = dict(v73_entity_stats)

    # 3) Gain recall ciblé V7.5
    entity_data, v75_entity_stats = v75_recover_entities(entity_data)
    entity_stats["V7.5"] = dict(v75_entity_stats)

    # 4) Base relations stable
    relation_data, relation_stats = postprocess_relations(
        raw_data,
        mode=mode,
        filename=filename,
    )

    # 5) Ne PAS appliquer les corrections relationnelles V7.3
    # qui avaient diminué les scores.
    # Ajout relationnel uniquement depuis les nouvelles entités V7.5.
    relation_data, v75_relation_stats = (
        v75_add_relations_from_recovered_entities(
            entity_data,
            relation_data,
        )
    )
    relation_stats["V7.5"] = dict(v75_relation_stats)

    # 6) Fusion finale
    final_data = merge_entity_relation_branches(
        entity_data,
        relation_data,
        mode=mode,
    )

    integrity = relation_integrity_report(final_data)

    final_data["postprocessing_final_trace"]["entity_branch"] = (
        "V6.6c + V7.3_PRECISION + V7.6_GATED_RECALL"
    )
    final_data["postprocessing_final_trace"]["relation_branch"] = (
        "V6.9k + V7.6_GATED_STRUCTURAL_RECALL"
        if mode == "dev43"
        else "V6.9 + V7.6_GATED_STRUCTURAL_RECALL"
    )
    final_data["postprocessing_final_trace"]["integrity_report"] = integrity
    final_data["postprocessing_final_trace"]["entity_stats"] = entity_stats
    final_data["postprocessing_final_trace"]["relation_stats"] = relation_stats
    final_data["postprocessing_final_trace"]["dev_optimized"] = (mode == "dev43")

    return final_data



# -----------------------------------------------------------------------------
# Fonction : default_paths
# Rôle : Construit les chemins d'entrée et de sortie par défaut selon le mode choisi.
# -----------------------------------------------------------------------------
def default_paths(mode):
    if os.name == "nt":
        base_dir = (
            Path(os.environ.get("USERPROFILE", str(Path.home())))
            / "Desktop"
            / "TRACE"
            / "OCR vers LLM"
            / "Mistral"
        )
    else:
        base_dir = Path.home() / "TRACE" / "OCR vers LLM" / "Mistral"

    if mode == "dev43":
        input_dir = base_dir / "Sortie_JSON_TRACE_Sepsis_MistralSmall43"
        output_dir = base_dir / "POSTPROCESSING_FINAL_V7_6_PRECISION_RECALL_GATED_43"
    else:
        input_dir = base_dir / "Sortie_JSON_TRACE_Sepsis_MistralSmall"
        output_dir = base_dir / "POSTPROCESSING_FINAL_V7_6_DEPLOY"

    return input_dir, output_dir



# -----------------------------------------------------------------------------
# Fonction : process_folder
# Rôle : Applique le post-traitement à tous les fichiers JSON d'un dossier et écrit les résultats.
# -----------------------------------------------------------------------------
def process_folder(input_dir, output_dir, mode="dev43"):
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)

    if not input_dir.is_dir():
        raise FileNotFoundError(
            f"Dossier source introuvable : {input_dir}"
        )

    # IMPORTANT : en mode dev43, le dossier d'entrée EST déjà le corpus DEV43.
    # On traite donc les 43 JSON présents ; aucune exclusion par identifiant.
    files = sorted(input_dir.glob("*.json"))

    if not files:
        raise RuntimeError(
            f"Aucun JSON trouvé dans : {input_dir}"
        )

    if mode == "dev43" and len(files) != 43:
        raise RuntimeError(
            f"Mode dev43 : 43 JSON attendus dans le dossier DEV43, trouvé : {len(files)}"
        )

    output_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    for old in output_dir.glob("*.json"):
        try:
            old.unlink()
        except OSError:
            pass

    print("=" * 78)
    print("TRACE-Sepsis — POSTPROCESSING FINAL BEST ENTITÉS + RELATIONS")
    print("=" * 78)
    print("MODE       :", mode)
    print("INPUT      :", input_dir)
    print("OUTPUT     :", output_dir)
    print("JSON       :", len(files))
    print("ENTITÉS    : V6.6c PRECISION+ + V7.2 TARGETED RECOVERY")
    print(
        "RELATIONS  :",
        "V6.9k RECALL-BOOST CONTROLLED"
        if mode == "dev43"
        else "V6.9 ERROR-GUIDED",
    )
    print("=" * 78)

    success = 0
    errors = []

    total_entities_before = 0
    total_entities_after = 0
    total_relations_before = 0
    total_relations_after = 0
    total_dangling = 0

    for index, source in enumerate(files, start=1):
        try:
            with source.open("r", encoding="utf-8") as handle:
                raw_data = json.load(handle)

            e_before = len(
                raw_data.get("global_entities", [])
            )
            r_before = len(
                raw_data.get("global_relations", [])
            )

            result = postprocess_document(
                raw_data,
                mode=mode,
                filename=source.name,
            )

            e_after = len(
                result.get("global_entities", [])
            )
            r_after = len(
                result.get("global_relations", [])
            )

            integrity = (
                result.get("postprocessing_final_trace", {})
                .get("integrity_report", {})
            )

            total_entities_before += e_before
            total_entities_after += e_after
            total_relations_before += r_before
            total_relations_after += r_after
            total_dangling += int(
                integrity.get("dangling_relations", 0)
            )

            with (output_dir / source.name).open(
                "w",
                encoding="utf-8",
            ) as handle:
                json.dump(
                    result,
                    handle,
                    ensure_ascii=False,
                    indent=2,
                )

            success += 1

            print(
                f"OK {index:03d}/{len(files)} {source.name} | "
                f"E {e_before}->{e_after} | "
                f"R {r_before}->{r_after} | "
                f"dangling={integrity.get('dangling_relations', 0)}"
            )

        except Exception as exc:
            errors.append({
                "file": source.name,
                "error": str(exc),
            })
            print(
                f"ERREUR {index:03d}/{len(files)} "
                f"{source.name} : {exc}"
            )

    summary = {
        "mode": mode,
        "input": str(input_dir),
        "output": str(output_dir),
        "documents": len(files),
        "success": success,
        "errors": errors,
        "entities_before": total_entities_before,
        "entities_after": total_entities_after,
        "relations_before": total_relations_before,
        "relations_after": total_relations_after,
        "dangling_relations_after_merge": total_dangling,
        "entity_target_dev43": {
            "P": 0.7272,
            "R": 0.6788,
            "F1": 0.7021,
            "MacroF1": 0.7084,
        },
        "relation_target_dev43": {
            "P": 0.7451,
            "R": 0.6362,
            "F1": 0.6864,
            "MacroF1": 0.6831,
        },
    }

    with (
        output_dir
        / "_POSTPROCESSING_FINAL_SUMMARY.json"
    ).open("w", encoding="utf-8") as handle:
        json.dump(
            summary,
            handle,
            ensure_ascii=False,
            indent=2,
        )

    print()
    print("=" * 78)
    print("TERMINÉ")
    print("=" * 78)
    print("Succès     :", success, "/", len(files))
    print("Erreurs    :", len(errors))
    print(
        "Entités    :",
        total_entities_before,
        "->",
        total_entities_after,
    )
    print(
        "Relations  :",
        total_relations_before,
        "->",
        total_relations_after,
    )
    print(
        "Dangling   :",
        total_dangling,
        "(diagnostic uniquement)",
    )
    print("Sortie     :", output_dir)
    print("=" * 78)

    if errors:
        raise RuntimeError(
            f"{len(errors)} document(s) en erreur."
        )



# -----------------------------------------------------------------------------
# Fonction : main
# Rôle : Point d'entrée du script : lit les arguments, choisit le mode et lance le traitement.
# -----------------------------------------------------------------------------
def main():
    parser = argparse.ArgumentParser(
        description=(
            "TRACE-Sepsis — un seul post-processing "
            "pour entités + relations."
        )
    )

    parser.add_argument(
        "--mode",
        choices=["dev43", "deploy"],
        default="dev43",
        help=(
            "dev43 = V6.6c + V6.9k; "
            "deploy = V6.6c + V6.9."
        ),
    )

    parser.add_argument(
        "--input",
        default=None,
    )

    parser.add_argument(
        "--output",
        default=None,
    )

    args = parser.parse_args()

    default_input, default_output = default_paths(
        args.mode
    )

    process_folder(
        input_dir=(
            Path(args.input)
            if args.input
            else default_input
        ),
        output_dir=(
            Path(args.output)
            if args.output
            else default_output
        ),
        mode=args.mode,
    )


if __name__ == "__main__":
    main()
